var verses = {
    "2CO.5.17": "إِذًا إِنْ كَانَ أَحَدٌ فِي ٱلْمَسِيحِ فَهُوَ خَلِيقَةٌ جَدِيدَةٌ: ٱلْأَشْيَاءُ ٱلْعَتِيقَةُ قَدْ مَضَتْ، هُوَذَا ٱلْكُلُّ قَدْ صَارَ جَدِيدًا.",
    "COL.3.1-2": "فَإِنْ كُنْتُمْ قَدْ قُمْتُمْ مَعَ ٱلْمَسِيحِ فَٱطْلُبُوا مَا فَوْقُ، حَيْثُ ٱلْمَسِيحُ جَالِسٌ عَنْ يَمِينِ ٱللهِ. ٱهْتَمُّوا بِمَا فَوْقُ لَا بِمَا عَلَى ٱلْأَرْضِ،",
    "ISA.43.2": "إِذَا ٱجْتَزْتَ فِي ٱلْمِيَاهِ فَأَنَا مَعَكَ، وَفِي ٱلْأَنْهَارِ فَلَا تَغْمُرُكَ. إِذَا مَشَيْتَ فِي ٱلنَّارِ فَلَا تُلْذَعُ، وَٱللَّهِيبُ لَا يُحْرِقُكَ.",
    "PSA.34.8": "ذُوقُوا وَٱنْظُرُوا مَا أَطْيَبَ ٱلرَّبَّ! طُوبَى لِلرَّجُلِ ٱلْمُتَوَكِّلِ عَلَيْهِ.",
    "ROM.15.4": "لِأَنَّ كُلَّ مَا سَبَقَ فَكُتِبَ كُتِبَ لِأَجْلِ تَعْلِيمِنَا، حَتَّى بِٱلصَّبْرِ وَٱلتَّعْزِيَةِ بِمَا فِي ٱلْكُتُبِ يَكُونُ لَنَا رَجَاءٌ.",
    "PSA.55.22": "أَلْقِ عَلَى ٱلرَّبِّ هَمَّكَ فَهُوَ يَعُولُكَ. لَا يَدَعُ ٱلصِّدِّيقَ يَتَزَعْزَعُ إِلَى ٱلْأَبَدِ.",
    "ISA.40.8": "يَبِسَ ٱلْعُشْبُ، ذَبُلَ ٱلزَّهْرُ. وَأَمَّا كَلِمَةُ إِلَهِنَا فَتَثْبُتُ إِلَى ٱلْأَبَدِ».",
    "PSA.127.1": "إِنْ لَمْ يَبْنِ ٱلرَّبُّ ٱلْبَيْتَ، فَبَاطِلًا يَتْعَبُ ٱلْبَنَّاؤُونَ. إِنْ لَمْ يَحْفَظِ ٱلرَّبُّ ٱلْمَدِينَةَ، فَبَاطِلًا يَسْهَرُ ٱلْحَارِسُ.",
    "ISA.53.6": "كُلُّنَا كَغَنَمٍ ضَلَلْنَا. مِلْنَا كُلُّ وَاحِدٍ إِلَى طَرِيقِهِ، وَٱلرَّبُّ وَضَعَ عَلَيْهِ إِثْمَ جَمِيعِنَا.",
    "PSA.42.1-2": "كَمَا يَشْتَاقُ ٱلْإِيَّلُ إِلَى جَدَاوِلِ ٱلْمِيَاهِ، هَكَذَا تَشْتَاقُ نَفْسِي إِلَيْكَ يَا ٱللهُ. عَطِشَتْ نَفْسِي إِلَى ٱللهِ، إِلَى ٱلْإِلَهِ ٱلْحَيِّ. مَتَى أَجِيءُ وَأَتَرَاءَى قُدَّامَ ٱللهِ؟",
    "2SA.22.31": "ٱللهُ طَرِيقُهُ كَامِلٌ، وَقَوْلُ ٱلرَّبِّ نَقِيٌّ. تُرْسٌ هُوَ لِجَمِيعِ ٱلْمُحْتَمِينَ بِهِ.",
    "PSA.40.1-3": "اِنْتِظَارًا ٱنْتَظَرْتُ ٱلرَّبَّ، فَمَالَ إِلَيَّ وَسَمِعَ صُرَاخِي، وَأَصْعَدَنِي مِنْ جُبِّ ٱلْهَلَاكِ، مِنْ طِينِ ٱلْحَمْأَةِ، وَأَقَامَ عَلَى صَخْرَةٍ رِجْلَيَّ. ثَبَّتَ خُطُوَاتِي، وَجَعَلَ فِي فَمِي تَرْنِيمَةً جَدِيدَةً، تَسْبِيحَةً لِإِلَهِنَا. كَثِيرُونَ يَرَوْنَ وَيَخَافُونَ وَيَتَوَكَّلُونَ عَلَى ٱلرَّبِّ.",
    "JOB.19.25": "أَمَّا أَنَا فَقَدْ عَلِمْتُ أَنَّ وَلِيِّي حَيٌّ، وَٱلْآخِرَ عَلَى ٱلْأَرْضِ يَقُومُ،",
    "PSA.23.1-3": "ٱلرَّبُّ رَاعِيَّ فَلَا يُعْوِزُنِي شَيْءٌ. فِي مَرَاعٍ خُضْرٍ يُرْبِضُنِي. إِلَى مِيَاهِ ٱلرَّاحَةِ يُورِدُنِي. يَرُدُّ نَفْسِي. يَهْدِينِي إِلَى سُبُلِ ٱلْبِرِّ مِنْ أَجْلِ ٱسْمِهِ.",
    "MAT.5.44": "وَأَمَّا أَنَا فَأَقُولُ لَكُمْ: أَحِبُّوا أَعْدَاءَكُمْ. بَارِكُوا لَاعِنِيكُمْ. أَحْسِنُوا إِلَى مُبْغِضِيكُمْ، وَصَلُّوا لِأَجْلِ ٱلَّذِينَ يُسِيئُونَ إِلَيْكُمْ وَيَطْرُدُونَكُمْ،",
    "ISA.55.8-9": "«لِأَنَّ أَفْكَارِي لَيْسَتْ أَفْكَارَكُمْ، وَلَا طُرُقُكُمْ طُرُقِي، يَقُولُ ٱلرَّبُّ. لِأَنَّهُ كَمَا عَلَتِ ٱلسَّمَاوَاتُ عَنِ ٱلْأَرْضِ، هَكَذَا عَلَتْ طُرُقِي عَنْ طُرُقِكُمْ وَأَفْكَارِي عَنْ أَفْكَارِكُمْ.",
    "LUK.19.10": "لِأَنَّ ٱبْنَ ٱلْإِنْسَانِ قَدْ جَاءَ لِكَيْ يَطْلُبَ وَيُخَلِّصَ مَا قَدْ هَلَكَ».",
    "HEB.13.5-6": "لِتَكُنْ سِيرَتُكُمْ خَالِيَةً مِنْ مَحَبَّةِ ٱلْمَالِ. كُونُوا مُكْتَفِينَ بِمَا عِنْدَكُمْ، لِأَنَّهُ قَالَ: «لَا أُهْمِلُكَ وَلَا أَتْرُكُكَ»، حَتَّى إِنَّنَا نَقُولُ وَاثِقِينَ: «ٱلرَّبُّ مُعِينٌ لِي فَلَا أَخَافُ. مَاذَا يَصْنَعُ بِي إِنْسَانٌ؟».",
    "1CH.29.11": "لَكَ يَارَبُّ ٱلْعَظَمَةُ وَٱلْجَبَرُوتُ وَٱلْجَلَالُ وَٱلْبَهَاءُ وَٱلْمَجْدُ، لِأَنَّ لَكَ كُلَّ مَا فِي ٱلسَّمَاءِ وَٱلْأَرْضِ. لَكَ يَارَبُّ ٱلْمُلْكُ، وَقَدِ ٱرْتَفَعْتَ رَأْسًا عَلَى ٱلْجَمِيعِ.",
    "HEB.13.20-21": "وَإِلَهُ ٱلسَّلَامِ ٱلَّذِي أَقَامَ مِنَ ٱلْأَمْوَاتِ رَاعِيَ ٱلْخِرَافِ ٱلْعَظِيمَ، رَبَّنَا يَسُوعَ، بِدَمِ ٱلْعَهْدِ ٱلْأَبَدِيِّ، لِيُكَمِّلْكُمْ فِي كُلِّ عَمَلٍ صَالِحٍ لِتَصْنَعُوا مَشِيئَتَهُ، عَامِلًا فِيكُمْ مَا يُرْضِي أَمَامَهُ بِيَسُوعَ ٱلْمَسِيحِ، ٱلَّذِي لَهُ ٱلْمَجْدُ إِلَى أَبَدِ ٱلْآبِدِينَ. آمِينَ.",
    "1CO.1.18": "فَإِنَّ كَلِمَةَ ٱلصَّلِيبِ عِنْدَ ٱلْهَالِكِينَ جَهَالَةٌ، وَأَمَّا عِنْدَنَا نَحْنُ ٱلْمُخَلَّصِينَ فَهِيَ قُوَّةُ ٱللهِ،",
    "MAT.5.14-16": "أَنْتُمْ نُورُ ٱلْعَالَمِ. لَا يُمْكِنُ أَنْ تُخْفَى مَدِينَةٌ مَوْضُوعَةٌ عَلَى جَبَلٍ، وَلَا يُوقِدُونَ سِرَاجًا وَيَضَعُونَهُ تَحْتَ ٱلْمِكْيَالِ، بَلْ عَلَى ٱلْمَنَارَةِ فَيُضِيءُ لِجَمِيعِ ٱلَّذِينَ فِي ٱلْبَيْتِ. فَلْيُضِئْ نُورُكُمْ هَكَذَا قُدَّامَ ٱلنَّاسِ، لِكَيْ يَرَوْا أَعْمَالَكُمُ ٱلْحَسَنَةَ، وَيُمَجِّدُوا أَبَاكُمُ ٱلَّذِي فِي ٱلسَّمَاوَاتِ.",
    "COL.3.23-24": "وَكُلُّ مَا فَعَلْتُمْ، فَٱعْمَلُوا مِنَ ٱلْقَلْبِ، كَمَا لِلرَّبِّ لَيْسَ لِلنَّاسِ، عَالِمِينَ أَنَّكُمْ مِنَ ٱلرَّبِّ سَتَأْخُذُونَ جَزَاءَ ٱلْمِيرَاثِ، لِأَنَّكُمْ تَخْدِمُونَ ٱلرَّبَّ ٱلْمَسِيحَ.",
    "ROM.8.28": "وَنَحْنُ نَعْلَمُ أَنَّ كُلَّ ٱلْأَشْيَاءِ تَعْمَلُ مَعًا لِلْخَيْرِ لِلَّذِينَ يُحِبُّونَ ٱللهَ، ٱلَّذِينَ هُمْ مَدْعُوُّونَ حَسَبَ قَصْدِهِ.",
    "JHN.11.25-26": "قَالَ لَهَا يَسُوعُ: «أَنَا هُوَ ٱلْقِيَامَةُ وَٱلْحَيَاةُ. مَنْ آمَنَ بِي وَلَوْ مَاتَ فَسَيَحْيَا، وَكُلُّ مَنْ كَانَ حَيًّا وَآمَنَ بِي فَلَنْ يَمُوتَ إِلَى ٱلْأَبَدِ. أَتُؤْمِنِينَ بِهَذَا؟».",
    "1CO.13.6-7": "وَلَا تَفْرَحُ بِٱلْإِثْمِ بَلْ تَفْرَحُ بِٱلْحَقِّ، وَتَحْتَمِلُ كُلَّ شَيْءٍ، وَتُصَدِّقُ كُلَّ شَيْءٍ، وَتَرْجُو كُلَّ شَيْءٍ، وَتَصْبِرُ عَلَى كُلِّ شَيْءٍ.",
    "MAT.7.12": "فَكُلُّ مَا تُرِيدُونَ أَنْ يَفْعَلَ ٱلنَّاسُ بِكُمُ ٱفْعَلُوا هَكَذَا أَنْتُمْ أَيْضًا بِهِمْ، لِأَنَّ هَذَا هُوَ ٱلنَّامُوسُ وَٱلْأَنْبِيَاءُ.",
    "PSA.91.11": "لِأَنَّهُ يُوصِي مَلَائِكَتَهُ بِكَ لِكَيْ يَحْفَظُوكَ فِي كُلِّ طُرُقِكَ.",
    "ACT.2.38": "فَقَالَ لَهُمْ بُطْرُسُ: «تُوبُوا وَلْيَعْتَمِدْ كُلُّ وَاحِدٍ مِنْكُمْ عَلَى ٱسْمِ يَسُوعَ ٱلْمَسِيحِ لِغُفْرَانِ ٱلْخَطَايَا، فَتَقْبَلُوا عَطِيَّةَ ٱلرُّوحِ ٱلْقُدُسِ.",
    "1CO.3.16": "أَمَا تَعْلَمُونَ أَنَّكُمْ هَيْكَلُ ٱللهِ، وَرُوحُ ٱللهِ يَسْكُنُ فِيكُمْ؟",
    "ROM.3.23-24": "إِذِ ٱلْجَمِيعُ أَخْطَأُوا وَأَعْوَزَهُمْ مَجْدُ ٱللهِ، مُتَبَرِّرِينَ مَجَّانًا بِنِعْمَتِهِ بِٱلْفِدَاءِ ٱلَّذِي بِيَسُوعَ ٱلْمَسِيحِ،",
    "MAT.5.6": "طُوبَى لِلْجِيَاعِ وَٱلْعِطَاشِ إِلَى ٱلْبِرِّ، لِأَنَّهُمْ يُشْبَعُونَ.",
    "ISA.26.3": "ذُو ٱلرَّأْيِ ٱلْمُمَكَّنِ تَحْفَظُهُ سَالِمًا سَالِمًا، لِأَنَّهُ عَلَيْكَ مُتَوَكِّلٌ.",
    "PRO.17.22": "ٱلْقَلْبُ ٱلْفَرْحَانُ يُطَيِّبُ ٱلْجِسْمَ، وَٱلرُّوحُ ٱلْمُنْسَحِقَةُ تُجَفِّفُ ٱلْعَظْمَ.",
    "NEH.8.10": "فَقَالَ لَهُمُ: «ٱذْهَبُوا كُلُوا ٱلسَّمِينَ، وَٱشْرَبُوا ٱلْحُلْوَ، وَٱبْعَثُوا أَنْصِبَةً لِمَنْ لَمْ يُعَدَّ لَهُ، لِأَنَّ ٱلْيَوْمَ إِنَّمَا هُوَ مُقَدَّسٌ لِسَيِّدِنَا. وَلَا تَحْزَنُوا، لِأَنَّ فَرَحَ ٱلرَّبِّ هُوَ قُوَّتُكُمْ».",
    "1PE.2.9": "وَأَمَّا أَنْتُمْ فَجِنْسٌ مُخْتَارٌ، وَكَهَنُوتٌ مُلُوكِيٌّ، أُمَّةٌ مُقَدَّسَةٌ، شَعْبُ ٱقْتِنَاءٍ، لِكَيْ تُخْبِرُوا بِفَضَائِلِ ٱلَّذِي دَعَاكُمْ مِنَ ٱلظُّلْمَةِ إِلَى نُورِهِ ٱلْعَجِيبِ.",
    "PSA.18.2": "ٱلرَّبُّ صَخْرَتِي وَحِصْنِي وَمُنْقِذِي. إِلَهِي صَخْرَتِي بِهِ أَحْتَمِي. تُرْسِي وَقَرْنُ خَلَاصِي وَمَلْجَإِي.",
    "1CO.15.58": "إِذًا يَا إِخْوَتِي ٱلْأَحِبَّاءَ، كُونُوا رَاسِخِينَ، غَيْرَ مُتَزَعْزِعِينَ، مُكْثِرِينَ فِي عَمَلِ ٱلرَّبِّ كُلَّ حِينٍ، عَالِمِينَ أَنَّ تَعَبَكُمْ لَيْسَ بَاطِلًا فِي ٱلرَّبِّ.",
    "EXO.14.14": "ٱلرَّبُّ يُقَاتِلُ عَنْكُمْ وَأَنْتُمْ تَصْمُتُونَ».",
    "2CH.15.7": "فَتَشَدَّدُوا أَنْتُمْ وَلَا تَرْتَخِ أَيْدِيكُمْ لِأَنَّ لِعَمَلِكُمْ أَجْرًا».",
    "PHP.4.11-12": "لَيْسَ أَنِّي أَقُولُ مِنْ جِهَةِ ٱحْتِيَاجٍ، فَإِنِّي قَدْ تَعَلَّمْتُ أَنْ أَكُونَ مُكْتَفِيًا بِمَا أَنَا فِيهِ. أَعْرِفُ أَنْ أَتَّضِعَ وَأَعْرِفُ أَيْضًا أَنْ أَسْتَفْضِلَ. فِي كُلِّ شَيْءٍ وَفِي جَمِيعِ ٱلْأَشْيَاءِ قَدْ تَدَرَّبْتُ أَنْ أَشْبَعَ وَأَنْ أَجُوعَ، وَأَنْ أَسْتَفْضِلَ وَأَنْ أَنْقُصَ.",
    "ISA.58.11": "وَيَقُودُكَ ٱلرَّبُّ عَلَى ٱلدَّوَامِ، وَيُشْبِعُ فِي ٱلْجَدُوبِ نَفْسَكَ، وَيُنَشِّطُ عِظَامَكَ فَتَصِيرُ كَجَنَّةٍ رَيَّا وَكَنَبْعِ مِيَاهٍ لَا تَنْقَطِعُ مِيَاهُهُ.",
    "MAT.16.24": "حِينَئِذٍ قَالَ يَسُوعُ لِتَلَامِيذِهِ: «إِنْ أَرَادَ أَحَدٌ أَنْ يَأْتِيَ وَرَائِي فَلْيُنْكِرْ نَفْسَهُ وَيَحْمِلْ صَلِيبَهُ وَيَتْبَعْنِي،",
    "DEU.31.6": "تَشَدَّدُوا وَتَشَجَّعُوا. لَا تَخَافُوا وَلَا تَرْهَبُوا وُجُوهَهُمْ، لِأَنَّ ٱلرَّبَّ إِلَهَكَ سَائِرٌ مَعَكَ. لَا يُهْمِلُكَ وَلَا يَتْرُكُكَ».",
    "1CO.13.4-5": "ٱلْمَحَبَّةُ تَتَأَنَّى وَتَرْفُقُ. ٱلْمَحَبَّةُ لَا تَحْسِدُ. ٱلْمَحَبَّةُ لَا تَتَفَاخَرُ، وَلَا تَنْتَفِخُ، وَلَا تُقَبِّحُ، وَلَا تَطْلُبُ مَا لِنَفْسِهَا، وَلَا تَحْتَدُّ، وَلَا تَظُنُّ ٱلسُّؤَ،",
    "ACT.16.31": "فَقَالَا: «آمِنْ بِٱلرَّبِّ يَسُوعَ ٱلْمَسِيحِ فَتَخْلُصَ أَنْتَ وَأَهْلُ بَيْتِكَ».",
    "1PE.4.10": "لِيَكُنْ كُلُّ وَاحِدٍ بِحَسَبِ مَا أَخَذَ مَوْهِبَةً، يَخْدِمُ بِهَا بَعْضُكُمْ بَعْضًا، كَوُكَلَاءَ صَالِحِينَ عَلَى نِعْمَةِ ٱللهِ ٱلْمُتَنَوِّعَةِ.",
    "PSA.46.1": "ٱللهُ لَنَا مَلْجَأٌ وَقُوَّةٌ. عَوْنًا فِي ٱلضِّيْقَاتِ وُجِدَ شَدِيدًا.",
    "ISA.41.13": "لِأَنِّي أَنَا ٱلرَّبُّ إِلَهُكَ ٱلْمُمْسِكُ بِيَمِينِكَ، ٱلْقَائِلُ لَكَ: لَا تَخَفْ. أَنَا أُعِينُكَ.",
    "1CO.15.3-4": "فَإِنَّنِي سَلَّمْتُ إِلَيْكُمْ فِي ٱلْأَوَّلِ مَا قَبِلْتُهُ أَنَا أَيْضًا: أَنَّ ٱلْمَسِيحَ مَاتَ مِنْ أَجْلِ خَطَايَانَا حَسَبَ ٱلْكُتُبِ، وَأَنَّهُ دُفِنَ، وَأَنَّهُ قَامَ فِي ٱلْيَوْمِ ٱلثَّالِثِ حَسَبَ ٱلْكُتُبِ،",
    "JER.17.7-8": "مُبَارَكٌ ٱلرَّجُلُ ٱلَّذِي يَتَّكِلُ عَلَى ٱلرَّبِّ، وَكَانَ ٱلرَّبُّ مُتَّكَلَهُ، فَإِنَّهُ يَكُونُ كَشَجَرَةٍ مَغْرُوسَةٍ عَلَى مِيَاهٍ، وَعَلَى نَهْرٍ تَمُدُّ أُصُولَهَا، وَلَا تَرَى إِذَا جَاءَ ٱلْحَرُّ، وَيَكُونُ وَرَقُهَا أَخْضَرَ، وَفِي سَنَةِ ٱلْقَحْطِ لَا تَخَافُ، وَلَا تَكُفُّ عَنِ ٱلْإِثْمَارِ.",
    "PHP.1.6": "وَاثِقًا بِهَذَا عَيْنِهِ أَنَّ ٱلَّذِي ٱبْتَدَأَ فِيكُمْ عَمَلًا صَالِحًا يُكَمِّلُ إِلَى يَوْمِ يَسُوعَ ٱلْمَسِيحِ.",
    "2CO.12.9": "فَقَالَ لِي: «تَكْفِيكَ نِعْمَتِي، لِأَنَّ قُوَّتِي فِي ٱلضَّعْفِ تُكْمَلُ». فَبِكُلِّ سُرُورٍ أَفْتَخِرُ بِٱلْحَرِيِّ فِي ضَعَفَاتِي، لِكَيْ تَحِلَّ عَلَيَّ قُوَّةُ ٱلْمَسِيحِ.",
    "HEB.4.15-16": "لِأَنْ لَيْسَ لَنَا رَئِيسُ كَهَنَةٍ غَيْرُ قَادِرٍ أَنْ يَرْثِيَ لِضَعَفَاتِنَا، بَلْ مُجَرَّبٌ فِي كُلِّ شَيْءٍ مِثْلُنَا، بِلَا خَطِيَّةٍ. فَلْنَتَقَدَّمْ بِثِقَةٍ إِلَى عَرْشِ ٱلنِّعْمَةِ لِكَيْ نَنَالَ رَحْمَةً وَنَجِدَ نِعْمَةً عَوْنًا فِي حِينِهِ.",
    "PRO.4.23": "فَوْقَ كُلِّ تَحَفُّظٍ ٱحْفَظْ قَلْبَكَ، لِأَنَّ مِنْهُ مَخَارِجَ ٱلْحَيَاةِ.",
    "ROM.11.33": "يَا لَعُمْقِ غِنَى ٱللهِ وَحِكْمَتِهِ وَعِلْمِهِ! مَا أَبْعَدَ أَحْكَامَهُ عَنِ ٱلْفَحْصِ وَطُرُقَهُ عَنِ ٱلِٱسْتِقْصَاءِ!",
    "JHN.1.1-3": "فِي ٱلْبَدْءِ كَانَ ٱلْكَلِمَةُ، وَٱلْكَلِمَةُ كَانَ عِنْدَ ٱللهِ، وَكَانَ ٱلْكَلِمَةُ ٱللهَ. هَذَا كَانَ فِي ٱلْبَدْءِ عِنْدَ ٱللهِ. كُلُّ شَيْءٍ بِهِ كَانَ، وَبِغَيْرِهِ لَمْ يَكُنْ شَيْءٌ مِمَّا كَانَ.",
    "PSA.56.3-4": "فِي يَوْمِ خَوْفِي، أَنَا عَلَيْكَ أَتَّكِلُ. ٱللهُ أَفْتَخِرُ بِكَلَامِهِ. عَلَى ٱللهِ تَوَكَّلْتُ فَلَا أَخَافُ. مَاذَا يَصْنَعُهُ بِي ٱلْبَشَرُ؟",
    "JHN.10.11": "أَنَا هُوَ ٱلرَّاعِي ٱلصَّالِحُ، وَٱلرَّاعِي ٱلصَّالِحُ يَبْذِلُ نَفْسَهُ عَنِ ٱلْخِرَافِ.",
    "ROM.12.21": "لَا يَغْلِبَنَّكَ ٱلشَّرُّ بَلِ ٱغْلِبِ ٱلشَّرَّ بِٱلْخَيْرِ.",
    "MRK.9.23": "فَقَالَ لَهُ يَسُوعُ: «إِنْ كُنْتَ تَسْتَطِيعُ أَنْ تُؤْمِنَ. كُلُّ شَيْءٍ مُسْتَطَاعٌ لِلْمُؤْمِنِ».",
    "DEU.33.27": "ٱلْإِلَهُ ٱلْقَدِيمُ مَلْجَأٌ، وَٱلْأَذْرُعُ ٱلْأَبَدِيَّةُ مِنْ تَحْتُ. فَطَرَدَ مِنْ قُدَّامِكَ ٱلْعَدُوَّ وَقَالَ: أَهْلِكْ.",
    "PRO.17.17": "اَلصَّدِيقُ يُحِبُّ فِي كُلِّ وَقْتٍ، أَمَّا ٱلْأَخُ فَلِلشِّدَّةِ يُولَدُ.",
    "PSA.19.1": "اَلسَّمَاوَاتُ تُحَدِّثُ بِمَجْدِ ٱللهِ، وَٱلْفَلَكُ يُخْبِرُ بِعَمَلِ يَدَيْهِ.",
    "MAL.3.10": "هَاتُوا جَمِيعَ ٱلْعُشُورِ إِلَى ٱلْخَزْنَةِ لِيَكُونَ فِي بَيْتِي طَعَامٌ، وَجَرِّبُونِي بِهَذَا، قَالَ رَبُّ ٱلْجُنُودِ، إِنْ كُنْتُ لَا أَفْتَحُ لَكُمْ كُوَى ٱلسَّمَاوَاتِ، وَأَفِيضُ عَلَيْكُمْ بَرَكَةً حَتَّى لَا تُوسَعَ.",
    "JOS.24.15": "وَإِنْ سَاءَ فِي أَعْيُنِكُمْ أَنْ تَعْبُدُوا ٱلرَّبَّ، فَٱخْتَارُوا لِأَنْفُسِكُمُ ٱلْيَوْمَ مَنْ تَعْبُدُونَ: إِنْ كَانَ ٱلْآلِهَةَ ٱلَّذِينَ عَبَدَهُمْ آبَاؤُكُمُ ٱلَّذِينَ فِي عَبْرِ ٱلنَّهْرِ، وَإِنْ كَانَ آلِهَةَ ٱلْأَمُورِيِّينَ ٱلَّذِينَ أَنْتُمْ سَاكِنُونَ فِي أَرْضِهِمْ. وَأَمَّا أَنَا وَبَيْتِي فَنَعْبُدُ ٱلرَّبَّ».",
    "ECC.12.13": "فَلْنَسْمَعْ خِتَامَ ٱلْأَمْرِ كُلِّهِ: ٱتَّقِ ٱللهَ وَٱحْفَظْ وَصَايَاهُ، لِأَنَّ هَذَا هُوَ ٱلْإِنْسَانُ كُلُّهُ.",
    "PSA.37.23-24": "مِنْ قِبَلِ ٱلرَّبِّ تَتَثَبَّتُ خَطَوَاتُ ٱلْإِنْسَانِ وَفِي طَرِيقِهِ يُسَرُّ. إِذَا سَقَطَ لَا يَنْطَرِحُ، لِأَنَّ ٱلرَّبَّ مُسْنِدٌ يَدَهُ.",
    "REV.21.5": "وَقَالَ ٱلْجَالِسُ عَلَى ٱلْعَرْشِ: «هَا أَنَا أَصْنَعُ كُلَّ شَيْءٍ جَدِيدًا!». وَقَالَ لِيَ: «ٱكْتُبْ: فَإِنَّ هَذِهِ ٱلْأَقْوَالَ صَادِقَةٌ وَأَمِينَةٌ».",
    "ISA.40.31": "وَأَمَّا مُنْتَظِرُو ٱلرَّبِّ فَيُجَدِّدُونَ قُوَّةً. يَرْفَعُونَ أَجْنِحَةً كَٱلنُّسُورِ. يَرْكُضُونَ وَلَا يَتْعَبُونَ. يَمْشُونَ وَلَا يُعْيُونَ.",
    "JHN.4.13-14": "أَجَابَ يَسُوعُ وَقَالَ لَهاَ: «كُلُّ مَنْ يَشْرَبُ مِنْ هَذَا ٱلْمَاءِ يَعْطَشُ أَيْضًا. وَلَكِنْ مَنْ يَشْرَبُ مِنَ ٱلْمَاءِ ٱلَّذِي أُعْطِيهِ أَنَا فَلَنْ يَعْطَشَ إِلَى ٱلْأَبَدِ، بَلِ ٱلْمَاءُ ٱلَّذِي أُعْطِيهِ يَصِيرُ فِيهِ يَنْبُوعَ مَاءٍ يَنْبَعُ إِلَى حَيَاةٍ أَبَدِيَّةٍ».",
    "HEB.12.1-2": "لِذَلِكَ نَحْنُ أَيْضًا إِذْ لَنَا سَحَابَةٌ مِنَ ٱلشُّهُودِ مِقْدَارُ هَذِهِ مُحِيطَةٌ بِنَا، لِنَطْرَحْ كُلَّ ثِقْلٍ، وَٱلْخَطِيَّةَ ٱلْمُحِيطَةَ بِنَا بِسُهُولَةٍ، وَلْنُحَاضِرْ بِٱلصَّبْرِ فِي ٱلْجِهَادِ ٱلْمَوْضُوعِ أَمَامَنَا، نَاظِرِينَ إِلَى رَئِيسِ ٱلْإِيمَانِ وَمُكَمِّلِهِ يَسُوعَ، ٱلَّذِي مِنْ أَجْلِ ٱلسُّرُورِ ٱلْمَوْضُوعِ أَمَامَهُ، ٱحْتَمَلَ ٱلصَّلِيبَ مُسْتَهِينًا بِٱلْخِزْيِ، فَجَلَسَ فِي يَمِينِ عَرْشِ ٱللهِ.",
    "1JN.4.18": "لَا خَوْفَ فِي ٱلْمَحَبَّةِ، بَلِ ٱلْمَحَبَّةُ ٱلْكَامِلَةُ تَطْرَحُ ٱلْخَوْفَ إِلَى خَارِجٍ لِأَنَّ ٱلْخَوْفَ لَهُ عَذَابٌ. وَأَمَّا مَنْ خَافَ فَلَمْ يَتَكَمَّلْ فِي ٱلْمَحَبَّةِ.",
    "PSA.118.24": "هَذَا هُوَ ٱلْيَوْمُ ٱلَّذِي صَنَعُهُ ٱلرَّبُّ، نَبْتَهِجُ وَنَفْرَحُ فِيهِ.",
    "HEB.12.11": "وَلَكِنَّ كُلَّ تَأْدِيبٍ فِي ٱلْحَاضِرِ لَا يُرَى أَنَّهُ لِلْفَرَحِ بَلْ لِلْحَزَنِ. وَأَمَّا أَخِيرًا فَيُعْطِي ٱلَّذِينَ يَتَدَرَّبُونَ بِهِ ثَمَرَ بِرٍّ لِلسَّلَامِ.",
    "ECC.4.9-10": "اِثْنَانِ خَيْرٌ مِنْ وَاحِدٍ، لِأَنَّ لَهُمَا أُجْرَةً لِتَعَبِهِمَا صَالِحَةً. لِأَنَّهُ إِنْ وَقَعَ أَحَدُهُمَا يُقِيمُهُ رَفِيقُهُ. وَوَيْلٌ لِمَنْ هُوَ وَحْدَهُ إِنْ وَقَعَ، إِذْ لَيْسَ ثَانٍ لِيُقِيمَهُ.",
    "2CO.1.3-4": "مُبَارَكٌ ٱللهُ أَبُو رَبِّنَا يَسُوعَ ٱلْمَسِيحِ، أَبُو ٱلرَّأْفَةِ وَإِلَهُ كُلِّ تَعْزِيَةٍ، ٱلَّذِي يُعَزِّينَا فِي كُلِّ ضِيقَتِنَا، حَتَّى نَسْتَطِيعَ أَنْ نُعَزِّيَ ٱلَّذِينَ هُمْ فِي كُلِّ ضِيقَةٍ بِٱلتَّعْزِيَةِ ٱلَّتِي نَتَعَزَّى نَحْنُ بِهَا مِنَ ٱللهِ.",
    "PSA.30.5": "لِأَنَّ لِلَحْظَةٍ غَضَبَهُ. حَيَاةٌ فِي رِضَاهُ. عِنْدَ ٱلْمَسَاءِ يَبِيتُ ٱلْبُكَاءُ، وَفِي ٱلصَّبَاحِ تَرَنُّمٌ.",
    "GAL.6.2": "اِحْمِلُوا بَعْضُكُمْ أَثْقَالَ بَعْضٍ، وَهَكَذَا تَمِّمُوا نَامُوسَ ٱلْمَسِيحِ.",
    "JHN.14.27": "«سَلَامًا أَتْرُكُ لَكُمْ. سَلَامِي أُعْطِيكُمْ. لَيْسَ كَمَا يُعْطِي ٱلْعَالَمُ أُعْطِيكُمْ أَنَا. لَا تَضْطَرِبْ قُلُوبُكُمْ وَلَا تَرْهَبْ.",
    "GAL.3.26-28": "لِأَنَّكُمْ جَمِيعًا أَبْنَاءُ ٱللهِ بِٱلْإِيمَانِ بِٱلْمَسِيحِ يَسُوعَ. لِأَنَّ كُلَّكُمُ ٱلَّذِينَ ٱعْتَمَدْتُمْ بِٱلْمَسِيحِ قَدْ لَبِسْتُمُ ٱلْمَسِيحَ: لَيْسَ يَهُودِيٌّ وَلَا يُونَانِيٌّ. لَيْسَ عَبْدٌ وَلَا حُرٌّ. لَيْسَ ذَكَرٌ وَأُنْثَى، لِأَنَّكُمْ جَمِيعًا وَاحِدٌ فِي ٱلْمَسِيحِ يَسُوعَ.",
    "EXO.33.14": "فَقَالَ: «وَجْهِي يَسِيرُ فَأُرِيحُكَ».",
    "LUK.1.37": "لِأَنَّهُ لَيْسَ شَيْءٌ غَيْرَ مُمْكِنٍ لَدَى ٱللهِ».",
    "PRO.16.3": "أَلْقِ عَلَى ٱلرَّبِّ أَعْمَالَكَ فَتُثَبَّتَ أَفْكَارُكَ.",
    "ACT.17.27-28": "لِكَيْ يَطْلُبُوا ٱللهَ لَعَلَّهُمْ يَتَلَمَّسُونَهُ فَيَجِدُوهُ، مَعَ أَنَّهُ عَنْ كُلِّ وَاحِدٍ مِنَّا لَيْسَ بَعِيدًا. لِأَنَّنَا بِهِ نَحْيَا وَنَتَحَرَّكُ وَنُوجَدُ، كَمَا قَالَ بَعْضُ شُعَرَائِكُمْ أَيْضًا: لِأَنَّنَا أَيْضًا ذُرِّيَّتُهُ.",
    "JHN.5.24": "«اَلْحَقَّ ٱلْحَقَّ أَقُولُ لَكُمْ: إِنَّ مَنْ يَسْمَعُ كَلَامِي وَيُؤْمِنُ بِالَّذِي أَرْسَلَنِي فَلَهُ حَيَاةٌ أَبَدِيَّةٌ، وَلَا يَأْتِي إِلَى دَيْنُونَةٍ، بَلْ قَدِ ٱنْتَقَلَ مِنَ ٱلْمَوْتِ إِلَى ٱلْحَيَاةِ.",
    "MRK.1.15": "وَيَقُولُ: «قَدْ كَمَلَ ٱلزَّمَانُ وَٱقْتَرَبَ مَلَكُوتُ ٱللهِ، فَتُوبُوا وَآمِنُوا بِٱلْإِنْجِيلِ».",
    "PRO.16.9": "قَلْبُ ٱلْإِنْسَانِ يُفَكِّرُ فِي طَرِيقِهِ، وَٱلرَّبُّ يَهْدِي خَطْوَتَهُ.",
    "PSA.46.10": "كُفُّوا وَٱعْلَمُوا أَنِّي أَنَا ٱللهُ. أَتَعَالَى بَيْنَ ٱلْأُمَمِ، أَتَعَالَى فِي ٱلْأَرْضِ.",
    "2TH.3.16": "وَرَبُّ ٱلسَّلَامِ نَفْسُهُ يُعْطِيكُمُ ٱلسَّلَامَ دَائِمًا مِنْ كُلِّ وَجْهٍ. ٱلرَّبُّ مَعَ جَمِيعِكُمْ.",
    "1TH.5.16-18": "ٱفْرَحُوا كُلَّ حِينٍ. صَلُّوا بِلَا ٱنْقِطَاعٍ. ٱشْكُرُوا فِي كُلِّ شَيْءٍ، لِأَنَّ هَذِهِ هِيَ مَشِيئَةُ ٱللهِ فِي ٱلْمَسِيحِ يَسُوعَ مِنْ جِهَتِكُمْ.",
    "PHP.3.13-14": "أَيُّهَا ٱلْإِخْوَةُ، أَنَا لَسْتُ أَحْسِبُ نَفْسِي أَنِّي قَدْ أَدْرَكْتُ. وَلَكِنِّي أَفْعَلُ شَيْئًا وَاحِدًا: إِذْ أَنَا أَنْسَى مَا هُوَ وَرَاءُ وَأَمْتَدُّ إِلَى مَا هُوَ قُدَّامُ، أَسْعَى نَحْوَ ٱلْغَرَضِ لِأَجْلِ جَعَالَةِ دَعْوَةِ ٱللهِ ٱلْعُلْيَا فِي ٱلْمَسِيحِ يَسُوعَ.",
    "MAT.24.35": "اَلسَّمَاءُ وَٱلْأَرْضُ تَزُولَانِ وَلَكِنَّ كَلَامِي لَا يَزُولُ.",
    "EPH.5.1-2": "فَكُونُوا مُتَمَثِّلِينَ بِٱللهِ كَأَوْلَادٍ أَحِبَّاءَ، وَٱسْلُكُوا فِي ٱلْمَحَبَّةِ كَمَا أَحَبَّنَا ٱلْمَسِيحُ أَيْضًا وَأَسْلَمَ نَفْسَهُ لِأَجْلِنَا، قُرْبَانًا وَذَبِيحَةً لِلهِ رَائِحَةً طَيِّبَةً.",
    "PRO.18.10": "اِسْمُ ٱلرَّبِّ بُرْجٌ حَصِينٌ، يَرْكُضُ إِلَيْهِ ٱلصِّدِّيقُ وَيَتَمَنَّعُ.",
    "JHN.15.4-5": "اُثْبُتُوا فِيَّ وَأَنَا فِيكُمْ. كَمَا أَنَّ ٱلْغُصْنَ لَا يَقْدِرُ أَنْ يَأْتِيَ بِثَمَرٍ مِنْ ذَاتِهِ إِنْ لَمْ يَثْبُتْ فِي ٱلْكَرْمَةِ، كَذَلِكَ أَنْتُمْ أَيْضًا إِنْ لَمْ تَثْبُتُوا فِيَّ. أَنَا ٱلْكَرْمَةُ وَأَنْتُمُ ٱلْأَغْصَانُ. ٱلَّذِي يَثْبُتُ فِيَّ وَأَنَا فِيهِ هَذَا يَأْتِي بِثَمَرٍ كَثِيرٍ، لِأَنَّكُمْ بِدُونِي لَا تَقْدِرُونَ أَنْ تَفْعَلُوا شَيْئًا.",
    "PSA.37.4": "وَتَلَذَّذْ بِٱلرَّبِّ فَيُعْطِيَكَ سُؤْلَ قَلْبِكَ.",
    "1JN.4.9-10": "بِهَذَا أُظْهِرَتْ مَحَبَّةُ ٱللهِ فِينَا: أَنَّ ٱللهَ قَدْ أَرْسَلَ ٱبْنَهُ ٱلْوَحِيدَ إِلَى ٱلْعَالَمِ لِكَيْ نَحْيَا بِهِ. فِي هَذَا هِيَ ٱلْمَحَبَّةُ: لَيْسَ أَنَّنَا نَحْنُ أَحْبَبْنَا ٱللهَ، بَلْ أَنَّهُ هُوَ أَحَبَّنَا، وَأَرْسَلَ ٱبْنَهُ كَفَّارَةً لِخَطَايَانَا.",
    "JHN.17.3": "وَهَذِهِ هِيَ ٱلْحَيَاةُ ٱلْأَبَدِيَّةُ: أَنْ يَعْرِفُوكَ أَنْتَ ٱلْإِلَهَ ٱلْحَقِيقِيَّ وَحْدَكَ وَيَسُوعَ ٱلْمَسِيحَ ٱلَّذِي أَرْسَلْتَهُ.",
    "2CO.4.6": "لِأَنَّ ٱللهَ ٱلَّذِي قَالَ: «أَنْ يُشْرِقَ نُورٌ مِنْ ظُلْمَةٍ»، هُوَ ٱلَّذِي أَشْرَقَ فِي قُلُوبِنَا، لِإِنَارَةِ مَعْرِفَةِ مَجْدِ ٱللهِ فِي وَجْهِ يَسُوعَ ٱلْمَسِيحِ.",
    "COL.3.12-13": "فَٱلْبَسُوا كَمُخْتَارِي ٱللهِ ٱلْقِدِّيسِينَ ٱلْمَحْبُوبِينَ أَحْشَاءَ رَأْفَاتٍ، وَلُطْفًا، وَتَوَاضُعًا، وَوَدَاعَةً، وَطُولَ أَنَاةٍ، مُحْتَمِلِينَ بَعْضُكُمْ بَعْضًا، وَمُسَامِحِينَ بَعْضُكُمْ بَعْضًا. إِنْ كَانَ لِأَحَدٍ عَلَى أَحَدٍ شَكْوَى، كَمَا غَفَرَ لَكُمُ ٱلْمَسِيحُ هَكَذَا أَنْتُمْ أَيْضًا.",
    "PSA.1.1-2": "طُوبَى لِلرَّجُلِ ٱلَّذِي لَمْ يَسْلُكْ فِي مَشُورَةِ ٱلْأَشْرَارِ، وَفِي طَرِيقِ ٱلْخُطَاةِ لَمْ يَقِفْ، وَفِي مَجْلِسِ ٱلْمُسْتَهْزِئِينَ لَمْ يَجْلِسْ. لَكِنْ فِي نَامُوسِ ٱلرَّبِّ مَسَرَّتُهُ، وَفِي نَامُوسِهِ يَلْهَجُ نَهَارًا وَلَيْلًا.",
    "PRO.3.11-12": "يَا ٱبْنِي، لَا تَحْتَقِرْ تَأْدِيبَ ٱلرَّبِّ وَلَا تَكْرَهْ تَوْبِيخَهُ، لِأَنَّ ٱلَّذِي يُحِبُّهُ ٱلرَّبُّ يُؤَدِّبُهُ، وَكَأَبٍ بِٱبْنٍ يُسَرُّ بِهِ.",
    "ECC.3.11": "صَنَعَ ٱلْكُلَّ حَسَنًا فِي وَقْتِهِ، وَأَيْضًا جَعَلَ ٱلْأَبَدِيَّةَ فِي قَلْبِهِمِ، ٱلَّتِي بِلَاهَا لَا يُدْرِكُ ٱلْإِنْسَانُ ٱلْعَمَلَ ٱلَّذِي يَعْمَلُهُ ٱللهُ مِنَ ٱلْبِدَايَةِ إِلَى ٱلنِّهَايَةِ.",
    "JOL.2.13": "وَمَزِّقُوا قُلُوبَكُمْ لَا ثِيَابَكُمْ». وَٱرْجِعُوا إِلَى ٱلرَّبِّ إِلَهِكُمْ لِأَنَّهُ رَؤُوفٌ رَحِيمٌ، بَطِيءُ ٱلْغَضَبِ وَكَثِيرُ ٱلرَّأْفَةِ وَيَنْدَمُ عَلَى ٱلشَّرِّ.",
    "GAL.6.9-10": "فَلَا نَفْشَلْ فِي عَمَلِ ٱلْخَيْرِ لِأَنَّنَا سَنَحْصُدُ فِي وَقْتِهِ إِنْ كُنَّا لَا نَكِلُّ. فَإِذًا حَسْبَمَا لَنَا فُرْصَةٌ، فَلْنَعْمَلِ ٱلْخَيْرَ لِلْجَمِيعِ، وَلَا سِيَّمَا لِأَهْلِ ٱلْإِيمَانِ.",
    "PSA.136.1": "اِحْمَدُوا ٱلرَّبَّ لِأَنَّهُ صَالِحٌ، لِأَنَّ إِلَى ٱلْأَبَدِ رَحْمَتَهُ.",
    "PHP.4.13": "أَسْتَطِيعُ كُلَّ شَيْءٍ فِي ٱلْمَسِيحِ ٱلَّذِي يُقَوِّينِي.",
    "EPH.4.32": "وَكُونُوا لُطَفَاءَ بَعْضُكُمْ نَحْوَ بَعْضٍ، شَفُوقِينَ، مُتَسَامِحِينَ كَمَا سَامَحَكُمُ ٱللهُ أَيْضًا فِي ٱلْمَسِيحِ.",
    "JAS.1.12": "طُوبَى لِلرَّجُلِ ٱلَّذِي يَحْتَمِلُ ٱلتَّجْرِبَةَ، لِأَنَّهُ إِذَا تَزَكَّى يَنَالُ «إِكْلِيلَ ٱلْحَيَاةِ» ٱلَّذِي وَعَدَ بِهِ ٱلرَّبُّ لِلَّذِينَ يُحِبُّونَهُ.",
    "JHN.1.12": "وَأَمَّا كُلُّ ٱلَّذِينَ قَبِلُوهُ فَأَعْطَاهُمْ سُلْطَانًا أَنْ يَصِيرُوا أَوْلَادَ ٱللهِ، أَيِ ٱلْمُؤْمِنُونَ بِٱسْمِهِ.",
    "EPH.3.17-19": "لِيَحِلَّ ٱلْمَسِيحُ بِٱلْإِيمَانِ فِي قُلُوبِكُمْ، وَأَنْتُمْ مُتَأَصِّلُونَ وَمُتَأَسِّسُونَ فِي ٱلْمَحَبَّةِ، حَتَّى تَسْتَطِيعُوا أَنْ تُدْرِكُوا مَعَ جَمِيعِ ٱلْقِدِّيسِينَ، مَا هُوَ ٱلْعَرْضُ وَٱلطُّولُ وَٱلْعُمْقُ وَٱلْعُلْوُ، وَتَعْرِفُوا مَحَبَّةَ ٱلْمَسِيحِ ٱلْفَائِقَةَ ٱلْمَعْرِفَةِ، لِكَيْ تَمْتَلِئُوا إِلَى كُلِّ مِلْءِ ٱللهِ.",
    "PHP.2.9-11": "لِذَلِكَ رَفَّعَهُ ٱللهُ أَيْضًا، وَأَعْطَاهُ ٱسْمًا فَوْقَ كُلِّ ٱسْمٍ، لِكَيْ تَجْثُوَ بِٱسْمِ يَسُوعَ كُلُّ رُكْبَةٍ مِمَّنْ فِي ٱلسَّمَاءِ، وَمَنْ عَلَى ٱلْأَرْضِ، وَمَنْ تَحْتَ ٱلْأَرْضِ، وَيَعْتَرِفَ كُلُّ لِسَانٍ أَنَّ يَسُوعَ ٱلْمَسِيحَ هُوَ رَبٌّ، لِمَجْدِ ٱللهِ ٱلْآبِ.",
    "PRO.31.30": "اَلْحُسْنُ غِشٌّ وَٱلْجَمَالُ بَاطِلٌ، أَمَّا ٱلْمَرْأَةُ ٱلْمُتَّقِيَةُ ٱلرَّبَّ فَهِيَ تُمْدَحُ.",
    "MAT.28.19-20": "فَٱذْهَبُوا وَتَلْمِذُوا جَمِيعَ ٱلْأُمَمِ وَعَمِّدُوهُمْ بِٱسْمِ ٱلْآبِ وَٱلِٱبْنِ وَٱلرُّوحِ ٱلْقُدُسِ. وَعَلِّمُوهُمْ أَنْ يَحْفَظُوا جَمِيعَ مَا أَوْصَيْتُكُمْ بِهِ. وَهَا أَنَا مَعَكُمْ كُلَّ ٱلْأَيَّامِ إِلَى ٱنْقِضَاءِ ٱلدَّهْرِ». آمِينَ.",
    "1JN.3.16": "بِهَذَا قَدْ عَرَفْنَا ٱلْمَحَبَّةَ: أَنَّ ذَاكَ وَضَعَ نَفْسَهُ لِأَجْلِنَا، فَنَحْنُ يَنْبَغِي لَنَا أَنْ نَضَعَ نُفُوسَنَا لِأَجْلِ ٱلْإِخْوَةِ.",
    "EPH.4.1-3": "فَأَطْلُبُ إِلَيْكُمْ، أَنَا ٱلْأَسِيرَ فِي ٱلرَّبِّ: أَنْ تَسْلُكُوا كَمَا يَحِقُّ لِلدَّعْوَةِ ٱلَّتِي دُعِيتُمْ بِهَا. بِكُلِّ تَوَاضُعٍ وَوَدَاعَةٍ وَبِطُولِ أَنَاةٍ، مُحْتَمِلِينَ بَعْضُكُمْ بَعْضًا فِي ٱلْمَحَبَّةِ. مُجْتَهِدِينَ أَنْ تَحْفَظُوا وَحْدَانِيَّةَ ٱلرُّوحِ بِرِبَاطِ ٱلسَّلَامِ.",
    "PSA.100.4-5": "ٱدْخُلُوا أَبْوَابَهُ بِحَمْدٍ، دِيَارَهُ بِٱلتَّسْبِيحِ. ٱحْمَدُوهُ، بَارِكُوا ٱسْمَهُ. لِأَنَّ ٱلرَّبَّ صَالِحٌ، إِلَى ٱلْأَبَدِ رَحْمَتُهُ، وَإِلَى دَوْرٍ فَدَوْرٍ أَمَانَتُهُ.",
    "HAB.3.17-18": "فَمَعَ أَنَّهُ لَا يُزْهِرُ ٱلتِّينُ، وَلَا يَكُونُ حَمْلٌ فِي ٱلْكُرُومِ. يَكْذِبُ عَمَلُ ٱلزَّيْتُونَةِ، وَٱلْحُقُولُ لَا تَصْنَعُ طَعَامًا. يَنْقَطِعُ ٱلْغَنَمُ مِنَ ٱلْحَظِيرَةِ، وَلَا بَقَرَ فِي ٱلْمَذَاوِدِ، فَإِنِّي أَبْتَهِجُ بِٱلرَّبِّ وَأَفْرَحُ بِإِلَهِ خَلَاصِي.",
    "ROM.6.23": "لِأَنَّ أُجْرَةَ ٱلْخَطِيَّةِ هِيَ مَوْتٌ، وَأَمَّا هِبَةُ ٱللهِ فَهِيَ حَيَاةٌ أَبَدِيَّةٌ بِٱلْمَسِيحِ يَسُوعَ رَبِّنَا.",
    "LAM.3.22-23": "إِنَّهُ مِنْ إِحْسَانَاتِ ٱلرَّبِّ أَنَّنَا لَمْ نَفْنَ، لِأَنَّ مَرَاحِمَهُ لَا تَزُولُ. هِيَ جَدِيدَةٌ فِي كُلِّ صَبَاحٍ. كَثِيرَةٌ أَمَانَتُكَ.",
    "1JN.3.1": "اُنْظُرُوا أَيَّةَ مَحَبَّةٍ أَعْطَانَا ٱلْآبُ حَتَّى نُدْعَى أَوْلَادَ ٱللهِ! مِنْ أَجْلِ هَذَا لَا يَعْرِفُنَا ٱلْعَالَمُ، لِأَنَّهُ لَا يَعْرِفُهُ.",
    "PSA.150.6": "كُلُّ نَسَمَةٍ فَلْتُسَبِّحِ ٱلرَّبَّ. هَلِّلُويَا.",
    "2CO.4.16-18": "لِذَلِكَ لَا نَفْشَلُ، بَلْ وَإِنْ كَانَ إِنْسَانُنَا ٱلْخَارِجُ يَفْنَى، فَٱلدَّاخِلُ يَتَجَدَّدُ يَوْمًا فَيَوْمًا. لِأَنَّ خِفَّةَ ضِيقَتِنَا ٱلْوَقْتِيَّةَ تُنْشِئُ لَنَا أَكْثَرَ فَأَكْثَرَ ثِقَلَ مَجْدٍ أَبَدِيًّا. وَنَحْنُ غَيْرُ نَاظِرِينَ إِلَى ٱلْأَشْيَاءِ ٱلَّتِي تُرَى، بَلْ إِلَى ٱلَّتِي لَا تُرَى. لِأَنَّ ٱلَّتِي تُرَى وَقْتِيَّةٌ، وَأَمَّا ٱلَّتِي لَا تُرَى فَأَبَدِيَّةٌ.",
    "JER.29.12-13": "فَتَدْعُونَنِي وَتَذْهَبُونَ وَتُصَلُّونَ إِلَيَّ فَأَسْمَعُ لَكُمْ. وَتَطْلُبُونَنِي فَتَجِدُونَنِي إِذْ تَطْلُبُونَنِي بِكُلِّ قَلْبِكُمْ.",
    "REV.21.4": "وَسَيَمْسَحُ ٱللهُ كُلَّ دَمْعَةٍ مِنْ عُيُونِهِمْ، وَٱلْمَوْتُ لَا يَكُونُ فِي مَا بَعْدُ، وَلَا يَكُونُ حُزْنٌ وَلَا صُرَاخٌ وَلَا وَجَعٌ فِي مَا بَعْدُ، لِأَنَّ ٱلْأُمُورَ ٱلْأُولَى قَدْ مَضَتْ».",
    "PSA.84.11": "لِأَنَّ ٱلرَّبَّ ٱللهَ، شَمْسٌ وَمِجَنٌّ. ٱلرَّبُّ يُعْطِي رَحْمَةً وَمَجْدًا. لَا يَمْنَعُ خَيْرًا عَنِ ٱلسَّالِكِينَ بِٱلْكَمَالِ.",
    "1TI.6.12": "جَاهِدْ جِهَادَ ٱلْإِيمَانِ ٱلْحَسَنَ، وَأَمْسِكْ بِٱلْحَيَاةِ ٱلْأَبَدِيَّةِ ٱلَّتِي إِلَيْهَا دُعِيتَ أَيْضًا، وَٱعْتَرَفْتَ ٱلِٱعْتِرَافَ ٱلْحَسَنَ أَمَامَ شُهُودٍ كَثِيرِينَ.",
    "LAM.3.25-26": "طَيِّبٌ هُوَ ٱلرَّبُّ لِلَّذِينَ يَتَرَجَّوْنَهُ، لِلنَّفْسِ ٱلَّتِي تَطْلُبُهُ. جَيِّدٌ أَنْ يَنْتَظِرَ ٱلْإِنْسَانُ وَيَتَوَقَّعَ بِسُكُوتٍ خَلَاصَ ٱلرَّبِّ.",
    "2CO.3.17": "وَأَمَّا ٱلرَّبُّ فَهُوَ ٱلرُّوحُ، وَحَيْثُ رُوحُ ٱلرَّبِّ هُنَاكَ حُرِّيَّةٌ.",
    "PSA.91.1-2": "اَلسَّاكِنُ فِي سِتْرِ ٱلْعَلِيِّ، فِي ظِلِّ ٱلْقَدِيرِ يَبِيتُ. أَقُولُ لِلرَّبِّ: «مَلْجَإِي وَحِصْنِي. إِلَهِي فَأَتَّكِلُ عَلَيْهِ».",
    "EPH.1.3": "مُبَارَكٌ ٱللهُ أَبُو رَبِّنَا يَسُوعَ ٱلْمَسِيحِ، ٱلَّذِي بَارَكَنَا بِكُلِّ بَرَكَةٍ رُوحِيَّةٍ فِي ٱلسَّمَاوِيَّاتِ فِي ٱلْمَسِيحِ،",
    "MAT.4.4": "فَأَجَابَ وَقَالَ: «مَكْتُوبٌ: لَيْسَ بِٱلْخُبْزِ وَحْدَهُ يَحْيَا ٱلْإِنْسَانُ، بَلْ بِكُلِّ كَلِمَةٍ تَخْرُجُ مِنْ فَمِ ٱللهِ».",
    "ISA.49.15-16": "«هَلْ تَنْسَى ٱلْمَرْأَةُ رَضِيعَهَا فَلَا تَرْحَمَ ٱبْنَ بَطْنِهَا؟ حَتَّى هَؤُلَاءِ يَنْسَيْنَ، وَأَنَا لَا أَنْسَاكِ. هُوَذَا عَلَى كَفَّيَّ نَقَشْتُكِ. أَسْوَارُكِ أَمَامِي دَائِمًا.",
    "HEB.10.24-25": "وَلْنُلَاحِظْ بَعْضُنَا بَعْضًا لِلتَّحْرِيضِ عَلَى ٱلْمَحَبَّةِ وَٱلْأَعْمَالِ ٱلْحَسَنَةِ، غَيْرَ تَارِكِينَ ٱجْتِمَاعَنَا كَمَا لِقَوْمٍ عَادَةٌ، بَلْ وَاعِظِينَ بَعْضُنَا بَعْضًا، وَبِٱلْأَكْثَرِ عَلَى قَدْرِ مَا تَرَوْنَ ٱلْيَوْمَ يَقْرُبُ،",
    "ROM.1.16": "لِأَنِّي لَسْتُ أَسْتَحِي بِإِنْجِيلِ ٱلْمَسِيحِ، لِأَنَّهُ قُوَّةُ ٱللهِ لِلْخَلَاصِ لِكُلِّ مَنْ يُؤْمِنُ: لِلْيَهُودِيِّ أَوَّلًا ثُمَّ لِلْيُونَانِيِّ.",
    "2TI.1.7": "لِأَنَّ ٱللهَ لَمْ يُعْطِنَا رُوحَ ٱلْفَشَلِ، بَلْ رُوحَ ٱلْقُوَّةِ وَٱلْمَحَبَّةِ وَٱلنُّصْحِ.",
    "ISA.40.28-29": "أَمَا عَرَفْتَ أَمْ لَمْ تَسْمَعْ؟ إِلَهُ ٱلدَّهْرِ ٱلرَّبُّ خَالِقُ أَطْرَافِ ٱلْأَرْضِ لَا يَكِلُّ وَلَا يَعْيَا. لَيْسَ عَنْ فَهْمِهِ فَحْصٌ. يُعْطِي ٱلْمُعْيِيَ قُدْرَةً، وَلِعَدِيمِ ٱلْقُوَّةِ يُكَثِّرُ شِدَّةً.",
    "JHN.8.31-32": "فَقَالَ يَسُوعُ لِلْيَهُودِ ٱلَّذِينَ آمَنُوا بِهِ: «إِنَّكُمْ إِنْ ثَبَتُّمْ فِي كَلَامِي فَبِالْحَقِيقَةِ تَكُونُونَ تَلَامِيذِي، وَتَعْرِفُونَ ٱلْحَقَّ، وَٱلْحَقُّ يُحَرِّرُكُمْ».",
    "HEB.11.1": "وَأَمَّا ٱلْإِيمَانُ فَهُوَ ٱلثِّقَةُ بِمَا يُرْجَى وَٱلْإِيقَانُ بِأُمُورٍ لَا تُرَى.",
    "ISA.40.11": "كَرَاعٍ يَرْعَى قَطِيعَهُ. بِذِرَاعِهِ يَجْمَعُ ٱلْحُمْلَانَ، وَفِي حِضْنِهِ يَحْمِلُهَا، وَيَقُودُ ٱلْمُرْضِعَاتِ».",
    "JHN.13.34-35": "وَصِيَّةً جَدِيدَةً أَنَا أُعْطِيكُمْ: أَنْ تُحِبُّوا بَعْضُكُمْ بَعْضًا. كَمَا أَحْبَبْتُكُمْ أَنَا تُحِبُّونَ أَنْتُمْ أَيْضًا بَعْضُكُمْ بَعْضًا. بِهَذَا يَعْرِفُ ٱلْجَمِيعُ أَنَّكُمْ تَلَامِيذِي: إِنْ كَانَ لَكُمْ حُبٌّ بَعْضًا لِبَعْضٍ».",
    "JER.1.5": "«قَبْلَمَا صَوَّرْتُكَ فِي ٱلْبَطْنِ عَرَفْتُكَ، وَقَبْلَمَا خَرَجْتَ مِنَ ٱلرَّحِمِ قَدَّسْتُكَ. جَعَلْتُكَ نَبِيًّا لِلشُّعُوبِ».",
    "EPH.4.29": "لَا تَخْرُجْ كَلِمَةٌ رَدِيَّةٌ مِنْ أَفْوَاهِكُمْ، بَلْ كُلُّ مَا كَانَ صَالِحًا لِلْبُنْيَانِ حَسَبَ ٱلْحَاجَةِ، كَيْ يُعْطِيَ نِعْمَةً لِلسَّامِعِينَ.",
    "JHN.10.10": "اَلسَّارِقُ لَا يَأْتِي إِلَّا لِيَسْرِقَ وَيَذْبَحَ وَيُهْلِكَ، وَأَمَّا أَنَا فَقَدْ أَتَيْتُ لِتَكُونَ لَهُمْ حَيَاةٌ وَلِيَكُونَ لَهُمْ أَفْضَلُ.",
    "HEB.11.6": "وَلَكِنْ بِدُونِ إِيمَانٍ لَا يُمْكِنُ إِرْضَاؤُهُ، لِأَنَّهُ يَجِبُ أَنَّ ٱلَّذِي يَأْتِي إِلَى ٱللهِ يُؤْمِنُ بِأَنَّهُ مَوْجُودٌ، وَأَنَّهُ يُجَازِي ٱلَّذِينَ يَطْلُبُونَهُ.",
    "ISA.55.6-7": "اُطْلُبُوا ٱلرَّبَّ مَا دَامَ يُوجَدُ. ٱدْعُوهُ وَهُوَ قَرِيبٌ. لِيَتْرُكِ ٱلشِّرِّيرُ طَرِيقَهُ، وَرَجُلُ ٱلْإِثْمِ أَفْكَارَهُ، وَلْيَتُبْ إِلَى ٱلرَّبِّ فَيَرْحَمَهُ، وَإِلَى إِلَهِنَا لِأَنَّهُ يُكْثِرُ ٱلْغُفْرَانَ.",
    "JHN.15.16": "لَيْسَ أَنْتُمُ ٱخْتَرْتُمُونِي بَلْ أَنَا ٱخْتَرْتُكُمْ، وَأَقَمْتُكُمْ لِتَذْهَبُوا وَتَأْتُوا بِثَمَرٍ، وَيَدُومَ ثَمَرُكُمْ، لِكَيْ يُعْطِيَكُمُ ٱلْآبُ كُلَّ مَا طَلَبْتُمْ بِٱسْمِي.",
    "1CO.13.13": "أَمَّا ٱلْآنَ فَيَثْبُتُ: ٱلْإِيمَانُ وَٱلرَّجَاءُ وَٱلْمَحَبَّةُ، هَذِهِ ٱلثَّلَاثَةُ وَلَكِنَّ أَعْظَمَهُنَّ ٱلْمَحَبَّةُ.",
    "ROM.8.38-39": "فَإِنِّي مُتَيَقِّنٌ أَنَّهُ لَا مَوْتَ وَلَا حَيَاةَ، وَلَا مَلَائِكَةَ وَلَا رُؤَسَاءَ وَلَا قُوَّاتِ، وَلَا أُمُورَ حَاضِرَةً وَلَا مُسْتَقْبَلَةً، وَلَا عُلْوَ وَلَا عُمْقَ، وَلَا خَلِيقَةَ أُخْرَى، تَقْدِرُ أَنْ تَفْصِلَنَا عَنْ مَحَبَّةِ ٱللهِ ٱلَّتِي فِي ٱلْمَسِيحِ يَسُوعَ رَبِّنَا.",
    "MAT.6.26": "اُنْظُرُوا إِلَى طُيُورِ ٱلسَّمَاءِ: إِنَّهَا لَا تَزْرَعُ وَلَا تَحْصُدُ وَلَا تَجْمَعُ إِلَى مَخَازِنَ، وَأَبُوكُمُ ٱلسَّمَاوِيُّ يَقُوتُهَا. أَلَسْتُمْ أَنْتُمْ بِٱلْحَرِيِّ أَفْضَلَ مِنْهَا؟",
    "1TI.1.15": "صَادِقَةٌ هِيَ ٱلْكَلِمَةُ وَمُسْتَحِقَّةٌ كُلَّ قُبُولٍ: أَنَّ ٱلْمَسِيحَ يَسُوعَ جَاءَ إِلَى ٱلْعَالَمِ لِيُخَلِّصَ ٱلْخُطَاةَ ٱلَّذِينَ أَوَّلُهُمْ أَنَا.",
    "JAS.1.22": "وَلَكِنْ كُونُوا عَامِلِينَ بِٱلْكَلِمَةِ، لَا سَامِعِينَ فَقَطْ خَادِعِينَ نُفُوسَكُمْ.",
    "PSA.145.18": "ٱلرَّبُّ قَرِيبٌ لِكُلِّ ٱلَّذِينَ يَدْعُونَهُ، ٱلَّذِينَ يَدْعُونَهُ بِٱلْحَقِّ.",
    "MAT.22.37-39": "فَقَالَ لَهُ يَسُوعُ: «تُحِبُّ ٱلرَّبَّ إِلَهَكَ مِنْ كُلِّ قَلْبِكَ، وَمِنْ كُلِّ نَفْسِكَ، وَمِنْ كُلِّ فِكْرِكَ. هَذِهِ هِيَ ٱلْوَصِيَّةُ ٱلْأُولَى وَٱلْعُظْمَى. وَٱلثَّانِيَةُ مِثْلُهَا: تُحِبُّ قَرِيبَكَ كَنَفْسِكَ.",
    "PSA.16.11": "تُعَرِّفُنِي سَبِيلَ ٱلْحَيَاةِ. أَمَامَكَ شِبَعُ سُرُورٍ. فِي يَمِينِكَ نِعَمٌ إِلَى ٱلْأَبَدِ.",
    "GEN.1.1": "فِي ٱلْبَدْءِ خَلَقَ ٱللهُ ٱلسَّمَاوَاتِ وَٱلْأَرْضَ.",
    "JAS.1.5": "وَإِنَّمَا إِنْ كَانَ أَحَدُكُمْ تُعْوِزُهُ حِكْمَةٌ، فَلْيَطْلُبْ مِنَ ٱللهِ ٱلَّذِي يُعْطِي ٱلْجَمِيعَ بِسَخَاءٍ وَلَا يُعَيِّرُ، فَسَيُعْطَى لَهُ.",
    "MAT.18.20": "لِأَنَّهُ حَيْثُمَا ٱجْتَمَعَ ٱثْنَانِ أَوْ ثَلَاثَةٌ بِٱسْمِي فَهُنَاكَ أَكُونُ فِي وَسْطِهِمْ».",
    "PSA.121.1-2": "أَرْفَعُ عَيْنَيَّ إِلَى ٱلْجِبَالِ، مِنْ حَيْثُ يَأْتِي عَوْنِي! مَعُونَتِي مِنْ عِنْدِ ٱلرَّبِّ، صَانِعِ ٱلسَّمَاوَاتِ وَٱلْأَرْضِ.",
    "GAL.5.22-23": "وَأَمَّا ثَمَرُ ٱلرُّوحِ فَهُوَ: مَحَبَّةٌ، فَرَحٌ، سَلَامٌ، طُولُ أَنَاةٍ، لُطْفٌ، صَلَاحٌ، إِيمَانٌ، وَدَاعَةٌ، تَعَفُّفٌ. ضِدَّ أَمْثَالِ هَذِهِ لَيْسَ نَامُوسٌ.",
    "ISA.64.8": "وَٱلْآنَ يَارَبُّ أَنْتَ أَبُونَا. نَحْنُ ٱلطِّينُ وَأَنْتَ جَابِلُنَا، وَكُلُّنَا عَمَلُ يَدَيْكَ.",
    "ROM.10.13": "لِأَنَّ «كُلَّ مَنْ يَدْعُو بِٱسْمِ ٱلرَّبِّ يَخْلُصُ».",
    "COL.3.17": "وَكُلُّ مَا عَمِلْتُمْ بِقَوْلٍ أَوْ فِعْلٍ، فَٱعْمَلُوا ٱلْكُلَّ بِٱسْمِ ٱلرَّبِّ يَسُوعَ، شَاكِرِينَ ٱللهَ وَٱلْآبَ بِهِ.",
    "MAT.7.7-8": "«اِسْأَلُوا تُعْطَوْا. اُطْلُبُوا تَجِدُوا. اِقْرَعُوا يُفْتَحْ لَكُمْ. لِأَنَّ كُلَّ مَنْ يَسْأَلُ يَأْخُذُ، وَمَنْ يَطْلُبُ يَجِدُ، وَمَنْ يَقْرَعُ يُفْتَحُ لَهُ.",
    "JHN.20.29": "قَالَ لَهُ يَسُوعُ: «لِأَنَّكَ رَأَيْتَنِي يَا تُومَا آمَنْتَ! طُوبَى لِلَّذِينَ آمَنُوا وَلَمْ يَرَوْا».",
    "JER.33.3": "اُدْعُنِي فَأُجِيبَكَ وَأُخْبِرَكَ بِعَظَائِمَ وَعَوَائِصَ لَمْ تَعْرِفْهَا.",
    "EZK.36.26": "وَأُعْطِيكُمْ قَلْبًا جَدِيدًا، وَأَجْعَلُ رُوحًا جَدِيدَةً فِي دَاخِلِكُمْ، وَأَنْزِعُ قَلْبَ ٱلْحَجَرِ مِنْ لَحْمِكُمْ وَأُعْطِيكُمْ قَلْبَ لَحْمٍ.",
    "ROM.5.8": "وَلَكِنَّ ٱللهَ بَيَّنَ مَحَبَّتَهُ لَنَا، لِأَنَّهُ وَنَحْنُ بَعْدُ خُطَاةٌ مَاتَ ٱلْمَسِيحُ لِأَجْلِنَا.",
    "PSA.119.105": "سِرَاجٌ لِرِجْلِي كَلَامُكَ وَنُورٌ لِسَبِيلِي.",
    "ROM.12.1-2": "فَأَطْلُبُ إِلَيْكُمْ أَيُّهَا ٱلْإِخْوَةُ بِرَأْفَةِ ٱللهِ أَنْ تُقَدِّمُوا أَجْسَادَكُمْ ذَبِيحَةً حَيَّةً مُقَدَّسَةً مَرْضِيَّةً عِنْدَ ٱللهِ، عِبَادَتَكُمُ ٱلْعَقْلِيَّةَ. وَلَا تُشَاكِلُوا هَذَا ٱلدَّهْرَ، بَلْ تَغَيَّرُوا عَنْ شَكْلِكُمْ بِتَجْدِيدِ أَذْهَانِكُمْ، لِتَخْتَبِرُوا مَا هِيَ إِرَادَةُ ٱللهِ: ٱلصَّالِحَةُ ٱلْمَرْضِيَّةُ ٱلْكَامِلَةُ.",
    "PSA.119.11": "خَبَأْتُ كَلَامَكَ فِي قَلْبِي لِكَيْلَا أُخْطِئَ إِلَيْكَ.",
    "1CO.16.13-14": "اِسْهَرُوا. ٱثْبُتُوا فِي ٱلْإِيمَانِ. كُونُوا رِجَالًا. تَقَوَّوْا. لِتَصِرْ كُلُّ أُمُورِكُمْ فِي مَحَبَّةٍ.",
    "MAT.11.28-30": "تَعَالَوْا إِلَيَّ يا جَمِيعَ ٱلْمُتْعَبِينَ وَٱلثَّقِيلِي ٱلْأَحْمَالِ، وَأَنَا أُرِيحُكُمْ. اِحْمِلُوا نِيرِي عَلَيْكُمْ وَتَعَلَّمُوا مِنِّي، لِأَنِّي وَدِيعٌ وَمُتَوَاضِعُ ٱلْقَلْبِ، فَتَجِدُوا رَاحَةً لِنُفُوسِكُمْ. لِأَنَّ نِيرِي هَيِّنٌ وَحِمْلِي خَفِيفٌ».",
    "1SA.16.7": "فَقَالَ ٱلرَّبُّ لِصَمُوئِيلَ: «لَا تَنْظُرْ إِلَى مَنْظَرِهِ وَطُولِ قَامَتِهِ لِأَنِّي قَدْ رَفَضْتُهُ. لِأَنَّهُ لَيْسَ كَمَا يَنْظُرُ ٱلْإِنْسَانُ. لِأَنَّ ٱلْإِنْسَانَ يَنْظُرُ إِلَى ٱلْعَيْنَيْنِ، وَأَمَّا ٱلرَّبُّ فَإِنَّهُ يَنْظُرُ إِلَى ٱلْقَلْبِ».",
    "LUK.1.46-47": "فَقَالَتْ مَرْيَمُ: «تُعَظِّمُ نَفْسِي ٱلرَّبَّ، وَتَبْتَهِجُ رُوحِي بِٱللهِ مُخَلِّصِي،",
    "GEN.1.27": "فَخَلَقَ ٱللهُ ٱلْإِنْسَانَ عَلَى صُورَتِهِ. عَلَى صُورَةِ ٱللهِ خَلَقَهُ. ذَكَرًا وَأُنْثَى خَلَقَهُمْ.",
    "GAL.2.20": "مَعَ ٱلْمَسِيحِ صُلِبْتُ، فَأَحْيَا لَا أَنَا، بَلِ ٱلْمَسِيحُ يَحْيَا فِيَّ. فَمَا أَحْيَاهُ ٱلْآنَ فِي ٱلْجَسَدِ، فَإِنَّمَا أَحْيَاهُ فِي ٱلْإِيمَانِ، إِيمَانِ ٱبْنِ ٱللهِ، ٱلَّذِي أَحَبَّنِي وَأَسْلَمَ نَفْسَهُ لِأَجْلِي.",
    "1CO.2.9": "بَلْ كَمَا هُوَ مَكْتُوبٌ: «مَا لَمْ تَرَ عَيْنٌ، وَلَمْ تَسْمَعْ أُذُنٌ، وَلَمْ يَخْطُرْ عَلَى بَالِ إِنْسَانٍ: مَا أَعَدَّهُ ٱللهُ لِلَّذِينَ يُحِبُّونَهُ».",
    "COL.3.16": "لِتَسْكُنْ فِيكُمْ كَلِمَةُ ٱلْمَسِيحِ بِغِنًى، وَأَنْتُمْ بِكُلِّ حِكْمَةٍ مُعَلِّمُونَ وَمُنْذِرُونَ بَعْضُكُمْ بَعْضًا، بِمَزَامِيرَ وَتَسَابِيحَ وَأَغَانِيَّ رُوحِيَّةٍ، بِنِعْمَةٍ، مُتَرَنِّمِينَ فِي قُلُوبِكُمْ لِلرَّبِّ.",
    "NUM.6.24-26": "يُبَارِكُكَ ٱلرَّبُّ وَيَحْرُسُكَ. يُضِيءُ ٱلرَّبُّ بِوَجْهِهِ عَلَيْكَ وَيَرْحَمُكَ. يَرْفَعُ ٱلرَّبُّ وَجْهَهُ عَلَيْكَ وَيَمْنَحُكَ سَلَامًا.",
    "LUK.11.28": "أَمَّا هُوَ فَقَالَ: «بَلْ طُوبَى لِلَّذِينَ يَسْمَعُونَ كَلَامَ ٱللهِ وَيَحْفَظُونَهُ».",
    "PSA.63.1": "يَا ٱللهُ، إِلَهِي أَنْتَ. إِلَيْكَ أُبَكِّرُ. عَطِشَتْ إِلَيْكَ نَفْسِي، يَشْتَاقُ إِلَيْكَ جَسَدِي فِي أَرْضٍ نَاشِفَةٍ وَيَابِسَةٍ بِلَا مَاءٍ،",
    "JHN.8.36": "فَإِنْ حَرَّرَكُمْ ٱلِٱبْنُ فَبِالْحَقِيقَةِ تَكُونُونَ أَحْرَارًا.",
    "PRO.15.1": "اَلْجَوَابُ ٱللَّيِّنُ يَصْرِفُ ٱلْغَضَبَ، وَٱلْكَلَامُ ٱلْمُوجِعُ يُهَيِّجُ ٱلسَّخَطَ.",
    "ISA.43.18-19": "«لَا تَذْكُرُوا ٱلْأَوَّلِيَّاتِ، وَٱلْقَدِيمَاتُ لَا تَتَأَمَّلُوا بِهَا. هَأَنَذَا صَانِعٌ أَمْرًا جَدِيدًا. ٱلْآنَ يَنْبُتُ. أَلَا تَعْرِفُونَهُ؟ أَجْعَلُ فِي ٱلْبَرِّيَّةِ طَرِيقًا، فِي ٱلْقَفْرِ أَنْهَارًا.",
    "JAS.1.19-20": "إِذًا يَا إِخْوَتِي ٱلْأَحِبَّاءَ، لِيَكُنْ كُلُّ إِنْسَانٍ مُسْرِعًا فِي ٱلِٱسْتِمَاعِ، مُبْطِئًا فِي ٱلتَّكَلُّمِ، مُبْطِئًا فِي ٱلْغَضَبِ، لِأَنَّ غَضَبَ ٱلْإِنْسَانِ لَا يَصْنَعُ بِرَّ ٱللهِ.",
    "EPH.2.10": "لِأَنَّنَا نَحْنُ عَمَلُهُ، مَخْلُوقِينَ فِي ٱلْمَسِيحِ يَسُوعَ لِأَعْمَالٍ صَالِحَةٍ، قَدْ سَبَقَ ٱللهُ فَأَعَدَّهَا لِكَيْ نَسْلُكَ فِيهَا.",
    "ROM.10.17": "إِذًا ٱلْإِيمَانُ بِٱلْخَبَرِ، وَٱلْخَبَرُ بِكَلِمَةِ ٱللهِ.",
    "JAS.1.2-4": "اِحْسِبُوهُ كُلَّ فَرَحٍ يَا إِخْوَتِي حِينَمَا تَقَعُونَ فِي تَجَارِبَ مُتَنَوِّعَةٍ، عَالِمِينَ أَنَّ ٱمْتِحَانَ إِيمَانِكُمْ يُنْشِئُ صَبْرًا. وَأَمَّا ٱلصَّبْرُ فَلْيَكُنْ لَهُ عَمَلٌ تَامٌّ، لِكَيْ تَكُونُوا تَامِّينَ وَكَامِلِينَ غَيْرَ نَاقِصِينَ فِي شَيْءٍ.",
    "1TH.5.11": "لِذَلِكَ عَزُّوا بَعْضُكُمْ بَعْضًا وَٱبْنُوا أَحَدُكُمُ ٱلْآخَرَ، كَمَا تَفْعَلُونَ أَيْضًا.",
    "1PE.1.3": "مُبَارَكٌ ٱللهُ أَبُو رَبِّنَا يَسُوعَ ٱلْمَسِيحِ، ٱلَّذِي حَسَبَ رَحْمَتِهِ ٱلْكَثِيرَةِ وَلَدَنَا ثَانِيَةً لِرَجَاءٍ حَيٍّ، بِقِيَامَةِ يَسُوعَ ٱلْمَسِيحِ مِنَ ٱلْأَمْوَاتِ،",
    "JHN.1.5": "وَٱلنُّورُ يُضِيءُ فِي ٱلظُّلْمَةِ، وَٱلظُّلْمَةُ لَمْ تُدْرِكْهُ.",
    "LEV.19.18": "لَا تَنْتَقِمْ وَلَا تَحْقِدْ عَلَى أَبْنَاءِ شَعْبِكَ، بَلْ تُحِبُّ قَرِيبَكَ كَنَفْسِكَ. أَنَا ٱلرَّبُّ.",
    "MAT.5.8": "طُوبَى لِلْأَنْقِيَاءِ ٱلْقَلْبِ، لِأَنَّهُمْ يُعَايِنُونَ ٱللهَ.",
    "ISA.61.1": "رُوحُ ٱلسَّيِّدِ ٱلرَّبِّ عَلَيَّ، لِأَنَّ ٱلرَّبَّ مَسَحَنِي لِأُبَشِّرَ ٱلْمَسَاكِينَ، أَرْسَلَنِي لِأَعْصِبَ مُنْكَسِرِي ٱلْقَلْبِ، لِأُنَادِيَ لِلْمَسْبِيِّينَ بِٱلْعِتْقِ، وَلِلْمَأْسُورِينَ بِٱلْإِطْلَاقِ.",
    "RUT.1.16": "فَقَالَتْ رَاعُوثُ: «لَا تُلِحِّي عَلَيَّ أَنْ أَتْرُكَكِ وَأَرْجِعَ عَنْكِ، لِأَنَّهُ حَيْثُمَا ذَهَبْتِ أَذْهَبُ وَحَيْثُمَا بِتِّ أَبِيتُ. شَعْبُكِ شَعْبِي وَإِلَهُكِ إِلَهِي.",
    "JHN.8.12": "ثُمَّ كَلَّمَهُمْ يَسُوعُ أَيْضًا قَائِلًا: «أَنَا هُوَ نُورُ ٱلْعَالَمِ. مَنْ يَتْبَعْنِي فَلَا يَمْشِي فِي ٱلظُّلْمَةِ بَلْ يَكُونُ لَهُ نُورُ ٱلْحَيَاةِ».",
    "2TH.3.3": "أَمِينٌ هُوَ ٱلرَّبُّ ٱلَّذِي سَيُثَبِّتُكُمْ وَيَحْفَظُكُمْ مِنَ ٱلشِّرِّيرِ.",
    "PSA.34.4": "طَلَبْتُ إِلَى ٱلرَّبِّ فَٱسْتَجَابَ لِي، وَمِنْ كُلِّ مَخَاوِفِي أَنْقَذَنِي.",
    "TIT.3.5": "لَا بِأَعْمَالٍ فِي بِرٍّ عَمِلْنَاهَا نَحْنُ، بَلْ بِمُقْتَضَى رَحْمَتِهِ - خَلَّصَنَا بِغُسْلِ ٱلْمِيلَادِ ٱلثَّانِي وَتَجْدِيدِ ٱلرُّوحِ ٱلْقُدُسِ،",
    "LUK.12.32": "«لَا تَخَفْ، أَيُّهَا ٱلْقَطِيعُ ٱلصَّغِيرُ، لِأَنَّ أَبَاكُمْ قَدْ سُرَّ أَنْ يُعْطِيَكُمُ ٱلْمَلَكُوتَ.",
    "PSA.23.6": "إِنَّمَا خَيْرٌ وَرَحْمَةٌ يَتْبَعَانِنِي كُلَّ أَيَّامِ حَيَاتِي، وَأَسْكُنُ فِي بَيْتِ ٱلرَّبِّ إِلَى مَدَى ٱلْأَيَّامِ.",
    "MIC.7.18-19": "مَنْ هُوَ إِلَهٌ مِثْلُكَ غَافِرٌ ٱلْإِثْمَ وَصَافِحٌ عَنِ ٱلذَّنْبِ لِبَقِيَّةِ مِيرَاثِهِ! لَا يَحْفَظُ إِلَى ٱلْأَبَدِ غَضَبَهُ، فَإِنَّهُ يُسَرُّ بِٱلرَّأْفَةِ. يَعُودُ يَرْحَمُنَا، يَدُوسُ آثَامَنَا، وَتُطْرَحُ فِي أَعْمَاقِ ٱلْبَحْرِ جَمِيعُ خَطَايَاهُمْ.",
    "2CO.4.7": "وَلَكِنْ لَنَا هَذَا ٱلْكَنْزُ فِي أَوَانٍ خَزَفِيَّةٍ، لِيَكُونَ فَضْلُ ٱلْقُوَّةِ لِلهِ لَا مِنَّا.",
    "GEN.50.20": "أَنْتُمْ قَصَدْتُمْ لِي شَرًّا، أَمَّا ٱللهُ فَقَصَدَ بِهِ خَيْرًا، لِكَيْ يَفْعَلَ كَمَا ٱلْيَوْمَ، لِيُحْيِيَ شَعْبًا كَثِيرًا.",
    "PSA.32.8": "«أُعَلِّمُكَ وَأُرْشِدُكَ ٱلطَّرِيقَ ٱلَّتِي تَسْلُكُهَا. أَنْصَحُكَ. عَيْنِي عَلَيْكَ.",
    "MAT.6.19-21": "«لَا تَكْنِزُوا لَكُمْ كُنُوزًا عَلَى ٱلْأَرْضِ حَيْثُ يُفْسِدُ ٱلسُّوسُ وَٱلصَّدَأُ، وَحَيْثُ يَنْقُبُ ٱلسَّارِقُونَ وَيَسْرِقُونَ. بَلِ ٱكْنِزُوا لَكُمْ كُنُوزًا فِي ٱلسَّمَاءِ، حَيْثُ لَا يُفْسِدُ سُوسٌ وَلَا صَدَأٌ، وَحَيْثُ لَا يَنْقُبُ سَارِقُونَ وَلَا يَسْرِقُونَ، لِأَنَّهُ حَيْثُ يَكُونُ كَنْزُكَ هُنَاكَ يَكُونُ قَلْبُكَ أَيْضًا.",
    "ROM.15.13": "وَلْيَمْلَأْكُمْ إِلَهُ ٱلرَّجَاءِ كُلَّ سُرُورٍ وَسَلَامٍ فِي ٱلْإِيمَانِ، لِتَزْدَادُوا فِي ٱلرَّجَاءِ بِقُوَّةِ ٱلرُّوحِ ٱلْقُدُسِ.",
    "JHN.3.30": "يَنْبَغِي أَنَّ ذَلِكَ يَزِيدُ وَأَنِّي أَنَا أَنْقُصُ.",
    "DEU.7.9": "فَٱعْلَمْ أَنَّ ٱلرَّبَّ إِلَهَكَ هُوَ ٱللهُ، ٱلْإِلَهُ ٱلْأَمِينُ، ٱلْحَافِظُ ٱلْعَهْدَ وَٱلْإِحْسَانَ لِلَّذِينَ يُحِبُّونَهُ وَيَحْفَظُونَ وَصَايَاهُ إِلَى أَلْفِ جِيلٍ،",
    "HEB.13.8": "يَسُوعُ ٱلْمَسِيحُ هُوَ هُوَ أَمْسًا وَٱلْيَوْمَ وَإِلَى ٱلْأَبَدِ.",
    "EPH.2.4-5": "ٱللهُ ٱلَّذِي هُوَ غَنِيٌّ فِي ٱلرَّحْمَةِ، مِنْ أَجْلِ مَحَبَّتِهِ ٱلْكَثِيرَةِ ٱلَّتِي أَحَبَّنَا بِهَا، وَنَحْنُ أَمْوَاتٌ بِٱلْخَطَايَا أَحْيَانَا مَعَ ٱلْمَسِيحِ - بِٱلنِّعْمَةِ أَنْتُمْ مُخَلَّصُونَ -",
    "PRO.10.12": "اَلْبُغْضَةُ تُهَيِّجُ خُصُومَاتٍ، وَٱلْمَحَبَّةُ تَسْتُرُ كُلَّ ٱلذُّنُوبِ.",
    "3JN.1.4": "لَيْسَ لِي فَرَحٌ أَعْظَمُ مِنْ هَذَا: أَنْ أَسْمَعَ عَنْ أَوْلَادِي أَنَّهُمْ يَسْلُكُونَ بِٱلْحَقِّ.",
    "ECC.3.1": "لِكُلِّ شَيْءٍ زَمَانٌ، وَلِكُلِّ أَمْرٍ تَحْتَ ٱلسَّمَاوَاتِ وَقْتٌ:",
    "PSA.4.8": "بِسَلَامَةٍ أَضْطَجِعُ بَلْ أَيْضًا أَنَامُ، لِأَنَّكَ أَنْتَ يَارَبُّ مُنْفَرِدًا فِي طُمَأْنِينَةٍ تُسَكِّنُنِي.",
    "1CO.15.55-57": "«أَيْنَ شَوْكَتُكَ يَا مَوْتُ؟ أَيْنَ غَلَبَتُكِ يَا هَاوِيَةُ؟» أَمَّا شَوْكَةُ ٱلْمَوْتِ فَهِيَ ٱلْخَطِيَّةُ، وَقُوَّةُ ٱلْخَطِيَّةِ هِيَ ٱلنَّامُوسُ. وَلَكِنْ شُكْرًا لِلهِ ٱلَّذِي يُعْطِينَا ٱلْغَلَبَةَ بِرَبِّنَا يَسُوعَ ٱلْمَسِيحِ.",
    "JER.29.11": "لِأَنِّي عَرَفْتُ ٱلْأَفْكَارَ ٱلَّتِي أَنَا مُفْتَكِرٌ بِهَا عَنْكُمْ، يَقُولُ ٱلرَّبُّ، أَفْكَارَ سَلَامٍ لَا شَرٍّ، لِأُعْطِيَكُمْ آخِرَةً وَرَجَاءً.",
    "PRO.11.25": "ٱلنَّفْسُ ٱلسَّخِيَّةُ تُسَمَّنُ، وَٱلْمُرْوِي هُوَ أَيْضًا يُرْوَى.",
    "2PE.3.18": "وَلَكِنِ ٱنْمُوا فِي ٱلنِّعْمَةِ وَفِي مَعْرِفَةِ رَبِّنَا وَمُخَلِّصِنَا يَسُوعَ ٱلْمَسِيحِ. لَهُ ٱلْمَجْدُ ٱلْآنَ وَإِلَى يَوْمِ ٱلدَّهْرِ. آمِينَ.",
    "2TI.2.15": "ٱجْتَهِدْ أَنْ تُقِيمَ نَفْسَكَ لِلهِ مُزَكًّى، عَامِلًا لَا يُخْزَى، مُفَصِّلًا كَلِمَةَ ٱلْحَقِّ بِٱلِٱسْتِقَامَةِ.",
    "PSA.107.1": "اِحْمَدُوا ٱلرَّبَّ لِأَنَّهُ صَالِحٌ، لِأَنَّ إِلَى ٱلْأَبَدِ رَحْمَتَهُ.",
    "2CO.9.8": "وَٱللهُ قَادِرٌ أَنْ يَزِيدَكُمْ كُلَّ نِعْمَةٍ، لِكَيْ تَكُونُوا وَلَكُمْ كُلُّ ٱكْتِفَاءٍ كُلَّ حِينٍ فِي كُلِّ شَيْءٍ، تَزْدَادُونَ فِي كُلِّ عَمَلٍ صَالِحٍ.",
    "JHN.10.27-28": "خِرَافِي تَسْمَعُ صَوْتِي، وَأَنَا أَعْرِفُهَا فَتَتْبَعُنِي. وَأَنَا أُعْطِيهَا حَيَاةً أَبَدِيَّةً، وَلَنْ تَهْلِكَ إِلَى ٱلْأَبَدِ، وَلَا يَخْطَفُهَا أَحَدٌ مِنْ يَدِي.",
    "1CO.10.13": "لَمْ تُصِبْكُمْ تَجْرِبَةٌ إِلَّا بَشَرِيَّةٌ. وَلَكِنَّ ٱللهَ أَمِينٌ، ٱلَّذِي لَا يَدَعُكُمْ تُجَرَّبُونَ فَوْقَ مَا تَسْتَطِيعُونَ، بَلْ سَيَجْعَلُ مَعَ ٱلتَّجْرِبَةِ أَيْضًا ٱلْمَنْفَذَ، لِتَسْتَطِيعُوا أَنْ تَحْتَمِلُوا.",
    "MRK.11.24": "لِذَلِكَ أَقُولُ لَكُمْ: كُلُّ مَا تَطْلُبُونَهُ حِينَمَا تُصَلُّونَ، فَآمِنُوا أَنْ تَنَالُوهُ، فَيَكُونَ لَكُمْ.",
    "GAL.5.13-14": "فَإِنَّكُمْ إِنَّمَا دُعِيتُمْ لِلْحُرِّيَّةِ أَيُّهَا ٱلْإِخْوَةُ. غَيْرَ أَنَّهُ لَا تُصَيِّرُوا ٱلْحُرِّيَّةَ فُرْصَةً لِلْجَسَدِ، بَلْ بِٱلْمَحَبَّةِ ٱخْدِمُوا بَعْضُكُمْ بَعْضًا. لِأَنَّ كُلَّ ٱلنَّامُوسِ فِي كَلِمَةٍ وَاحِدَةٍ يُكْمَلُ: «تُحِبُّ قَرِيبَكَ كَنَفْسِكَ».",
    "ACT.4.12": "وَلَيْسَ بِأَحَدٍ غَيْرِهِ ٱلْخَلَاصُ. لِأَنْ لَيْسَ ٱسْمٌ آخَرُ تَحْتَ ٱلسَّمَاءِ، قَدْ أُعْطِيَ بَيْنَ ٱلنَّاسِ، بِهِ يَنْبَغِي أَنْ نَخْلُصَ».",
    "ISA.41.10": "لَا تَخَفْ لِأَنِّي مَعَكَ. لَا تَتَلَفَّتْ لِأَنِّي إِلَهُكَ. قَدْ أَيَّدْتُكَ وَأَعَنْتُكَ وَعَضَدْتُكَ بِيَمِينِ بِرِّي.",
    "1JN.4.16": "وَنَحْنُ قَدْ عَرَفْنَا وَصَدَّقْنَا ٱلْمَحَبَّةَ ٱلَّتِي لِلهِ فِينَا. ٱللهُ مَحَبَّةٌ، وَمَنْ يَثْبُتْ فِي ٱلْمَحَبَّةِ، يَثْبُتْ فِي ٱللهِ وَٱللهُ فِيهِ.",
    "EXO.15.2": "ٱلرَّبُّ قُوَّتِي وَنَشِيدِي، وَقَدْ صَارَ خَلَاصِي. هَذَا إِلَهِي فَأُمَجِّدُهُ، إِلَهُ أَبِي فَأُرَفِّعُهُ.",
    "REV.22.13": "أَنَا ٱلْأَلِفُ وَٱلْيَاءُ، ٱلْبِدَايَةُ وَٱلنِّهَايَةُ، ٱلْأَوَّلُ وَٱلْآخِرُ».",
    "2TI.4.7-8": "قَدْ جَاهَدْتُ ٱلْجِهَادَ ٱلْحَسَنَ، أَكْمَلْتُ ٱلسَّعْيَ، حَفِظْتُ ٱلْإِيمَانَ، وَأَخِيرًا قَدْ وُضِعَ لِي إِكْلِيلُ ٱلْبِرِّ، ٱلَّذِي يَهَبُهُ لِي فِي ذَلِكَ ٱلْيَوْمِ، ٱلرَّبُّ ٱلدَّيَّانُ ٱلْعَادِلُ، وَلَيْسَ لِي فَقَطْ، بَلْ لِجَمِيعِ ٱلَّذِينَ يُحِبُّونَ ظُهُورَهُ أَيْضًا.",
    "PSA.121.7-8": "ٱلرَّبُّ يَحْفَظُكَ مِنْ كُلِّ شَرٍّ. يَحْفَظُ نَفْسَكَ. ٱلرَّبُّ يَحْفَظُ خُرُوجَكَ وَدُخُولَكَ مِنَ ٱلْآنَ وَإِلَى ٱلدَّهْرِ.",
    "ISA.53.5": "وَهُوَ مَجْرُوحٌ لِأَجْلِ مَعَاصِينَا، مَسْحُوقٌ لِأَجْلِ آثَامِنَا. تَأْدِيبُ سَلَامِنَا عَلَيْهِ، وَبِحُبُرِهِ شُفِينَا.",
    "ROM.10.9-10": "لِأَنَّكَ إِنِ ٱعْتَرَفْتَ بِفَمِكَ بِٱلرَّبِّ يَسُوعَ، وَآمَنْتَ بِقَلْبِكَ أَنَّ ٱللهَ أَقَامَهُ مِنَ ٱلْأَمْوَاتِ، خَلَصْتَ. لِأَنَّ ٱلْقَلْبَ يُؤْمَنُ بِهِ لِلْبِرِّ، وَٱلْفَمَ يُعْتَرَفُ بِهِ لِلْخَلَاصِ.",
    "1PE.2.24": "ٱلَّذِي حَمَلَ هُوَ نَفْسُهُ خَطَايَانَا فِي جَسَدِهِ عَلَى ٱلْخَشَبَةِ، لِكَيْ نَمُوتَ عَنِ ٱلْخَطَايَا فَنَحْيَا لِلْبِرِّ. ٱلَّذِي بِجَلْدَتِهِ شُفِيتُمْ.",
    "2PE.1.3": "كَمَا أَنَّ قُدْرَتَهُ ٱلْإِلَهِيَّةَ قَدْ وَهَبَتْ لَنَا كُلَّ مَا هُوَ لِلْحَيَاةِ وَٱلتَّقْوَى، بِمَعْرِفَةِ ٱلَّذِي دَعَانَا بِٱلْمَجْدِ وَٱلْفَضِيلَةِ،",
    "PSA.94.19": "عِنْدَ كَثْرَةِ هُمُومِي فِي دَاخِلِي، تَعْزِيَاتُكَ تُلَذِّذُ نَفْسِي.",
    "MAT.6.34": "فَلَا تَهْتَمُّوا لِلْغَدِ، لِأَنَّ ٱلْغَدَ يَهْتَمُّ بِمَا لِنَفْسِهِ. يَكْفِي ٱلْيَوْمَ شَرُّهُ.",
    "PHP.4.4": "اِفْرَحُوا فِي ٱلرَّبِّ كُلَّ حِينٍ، وَأَقُولُ أَيْضًا: ٱفْرَحُوا.",
    "EPH.2.8-9": "لِأَنَّكُمْ بِٱلنِّعْمَةِ مُخَلَّصُونَ، بِٱلْإِيمَانِ، وَذَلِكَ لَيْسَ مِنْكُمْ. هُوَ عَطِيَّةُ ٱللهِ. لَيْسَ مِنْ أَعْمَالٍ كَيْلَا يَفْتَخِرَ أَحَدٌ.",
    "1PE.5.10": "وَإِلَهُ كُلِّ نِعْمَةٍ ٱلَّذِي دَعَانَا إِلَى مَجْدِهِ ٱلْأَبَدِيِّ فِي ٱلْمَسِيحِ يَسُوعَ، بَعْدَمَا تَأَلَّمْتُمْ يَسِيرًا، هُوَ يُكَمِّلُكُمْ، وَيُثَبِّتُكُمْ، وَيُقَوِّيكُمْ، وَيُمَكِّنُكُمْ.",
    "ACT.1.8": "لَكِنَّكُمْ سَتَنَالُونَ قُوَّةً مَتَى حَلَّ ٱلرُّوحُ ٱلْقُدُسُ عَلَيْكُمْ، وَتَكُونُونَ لِي شُهُودًا فِي أُورُشَلِيمَ وَفِي كُلِّ ٱلْيَهُودِيَّةِ وَٱلسَّامِرَةِ وَإِلَى أَقْصَى ٱلْأَرْضِ».",
    "JHN.3.16": "لِأَنَّهُ هَكَذَا أَحَبَّ ٱللهُ ٱلْعَالَمَ حَتَّى بَذَلَ ٱبْنَهُ ٱلْوَحِيدَ، لِكَيْ لَا يَهْلِكَ كُلُّ مَنْ يُؤْمِنُ بِهِ، بَلْ تَكُونُ لَهُ ٱلْحَيَاةُ ٱلْأَبَدِيَّةُ.",
    "1CH.16.11": "ٱطْلُبُوا ٱلرَّبَّ وَعِزَّهُ. ٱلْتَمِسُوا وَجْهَهُ دَائِمًا.",
    "1TI.4.12": "لَا يَسْتَهِنْ أَحَدٌ بِحَدَاثَتِكَ، بَلْ كُنْ قُدْوَةً لِلْمُؤْمِنِينَ: فِي ٱلْكَلَامِ، فِي ٱلتَّصَرُّفِ، فِي ٱلْمَحَبَّةِ، فِي ٱلرُّوحِ، فِي ٱلْإِيمَانِ، فِي ٱلطَّهَارَةِ.",
    "EPH.6.10-11": "أَخِيرًا يَا إِخْوَتِي، تَقَوَّوْا فِي ٱلرَّبِّ وَفِي شِدَّةِ قُوَّتِهِ. ٱلْبَسُوا سِلَاحَ ٱللهِ ٱلْكَامِلَ لِكَيْ تَقْدِرُوا أَنْ تَثْبُتُوا ضِدَّ مَكَايِدِ إِبْلِيسَ.",
    "JHN.15.12-13": "«هَذِهِ هِيَ وَصِيَّتِي أَنْ تُحِبُّوا بَعْضُكُمْ بَعْضًا كَمَا أَحْبَبْتُكُمْ. لَيْسَ لِأَحَدٍ حُبٌّ أَعْظَمُ مِنْ هَذَا: أَنْ يَضَعَ أَحَدٌ نَفْسَهُ لِأَجْلِ أَحِبَّائِهِ.",
    "ZEC.4.6": "فَأَجَابَ وَكَلَّمَنِي قَائِلًا: «هَذِهِ كَلِمَةُ ٱلرَّبِّ إِلَى زَرُبَّابِلَ قَائِلًا: لَا بِٱلْقُدْرَةِ وَلَا بِٱلْقُوَّةِ، بَلْ بِرُوحِي قَالَ رَبُّ ٱلْجُنُودِ.",
    "ROM.8.37": "وَلَكِنَّنَا فِي هَذِهِ جَمِيعِهَا يَعْظُمُ ٱنْتِصَارُنَا بِٱلَّذِي أَحَبَّنَا.",
    "PRO.1.7": "مَخَافَةُ ٱلرَّبِّ رَأْسُ ٱلْمَعْرِفَةِ، أَمَّا ٱلْجَاهِلُونَ فَيَحْتَقِرُونَ ٱلْحِكْمَةَ وَٱلْأَدَبَ.",
    "PSA.27.14": "ٱنْتَظِرِ ٱلرَّبَّ. لِيَتَشَدَّدْ وَلْيَتَشَجَّعْ قَلْبُكَ، وَٱنْتَظِرِ ٱلرَّبَّ.",
    "MRK.16.15": "وَقَالَ لَهُمُ: «ٱذْهَبُوا إِلَى ٱلْعَالَمِ أَجْمَعَ وَٱكْرِزُوا بِٱلْإِنْجِيلِ لِلْخَلِيقَةِ كُلِّهَا.",
    "JHN.16.33": "قَدْ كَلَّمْتُكُمْ بِهَذَا لِيَكُونَ لَكُمْ فِيَّ سَلَامٌ. فِي ٱلْعَالَمِ سَيَكُونُ لَكُمْ ضِيقٌ، وَلَكِنْ ثِقُوا: أَنَا قَدْ غَلَبْتُ ٱلْعَالَمَ».",
    "1PE.4.8": "وَلَكِنْ قَبْلَ كُلِّ شَيْءٍ، لِتَكُنْ مَحَبَّتُكُمْ بَعْضِكُمْ لِبَعْضٍ شَدِيدَةً، لِأَنَّ ٱلْمَحَبَّةَ تَسْتُرُ كَثْرَةً مِنَ ٱلْخَطَايَا.",
    "PRO.3.5-6": "تَوَكَّلْ عَلَى ٱلرَّبِّ بِكُلِّ قَلْبِكَ، وَعَلَى فَهْمِكَ لَا تَعْتَمِدْ. فِي كُلِّ طُرُقِكَ ٱعْرِفْهُ، وَهُوَ يُقَوِّمُ سُبُلَكَ.",
    "ROM.8.31-32": "فَمَاذَا نَقُولُ لِهَذَا؟ إِنْ كَانَ ٱللهُ مَعَنَا، فَمَنْ عَلَيْنَا؟ اَلَّذِي لَمْ يُشْفِقْ عَلَى ٱبْنِهِ، بَلْ بَذَلَهُ لِأَجْلِنَا أَجْمَعِينَ، كَيْفَ لَا يَهَبُنَا أَيْضًا مَعَهُ كُلَّ شَيْءٍ؟",
    "HAB.3.19": "اَلرَّبُّ ٱلسَّيِّدُ قُوَّتِي، وَيَجْعَلُ قَدَمَيَّ كَٱلْأَيَائِلِ، وَيُمَشِّينِي عَلَى مُرْتَفَعَاتِي. لِرَئِيسِ ٱلْمُغَنِّينَ عَلَى آلَاتِي ذَوَاتِ ٱلْأَوْتَارِ.",
    "MIC.6.8": "قَدْ أَخْبَرَكَ أَيُّهَا ٱلْإِنْسَانُ مَا هُوَ صَالِحٌ، وَمَاذَا يَطْلُبُهُ مِنْكَ ٱلرَّبُّ، إِلَّا أَنْ تَصْنَعَ ٱلْحَقَّ وَتُحِبَّ ٱلرَّحْمَةَ، وَتَسْلُكَ مُتَوَاضِعًا مَعَ إِلَهِكَ.",
    "MAT.17.20": "فَقَالَ لَهُمْ يَسُوعُ: «لِعَدَمِ إِيمَانِكُمْ. فَٱلْحَقَّ أَقُولُ لَكُمْ: لَوْ كَانَ لَكُمْ إِيمَانٌ مِثْلُ حَبَّةِ خَرْدَلٍ لَكُنْتُمْ تَقُولُونَ لِهَذَا ٱلْجَبَلِ: ٱنْتَقِلْ مِنْ هُنَا إِلَى هُنَاكَ فَيَنْتَقِلُ، وَلَا يَكُونُ شَيْءٌ غَيْرَ مُمْكِنٍ لَدَيْكُمْ.",
    "MRK.10.45": "لِأَنَّ ٱبْنَ ٱلْإِنْسَانِ أَيْضًا لَمْ يَأْتِ لِيُخْدَمَ بَلْ لِيَخْدِمَ وَلِيَبْذِلَ نَفْسَهُ فِدْيَةً عَنْ كَثِيرِينَ».",
    "DAN.12.3": "وَٱلْفَاهِمُونَ يَضِيئُونَ كَضِيَاءِ ٱلْجَلَدِ، وَٱلَّذِينَ رَدُّوا كَثِيرِينَ إِلَى ٱلْبِرِّ كَٱلْكَوَاكِبِ إِلَى أَبَدِ ٱلدُّهُورِ.",
    "PHP.4.6-7": "لَا تَهْتَمُّوا بِشَيْءٍ، بَلْ فِي كُلِّ شَيْءٍ بِٱلصَّلَاةِ وَٱلدُّعَاءِ مَعَ ٱلشُّكْرِ، لِتُعْلَمْ طِلْبَاتُكُمْ لَدَى ٱللهِ. وَسَلَامُ ٱللهِ ٱلَّذِي يَفُوقُ كُلَّ عَقْلٍ، يَحْفَظُ قُلُوبَكُمْ وَأَفْكَارَكُمْ فِي ٱلْمَسِيحِ يَسُوعَ.",
    "2CO.4.8-9": "مُكْتَئِبِينَ فِي كُلِّ شَيْءٍ، لَكِنْ غَيْرَ مُتَضَايِقِينَ. مُتَحَيِّرِينَ، لَكِنْ غَيْرَ يَائِسِينَ. مُضْطَهَدِينَ، لَكِنْ غَيْرَ مَتْرُوكِينَ. مَطْرُوحِينَ، لَكِنْ غَيْرَ هَالِكِينَ.",
    "PRO.16.24": "اَلْكَلَامُ ٱلْحَسَنُ شَهْدُ عَسَلٍ، حُلْوٌ لِلنَّفْسِ وَشِفَاءٌ لِلْعِظَامِ.",
    "1JN.1.5": "وَهَذَا هُوَ ٱلْخَبَرُ ٱلَّذِي سَمِعْنَاهُ مِنْهُ وَنُخْبِرُكُمْ بِهِ: إِنَّ ٱللهَ نُورٌ وَلَيْسَ فِيهِ ظُلْمَةٌ ٱلْبَتَّةَ.",
    "DEU.6.4-5": "«اِسْمَعْ يَا إِسْرَائِيلُ: ٱلرَّبُّ إِلَهُنَا رَبٌّ وَاحِدٌ. فَتُحِبُّ ٱلرَّبَّ إِلَهَكَ مِنْ كُلِّ قَلْبِكَ وَمِنْ كُلِّ نَفْسِكَ وَمِنْ كُلِّ قُوَّتِكَ.",
    "PSA.23.4": "أَيْضًا إِذَا سِرْتُ فِي وَادِي ظِلِّ ٱلْمَوْتِ لَا أَخَافُ شَرًّا، لِأَنَّكَ أَنْتَ مَعِي. عَصَاكَ وَعُكَّازُكَ هُمَا يُعَزِّيَانِنِي.",
    "ROM.8.18": "فَإِنِّي أَحْسِبُ أَنَّ آلَامَ ٱلزَّمَانِ ٱلْحَاضِرِ لَا تُقَاسُ بِٱلْمَجْدِ ٱلْعَتِيدِ أَنْ يُسْتَعْلَنَ فِينَا.",
    "REV.3.20": "هَأَنَذَا وَاقِفٌ عَلَى ٱلْبَابِ وَأَقْرَعُ. إِنْ سَمِعَ أَحَدٌ صَوْتِي وَفَتَحَ ٱلْبَابَ، أَدْخُلُ إِلَيْهِ وَأَتَعَشَّى مَعَهُ وَهُوَ مَعِي.",
    "ISA.30.15": "لِأَنَّهُ هَكَذَا قَالَ ٱلسَّيِّدُ ٱلرَّبُّ قُدُّوسُ إِسْرَائِيلَ: «بِٱلرُّجُوعِ وَٱلسُّكُونِ تَخْلُصُونَ. بِٱلْهُدُوءِ وَٱلطُّمَأْنِينَةِ تَكُونُ قُوَّتُكُمْ». فَلَمْ تَشَاءُوا.",
    "JHN.6.35": "فَقَالَ لَهُمْ يَسُوعُ: «أَنَا هُوَ خُبْزُ ٱلْحَيَاةِ. مَنْ يُقْبِلْ إِلَيَّ فَلَا يَجُوعُ، وَمَنْ يُؤْمِنْ بِي فَلَا يَعْطَشُ أَبَدًا.",
    "ACT.20.35": "فِي كُلِّ شَيْءٍ أَرَيْتُكُمْ أَنَّهُ هَكَذَا يَنْبَغِي أَنَّكُمْ تَتْعَبُونَ وَتَعْضُدُونَ ٱلضُّعَفَاءَ، مُتَذَكِّرِينَ كَلِمَاتِ ٱلرَّبِّ يَسُوعَ أَنَّهُ قَالَ: مَغْبُوطٌ هُوَ ٱلْعَطَاءُ أَكْثَرُ مِنَ ٱلْأَخْذِ».",
    "JAS.5.16": "اِعْتَرِفُوا بَعْضُكُمْ لِبَعْضٍ بِٱلزَلَّاتِ، وَصَلُّوا بَعْضُكُمْ لِأَجْلِ بَعْضٍ، لِكَيْ تُشْفَوْا. طَلِبَةُ ٱلْبَارِّ تَقْتَدِرُ كَثِيرًا فِي فِعْلِهَا.",
    "ISA.1.18": "هَلُمَّ نَتَحَاجَجْ، يَقُولُ ٱلرَّبُّ. إِنْ كَانَتْ خَطَايَاكُمْ كَٱلْقِرْمِزِ تَبْيَضُّ كَٱلثَّلْجِ. إِنْ كَانَتْ حَمْرَاءَ كَٱلدُّودِيِّ تَصِيرُ كَٱلصُّوفِ.",
    "PRO.27.17": "ٱلْحَدِيدُ بِٱلْحَدِيدِ يُحَدَّدُ، وَٱلْإِنْسَانُ يُحَدِّدُ وَجْهَ صَاحِبِهِ.",
    "JHN.1.14": "وَٱلْكَلِمَةُ صَارَ جَسَدًا وَحَلَّ بَيْنَنَا، وَرَأَيْنَا مَجْدَهُ، مَجْدًا كَمَا لِوَحِيدٍ مِنَ ٱلْآبِ، مَمْلُوءًا نِعْمَةً وَحَقًّا.",
    "1JN.1.9": "إِنِ ٱعْتَرَفْنَا بِخَطَايَانَا فَهُوَ أَمِينٌ وَعَادِلٌ، حَتَّى يَغْفِرَ لَنَا خَطَايَانَا وَيُطَهِّرَنَا مِنْ كُلِّ إِثْمٍ.",
    "MAT.6.33": "لَكِنِ ٱطْلُبُوا أَوَّلًا مَلَكُوتَ ٱللهِ وَبِرَّهُ، وَهَذِهِ كُلُّهَا تُزَادُ لَكُمْ.",
    "1CO.13.12": "فَإِنَّنَا نَنْظُرُ ٱلْآنَ فِي مِرْآةٍ، فِي لُغْزٍ، لَكِنْ حِينَئِذٍ وَجْهًا لِوَجْهٍ. ٱلْآنَ أَعْرِفُ بَعْضَ ٱلْمَعْرِفَةِ، لَكِنْ حِينَئِذٍ سَأَعْرِفُ كَمَا عُرِفْتُ.",
    "REV.1.8": "«أَنَا هُوَ ٱلْأَلِفُ وَٱلْيَاءُ، ٱلْبِدَايَةُ وَٱلنِّهَايَةُ» يَقُولُ ٱلرَّبُّ ٱلْكَائِنُ وَٱلَّذِي كَانَ وَٱلَّذِي يَأْتِي، ٱلْقَادِرُ عَلَى كُلِّ شَيْءٍ.",
    "PSA.28.7": "ٱلرَّبُّ عِزِّي وَتُرْسِي. عَلَيْهِ ٱتَّكَلَ قَلْبِي، فَٱنْتَصَرْتُ. وَيَبْتَهِجُ قَلْبِي وَبِأُغْنِيَتِي أَحْمَدُهُ.",
    "DEU.31.8": "وَٱلرَّبُّ سَائِرٌ أَمَامَكَ. هُوَ يَكُونُ مَعَكَ. لَا يُهْمِلُكَ وَلَا يَتْرُكُكَ. لَا تَخَفْ وَلَا تَرْتَعِبْ».",
    "HEB.4.12": "لِأَنَّ كَلِمَةَ ٱللهِ حَيَّةٌ وَفَعَّالَةٌ وَأَمْضَى مِنْ كُلِّ سَيْفٍ ذِي حَدَّيْنِ، وَخَارِقَةٌ إِلَى مَفْرَقِ ٱلنَّفْسِ وَٱلرُّوحِ وَٱلْمَفَاصِلِ وَٱلْمِخَاخِ، وَمُمَيِّزَةٌ أَفْكَارَ ٱلْقَلْبِ وَنِيَّاتِهِ.",
    "MAT.19.14": "أَمَّا يَسُوعُ فَقَالَ: «دَعُوا ٱلْأَوْلَادَ يَأْتُونَ إِلَيَّ وَلَا تَمْنَعُوهُمْ لِأَنَّ لِمِثْلِ هَؤُلَاءِ مَلَكُوتَ ٱلسَّمَاوَاتِ».",
    "JAS.4.7-8": "فَٱخْضَعُوا لِلهِ. قَاوِمُوا إِبْلِيسَ فَيَهْرُبَ مِنْكُمْ. اِقْتَرِبُوا إِلَى ٱللهِ فَيَقْتَرِبَ إِلَيْكُمْ. نَقُّوا أَيْدِيَكُمْ أَيُّهَا ٱلْخُطَاةُ، وَطَهِّرُوا قُلُوبَكُمْ يَا ذَوِي ٱلرَّأْيَيْنِ.",
    "PSA.139.13-14": "لِأَنَّكَ أَنْتَ ٱقْتَنَيْتَ كُلْيَتَيَّ. نَسَجْتَنِي فِي بَطْنِ أُمِّي. أَحْمَدُكَ مِنْ أَجْلِ أَنِّي قَدِ ٱمْتَزْتُ عَجَبًا. عَجِيبَةٌ هِيَ أَعْمَالُكَ، وَنَفْسِي تَعْرِفُ ذَلِكَ يَقِينًا.",
    "HOS.6.3": "لِنَعْرِفْ فَلْنَتَتَبَّعْ لِنَعْرِفَ ٱلرَّبَّ. خُرُوجُهُ يَقِينٌ كَٱلْفَجْرِ. يَأْتِي إِلَيْنَا كَٱلْمَطَرِ. كَمَطَرٍ مُتَأَخِّرٍ يَسْقِي ٱلْأَرْضَ.",
    "1CO.10.31": "فَإِذَا كُنْتُمْ تَأْكُلُونَ أَوْ تَشْرَبُونَ أَوْ تَفْعَلُونَ شَيْئًا، فَٱفْعَلُوا كُلَّ شَيْءٍ لِمَجْدِ ٱللهِ.",
    "JOS.1.8": "لَا يَبْرَحْ سِفْرُ هَذِهِ ٱلشَّرِيعَةِ مِنْ فَمِكَ، بَلْ تَلْهَجُ فِيهِ نَهَارًا وَلَيْلًا، لِكَيْ تَتَحَفَّظَ لِلْعَمَلِ حَسَبَ كُلِّ مَا هُوَ مَكْتُوبٌ فِيهِ. لِأَنَّكَ حِينَئِذٍ تُصْلِحُ طَرِيقَكَ وَحِينَئِذٍ تُفْلِحُ.",
    "2CH.7.14": "فَإِذَا تَوَاضَعَ شَعْبِي ٱلَّذِينَ دُعِيَ ٱسْمِي عَلَيْهِمْ وَصَلَّوْا وَطَلَبُوا وَجْهِي، وَرَجَعُوا عَنْ طُرُقِهِمِ ٱلرَّدِيةِ فَإِنَّنِي أَسْمَعُ مِنَ ٱلسَّمَاءِ وَأَغْفِرُ خَطِيَّتَهُمْ وَأُبْرِئُ أَرْضَهُمْ.",
    "PSA.19.14": "لِتَكُنْ أَقْوَالُ فَمِي وَفِكْرُ قَلْبِي مَرْضِيَّةً أَمَامَكَ يَارَبُّ، صَخْرَتِي وَوَلِيِّي.",
    "JHN.14.1-3": "«لَا تَضْطَرِبْ قُلُوبُكُمْ. أَنْتُمْ تُؤْمِنُونَ بِٱللهِ فَآمِنُوا بِي. فِي بَيْتِ أَبِي مَنَازِلُ كَثِيرَةٌ، وَإِلَّا فَإِنِّي كُنْتُ قَدْ قُلْتُ لَكُمْ. أَنَا أَمْضِي لِأُعِدَّ لَكُمْ مَكَانًا، وَإِنْ مَضَيْتُ وَأَعْدَدْتُ لَكُمْ مَكَانًا آتِي أَيْضًا وَآخُذُكُمْ إِلَيَّ، حَتَّى حَيْثُ أَكُونُ أَنَا تَكُونُونَ أَنْتُمْ أَيْضًا،",
    "PSA.147.3": "يَشْفِي ٱلْمُنْكَسِرِي ٱلْقُلُوبِ، وَيَجْبُرُ كَسْرَهُمْ.",
    "PHP.4.19": "فَيَمْلَأُ إِلَهِي كُلَّ ٱحْتِيَاجِكُمْ بِحَسَبِ غِنَاهُ فِي ٱلْمَجْدِ فِي ٱلْمَسِيحِ يَسُوعَ.",
    "2CO.13.14": "نِعْمَةُ رَبِّنَا يَسُوعَ ٱلْمَسِيحِ، وَمَحَبَّةُ ٱللهِ، وَشَرِكَةُ ٱلرُّوحِ ٱلْقُدُسِ مَعَ جَمِيعِكُمْ. آمِينَ.",
    "1PE.3.15": "بَلْ قَدِّسُوا ٱلرَّبَّ ٱلْإِلَهَ فِي قُلُوبِكُمْ، مُسْتَعِدِّينَ دَائِمًا لِمُجَاوَبَةِ كُلِّ مَنْ يَسْأَلُكُمْ عَنْ سَبَبِ ٱلرَّجَاءِ ٱلَّذِي فِيكُمْ، بِوَدَاعَةٍ وَخَوْفٍ،",
    "MAT.25.40": "فَيُجِيبُ ٱلْمَلِكُ وَيَقُولُ لَهُمُ: ٱلْحَقَّ أَقُولُ لَكُمْ: بِمَا أَنَّكُمْ فَعَلْتُمُوهُ بِأَحَدِ إِخْوَتِي هَؤُلَاءِ ٱلْأَصَاغِرِ، فَبِي فَعَلْتُمْ.",
    "PSA.139.23-24": "ٱخْتَبِرْنِي يَا ٱللهُ وَٱعْرِفْ قَلْبِي. ٱمْتَحِنِّي وَٱعْرِفْ أَفْكَارِي. وَٱنْظُرْ إِنْ كَانَ فِيَّ طَرِيقٌ بَاطِلٌ، وَٱهْدِنِي طَرِيقًا أَبَدِيًّا.",
    "JOS.1.9": "أَمَا أَمَرْتُكَ؟ تَشَدَّدْ وَتَشَجَّعْ! لَا تَرْهَبْ وَلَا تَرْتَعِبْ لِأَنَّ ٱلرَّبَّ إِلَهَكَ مَعَكَ حَيْثُمَا تَذْهَبُ».",
    "JAS.3.17-18": "وَأَمَّا ٱلْحِكْمَةُ ٱلَّتِي مِنْ فَوْقُ فَهِيَ أَوَّلًا طَاهِرَةٌ، ثُمَّ مُسَالِمَةٌ، مُتَرَفِّقَةٌ، مُذْعِنَةٌ، مَمْلُوَّةٌ رَحْمَةً وَأَثْمَارًا صَالِحَةً، عَدِيمَةُ ٱلرَّيْبِ وَٱلرِّيَاءِ. وَثَمَرُ ٱلْبِرِّ يُزْرَعُ فِي ٱلسَّلَامِ مِنَ ٱلَّذِينَ يَفْعَلُونَ ٱلسَّلَامَ.",
    "REV.22.17": "وَٱلرُّوحُ وَٱلْعَرُوسُ يَقُولَانِ: «تَعَالَ!». وَمَنْ يَسْمَعْ فَلْيَقُلْ: «تَعَالَ!». وَمَنْ يَعْطَشْ فَلْيَأْتِ. وَمَنْ يُرِدْ فَلْيَأْخُذْ مَاءَ حَيَاةٍ مَجَّانًا.",
    "MAT.19.26": "فَنَظَرَ إِلَيْهِمْ يَسُوعُ وَقَالَ لَهُمْ: «هَذَا عِنْدَ ٱلنَّاسِ غَيْرُ مُسْتَطَاعٍ، وَلَكِنْ عِنْدَ ٱللهِ كُلُّ شَيْءٍ مُسْتَطَاعٌ».",
    "PSA.103.11-12": "لِأَنَّهُ مِثْلُ ٱرْتِفَاعِ ٱلسَّمَاوَاتِ فَوْقَ ٱلْأَرْضِ قَوِيَتْ رَحْمَتُهُ عَلَى خَائِفِيهِ. كَبُعْدِ ٱلْمَشْرِقِ مِنَ ٱلْمَغْرِبِ أَبْعَدَ عَنَّا مَعَاصِيَنَا.",
    "REV.4.11": "«أَنْتَ مُسْتَحِقٌّ أَيُّهَا ٱلرَّبُّ أَنْ تَأْخُذَ ٱلْمَجْدَ وَٱلْكَرَامَةَ وَٱلْقُدْرَةَ، لِأَنَّكَ أَنْتَ خَلَقْتَ كُلَّ ٱلْأَشْيَاءِ، وَهِيَ بِإِرَادَتِكَ كَائِنَةٌ وَخُلِقَتْ».",
    "PHP.1.21": "لِأَنَّ لِيَ ٱلْحَيَاةَ هِيَ ٱلْمَسِيحُ وَٱلْمَوْتُ هُوَ رِبْحٌ.",
    "2TI.3.16-17": "كُلُّ ٱلْكِتَابِ هُوَ مُوحًى بِهِ مِنَ ٱللهِ، وَنَافِعٌ لِلتَّعْلِيمِ وَٱلتَّوْبِيخِ، لِلتَّقْوِيمِ وَٱلتَّأْدِيبِ ٱلَّذِي فِي ٱلْبِرِّ، لِكَيْ يَكُونَ إِنْسَانُ ٱللهِ كَامِلًا، مُتَأَهِّبًا لِكُلِّ عَمَلٍ صَالِحٍ.",
    "JER.31.3": "تَرَاءَى لِي ٱلرَّبُّ مِنْ بَعِيدٍ: «وَمَحَبَّةً أَبَدِيَّةً أَحْبَبْتُكِ، مِنْ أَجْلِ ذَلِكَ أَدَمْتُ لَكِ ٱلرَّحْمَةَ.",
    "LUK.15.7": "أَقُولُ لَكُمْ: إِنَّهُ هَكَذَا يَكُونُ فَرَحٌ فِي ٱلسَّمَاءِ بِخَاطِئٍ وَاحِدٍ يَتُوبُ أَكْثَرَ مِنْ تِسْعَةٍ وَتِسْعِينَ بَارًّا لَا يَحْتَاجُونَ إِلَى تَوْبَةٍ.",
    "ISA.54.10": "فَإِنَّ ٱلْجِبَالَ تَزُولُ، وَٱلْآكَامَ تَتَزَعْزَعُ، أَمَّا إِحْسَانِي فَلَا يَزُولُ عَنْكِ، وَعَهْدُ سَلَامِي لَا يَتَزَعْزَعُ، قَالَ رَاحِمُكِ ٱلرَّبُّ.",
    "EPH.3.20-21": "وَٱلْقَادِرُ أَنْ يَفْعَلَ فَوْقَ كُلِّ شَيْءٍ، أَكْثَرَ جِدًّا مِمَّا نَطْلُبُ أَوْ نَفْتَكِرُ، بِحَسَبِ ٱلْقُوَّةِ ٱلَّتِي تَعْمَلُ فِينَا، لَهُ ٱلْمَجْدُ فِي ٱلْكَنِيسَةِ فِي ٱلْمَسِيحِ يَسُوعَ إِلَى جَمِيعِ أَجْيَالِ دَهْرِ ٱلدُّهُورِ. آمِينَ.",
    "ROM.5.3-5": "وَلَيْسَ ذَلِكَ فَقَطْ، بَلْ نَفْتَخِرُ أَيْضًا فِي ٱلضِّيقَاتِ، عَالِمِينَ أَنَّ ٱلضِّيقَ يُنْشِئُ صَبْرًا، وَٱلصَّبْرُ تَزْكِيَةً، وَٱلتَّزْكِيَةُ رَجَاءً، وَٱلرَّجَاءُ لَا يُخْزِي، لِأَنَّ مَحَبَّةَ ٱللهِ قَدِ ٱنْسَكَبَتْ فِي قُلُوبِنَا بِٱلرُّوحِ ٱلْقُدُسِ ٱلْمُعْطَى لَنَا.",
    "1JN.4.19": "نَحْنُ نُحِبُّهُ لِأَنَّهُ هُوَ أَحَبَّنَا أَوَّلًا.",
    "JHN.14.6": "قَالَ لَهُ يَسُوعُ: «أَنَا هُوَ ٱلطَّرِيقُ وَٱلْحَقُّ وَٱلْحَيَاةُ. لَيْسَ أَحَدٌ يَأْتِي إِلَى ٱلْآبِ إِلَّا بِي.",
    "1PE.5.6-7": "فَتَوَاضَعُوا تَحْتَ يَدِ ٱللهِ ٱلْقَوِيَّةِ لِكَيْ يَرْفَعَكُمْ فِي حِينِهِ، مُلْقِينَ كُلَّ هَمِّكُمْ عَلَيْهِ، لِأَنَّهُ هُوَ يَعْتَنِي بِكُمْ.",
    "EST.4.14": "لِأَنَّكِ إِنْ سَكَتِّ سُكُوتًا فِي هَذَا ٱلْوَقْتِ يَكُونُ ٱلْفَرَجُ وَٱلنَّجَاةُ لِلْيَهُودِ مِنْ مَكَانٍ آخَرَ، وَأَمَّا أَنْتِ وَبَيْتُ أَبِيكِ فَتَبِيدُونَ. وَمَنْ يَعْلَمُ إِنْ كُنْتِ لِوَقْتٍ مِثْلِ هَذَا وَصَلْتِ إِلَى ٱلْمُلْكِ؟».",
    "PSA.51.10": "قَلْبًا نَقِيًّا ٱخْلُقْ فِيَّ يَا ٱللهُ، وَرُوحًا مُسْتَقِيمًا جَدِّدْ فِي دَاخِلِي.",
    "LUK.6.37-38": "«وَلَا تَدِينُوا فَلَا تُدَانُوا. لَا تَقْضُوا عَلَى أَحَدٍ فَلَا يُقْضَى عَلَيْكُمْ. اِغْفِرُوا يُغْفَرْ لَكُمْ. أَعْطُوا تُعْطَوْا، كَيْلًا جَيِّدًا مُلَبَّدًا مَهْزُوزًا فَائِضًا يُعْطُونَ فِي أَحْضَانِكُمْ. لِأَنَّهُ بِنَفْسِ ٱلْكَيْلِ ٱلَّذِي بِهِ تَكِيلُونَ يُكَالُ لَكُمْ».",
    "PRO.2.6": "لِأَنَّ ٱلرَّبَّ يُعْطِي حِكْمَةً. مِنْ فَمِهِ ٱلْمَعْرِفَةُ وَٱلْفَهْمُ.",
    "MAT.7.24-25": "«فَكُلُّ مَنْ يَسْمَعُ أَقْوَالِي هَذِهِ وَيَعْمَلُ بِهَا، أُشَبِّهُهُ بِرَجُلٍ عَاقِلٍ، بَنَى بَيْتَهُ عَلَى ٱلصَّخْرِ. فَنَزَلَ ٱلْمَطَرُ، وَجَاءَتِ ٱلْأَنْهَارُ، وَهَبَّتِ ٱلرِّيَاحُ، وَوَقَعَتْ عَلَى ذَلِكَ ٱلْبَيْتِ فَلَمْ يَسْقُطْ، لِأَنَّهُ كَانَ مُؤَسَّسًا عَلَى ٱلصَّخْرِ.",
    "TIT.2.11-13": "لِأَنَّهُ قَدْ ظَهَرَتْ نِعْمَةُ ٱللهِ ٱلْمُخَلِّصَةُ لِجَمِيعِ ٱلنَّاسِ، مُعَلِّمَةً إِيَّانَا أَنْ نُنْكِرَ ٱلْفُجُورَ وَٱلشَّهَوَاتِ ٱلْعَالَمِيَّةَ، وَنَعِيشَ بِٱلتَّعَقُّلِ وَٱلْبِرِّ وَٱلتَّقْوَى فِي ٱلْعَالَمِ ٱلْحَاضِرِ، مُنْتَظِرِينَ ٱلرَّجَاءَ ٱلْمُبَارَكَ وَظُهُورَ مَجْدِ ٱللهِ ٱلْعَظِيمِ وَمُخَلِّصِنَا يَسُوعَ ٱلْمَسِيحِ،",
    "LUK.2.14": "«ٱلْمَجْدُ لِلهِ فِي ٱلْأَعَالِي، وَعَلَى ٱلْأَرْضِ ٱلسَّلَامُ، وَبِالنَّاسِ ٱلْمَسَرَّةُ».",
    "JOB.23.10": "«لِأَنَّهُ يَعْرِفُ طَرِيقِي. إِذَا جَرَّبَنِي أَخْرُجُ كَٱلذَّهَبِ.",
    "2CO.9.6-7": "هَذَا وَإِنَّ مَنْ يَزْرَعُ بِٱلشُّحِّ فَبِٱلشُّحِّ أَيْضًا يَحْصُدُ، وَمَنْ يَزْرَعُ بِٱلْبَرَكَاتِ فَبِٱلْبَرَكَاتِ أَيْضًا يَحْصُدُ. كُلُّ وَاحِدٍ كَمَا يَنْوِي بِقَلْبِهِ، لَيْسَ عَنْ حُزْنٍ أَوِ ٱضْطِرَارٍ. لِأَنَّ ٱلْمُعْطِيَ ٱلْمَسْرُورَ يُحِبُّهُ ٱللهُ.",
    "PRO.19.21": "فِي قَلْبِ ٱلْإِنْسَانِ أَفْكَارٌ كَثِيرَةٌ، لَكِنْ مَشُورَةُ ٱلرَّبِّ هِيَ تَثْبُتُ.",
    "ROM.5.1-2": "فَإِذْ قَدْ تَبَرَّرْنَا بِٱلْإِيمَانِ لَنَا سَلَامٌ مَعَ ٱللهِ بِرَبِّنَا يَسُوعَ ٱلْمَسِيحِ، ٱلَّذِي بِهِ أَيْضًا قَدْ صَارَ لَنَا ٱلدُّخُولُ بِٱلْإِيمَانِ، إِلَى هَذِهِ ٱلنِّعْمَةِ ٱلَّتِي نَحْنُ فِيهَا مُقِيمُونَ، وَنَفْتَخِرُ عَلَى رَجَاءِ مَجْدِ ٱللهِ.",
    "LUK.6.27-28": "«لَكِنِّي أَقُولُ لَكُمْ أَيُّهَا ٱلسَّامِعُونَ: أَحِبُّوا أَعْدَاءَكُمْ، أَحْسِنُوا إِلَى مُبْغِضِيكُمْ، بَارِكُوا لَاعِنِيكُمْ، وَصَلُّوا لِأَجْلِ ٱلَّذِينَ يُسِيئُونَ إِلَيْكُمْ.",
    "PRO.22.6": "رَبِّ ٱلْوَلَدَ فِي طَرِيقِهِ، فَمَتَى شَاخَ أَيْضًا لَا يَحِيدُ عَنْهُ.",
    "NUM.23.19": "لَيْسَ ٱللهُ إِنْسَانًا فَيَكْذِبَ، وَلَا ٱبْنَ إِنْسَانٍ فَيَنْدَمَ. هَلْ يَقُولُ وَلَا يَفْعَلُ؟ أَوْ يَتَكَلَّمُ وَلَا يَفِي؟",
    "PHP.4.8": "أَخِيرًا أَيُّهَا ٱلْإِخْوَةُ، كُلُّ مَا هُوَ حَقٌّ، كُلُّ مَا هُوَ جَلِيلٌ، كُلُّ مَا هُوَ عَادِلٌ، كُلُّ مَا هُوَ طَاهِرٌ، كُلُّ مَا هُوَ مُسِرٌّ، كُلُّ مَا صِيتُهُ حَسَنٌ، إِنْ كَانَتْ فَضِيلَةٌ وَإِنْ كَانَ مَدْحٌ، فَفِي هَذِهِ ٱفْتَكِرُوا.",
    "COL.2.6-7": "فَكَمَا قَبِلْتُمُ ٱلْمَسِيحَ يَسُوعَ ٱلرَّبَّ ٱسْلُكُوا فِيهِ، مُتَأَصِّلِينَ وَمَبْنِيِّينَ فِيهِ، وَمُوَطَّدِينَ فِي ٱلْإِيمَانِ، كَمَا عُلِّمْتُمْ، مُتَفَاضِلِينَ فِيهِ بِٱلشُّكْرِ.",
    "ROM.12.12": "فَرِحِينَ فِي ٱلرَّجَاءِ، صَابِرِينَ فِي ٱلضِّيْقِ، مُواظِبِينَ عَلَى ٱلصَّلَاةِ،",
    "PHP.2.3-4": "لَا شَيْئًا بِتَحَزُّبٍ أَوْ بِعُجْبٍ، بَلْ بِتَوَاضُعٍ، حَاسِبِينَ بَعْضُكُمُ ٱلْبَعْضَ أَفْضَلَ مِنْ أَنْفُسِهِمْ. لَا تَنْظُرُوا كُلُّ وَاحِدٍ إِلَى مَا هُوَ لِنَفْسِهِ، بَلْ كُلُّ وَاحِدٍ إِلَى مَا هُوَ لِآخَرِينَ أَيْضًا.",
    "1JN.5.14-15": "وَهَذِهِ هِيَ ٱلثِّقَةُ ٱلَّتِي لَنَا عِنْدَهُ: أَنَّهُ إِنْ طَلَبْنَا شَيْئًا حَسَبَ مَشِيئَتِهِ يَسْمَعُ لَنَا. وَإِنْ كُنَّا نَعْلَمُ أَنَّهُ مَهْمَا طَلَبْنَا يَسْمَعُ لَنَا، نَعْلَمُ أَنَّ لَنَا ٱلطَّلَبَاتِ ٱلَّتِي طَلَبْنَاهَا مِنْهُ.",
    "EPH.5.8": "لِأَنَّكُمْ كُنْتُمْ قَبْلًا ظُلْمَةً، وَأَمَّا ٱلْآنَ فَنُورٌ فِي ٱلرَّبِّ. ٱسْلُكُوا كَأَوْلَادِ نُورٍ.",
    "1JN.4.7-8": "أَيُّهَا ٱلْأَحِبَّاءُ، لِنُحِبَّ بَعْضُنَا بَعْضًا، لِأَنَّ ٱلْمَحَبَّةَ هِيَ مِنَ ٱللهِ، وَكُلُّ مَنْ يُحِبُّ فَقَدْ وُلِدَ مِنَ ٱللهِ وَيَعْرِفُ ٱللهَ. وَمَنْ لَا يُحِبُّ لَمْ يَعْرِفِ ٱللهَ، لِأَنَّ ٱللهَ مَحَبَّةٌ.",
    "PSA.103.1-2": "بَارِكِي يَا نَفْسِي ٱلرَّبَّ، وَكُلُّ مَا فِي بَاطِنِي لِيُبَارِكِ ٱسْمَهُ ٱلْقُدُّوسَ. بَارِكِي يَا نَفْسِي ٱلرَّبَّ، وَلَا تَنْسَيْ كُلَّ حَسَنَاتِهِ.",
    "HOS.6.6": "«إِنِّي أُرِيدُ رَحْمَةً لَا ذَبِيحَةً، وَمَعْرِفَةَ ٱللهِ أَكْثَرَ مِنْ مُحْرَقَاتٍ.",
    "ROM.8.1": "إِذًا لَا شَيْءَ مِنَ ٱلدَّيْنُونَةِ ٱلْآنَ عَلَى ٱلَّذِينَ هُمْ فِي ٱلْمَسِيحِ يَسُوعَ، ٱلسَّالِكِينَ لَيْسَ حَسَبَ ٱلْجَسَدِ بَلْ حَسَبَ ٱلرُّوحِ.",
    "ISA.60.1": "«قُومِي ٱسْتَنِيرِي لِأَنَّهُ قَدْ جَاءَ نُورُكِ، وَمَجْدُ ٱلرَّبِّ أَشْرَقَ عَلَيْكِ.",
    "1TH.5.23-24": "وَإِلَهُ ٱلسَّلَامِ نَفْسُهُ يُقَدِّسُكُمْ بِٱلتَّمَامِ. وَلْتُحْفَظْ رُوحُكُمْ وَنَفْسُكُمْ وَجَسَدُكُمْ كَامِلَةً بِلَا لَوْمٍ عِنْدَ مَجِيءِ رَبِّنَا يَسُوعَ ٱلْمَسِيحِ. أَمِينٌ هُوَ ٱلَّذِي يَدْعُوكُمُ ٱلَّذِي سَيَفْعَلُ أَيْضًا.",
    "1CO.6.19-20": "أَمْ لَسْتُمْ تَعْلَمُونَ أَنَّ جَسَدَكُمْ هُوَ هَيْكَلٌ لِلرُّوحِ ٱلْقُدُسِ ٱلَّذِي فِيكُمُ، ٱلَّذِي لَكُمْ مِنَ ٱللهِ، وَأَنَّكُمْ لَسْتُمْ لِأَنْفُسِكُمْ؟ لِأَنَّكُمْ قَدِ ٱشْتُرِيتُمْ بِثَمَنٍ. فَمَجِّدُوا ٱللهَ فِي أَجْسَادِكُمْ وَفِي أَرْوَاحِكُمُ ٱلَّتِي هِيَ لِلهِ.",
    "GEN.28.15": "وَهَا أَنَا مَعَكَ، وَأَحْفَظُكَ حَيْثُمَا تَذْهَبُ، وَأَرُدُّكَ إِلَى هَذِهِ ٱلْأَرْضِ، لِأَنِّي لَا أَتْرُكُكَ حَتَّى أَفْعَلَ مَا كَلَّمْتُكَ بِهِ».",
    "PSA.73.26": "قَدْ فَنِيَ لَحْمِي وَقَلْبِي. صَخْرَةُ قَلْبِي وَنَصِيبِي ٱللهُ إِلَى ٱلدَّهْرِ.",
    "SNG.8.7": "مِيَاهٌ كَثِيرَةٌ لَا تَسْتَطِيعُ أَنْ تُطْفِئَ ٱلْمَحَبَّةَ، وَٱلسُّيُولُ لَا تَغْمُرُهَا. إِنْ أَعْطَى ٱلْإِنْسَانُ كُلَّ ثَرْوَةِ بَيْتِهِ بَدَلَ ٱلْمَحَبَّةِ، تُحْتَقَرُ ٱحْتِقَارًا.",
    "JER.32.17": "«آهِ، أَيُّهَا ٱلسَّيِّدُ ٱلرَّبُّ، هَا إِنَّكَ قَدْ صَنَعْتَ ٱلسَّمَاوَاتِ وَٱلْأَرْضَ بِقُوَّتِكَ ٱلْعَظِيمَةِ، وَبِذِرَاعِكَ ٱلْمَمْدُودَةِ. لَا يَعْسُرُ عَلَيْكَ شَيْءٌ.",
    "1CH.16.34": "ٱحْمَدُوا ٱلرَّبَّ لِأَنَّهُ صَالِحٌ، لِأَنَّ إِلَى ٱلْأَبَدِ رَحْمَتَهُ.",
    "GAL.5.1": "فَٱثْبُتُوا إِذًا فِي ٱلْحُرِّيَّةِ ٱلَّتِي قَدْ حَرَّرَنَا ٱلْمَسِيحُ بِهَا، وَلَا تَرْتَبِكُوا أَيْضًا بِنِيرِ عُبُودِيَّةٍ.",
    "PSA.34.18": "قَرِيبٌ هُوَ ٱلرَّبُّ مِنَ ٱلْمُنْكَسِرِي ٱلْقُلُوبِ، وَيُخَلِّصُ ٱلْمُنْسَحِقِي ٱلرُّوحِ.",
    "DAN.3.17-18": "هُوَذَا يُوجَدُ إِلَهُنَا ٱلَّذِي نَعْبُدُهُ يَسْتَطِيعُ أَنْ يُنَجِّيَنَا مِنْ أَتُّونِ ٱلنَّارِ ٱلْمُتَّقِدَةِ، وَأَنْ يُنْقِذَنَا مِنْ يَدِكَ أَيُّهَا ٱلْمَلِكُ. وَإِلَّا فَلْيَكُنْ مَعْلُومًا لَكَ أَيُّهَا ٱلْمَلِكُ، أَنَّنَا لَا نَعْبُدُ آلِهَتَكَ وَلَا نَسْجُدُ لِتِمْثَالِ ٱلذَّهَبِ ٱلَّذِي نَصَبْتَهُ».",
    "1TI.1.17": "وَمَلِكُ ٱلدُّهُورِ ٱلَّذِي لَا يَفْنَى وَلَا يُرَى، ٱلْإِلَهُ ٱلْحَكِيمُ وَحْدَهُ، لَهُ ٱلْكَرَامَةُ وَٱلْمَجْدُ إِلَى دَهْرِ ٱلدُّهُورِ. آمِينَ.",
    "PSA.86.5": "لِأَنَّكَ أَنْتَ يَارَبُّ صَالِحٌ وَغَفُورٌ، وَكَثِيرُ ٱلرَّحْمَةِ لِكُلِّ ٱلدَّاعِينَ إِلَيْكَ.",
    "AMO.5.24": "وَلْيَجْرِ ٱلْحَقُّ كَٱلْمِيَاهِ، وَٱلْبِرُّ كَنَهْرٍ دَائِمٍ.",
    "JAS.1.17": "كُلُّ عَطِيَّةٍ صَالِحَةٍ وَكُلُّ مَوْهِبَةٍ تَامَّةٍ هِيَ مِنْ فَوْقُ، نَازِلَةٌ مِنْ عِنْدِ أَبِي ٱلْأَنْوَارِ، ٱلَّذِي لَيْسَ عِنْدَهُ تَغْيِيرٌ وَلَا ظِلُّ دَوَرَانٍ.",
    "JUD.1.24-25": "وَٱلْقَادِرُ أَنْ يَحْفَظَكُمْ غَيْرَ عَاثِرِينَ، وَيُوقِفَكُمْ أَمَامَ مَجْدِهِ بِلَا عَيْبٍ فِي ٱلِٱبْتِهَاجِ، ٱلْإِلَهُ ٱلْحَكِيمُ ٱلْوَحِيدُ مُخَلِّصُنَا، لَهُ ٱلْمَجْدُ وَٱلْعَظَمَةُ وَٱلْقُدْرَةُ وَٱلسُّلْطَانُ، ٱلْآنَ وَإِلَى كُلِّ ٱلدُّهُورِ. آمِينَ.",
    "2PE.3.9": "لَا يَتَبَاطَأُ ٱلرَّبُّ عَنْ وَعْدِهِ كَمَا يَحْسِبُ قَوْمٌ ٱلتَّبَاطُؤَ، لَكِنَّهُ يَتَأَنَّى عَلَيْنَا، وَهُوَ لَا يَشَاءُ أَنْ يَهْلِكَ أُنَاسٌ، بَلْ أَنْ يُقْبِلَ ٱلْجَمِيعُ إِلَى ٱلتَّوْبَةِ.",
    "ISA.9.6": "لِأَنَّهُ يُولَدُ لَنَا وَلَدٌ وَنُعْطَى ٱبْنًا، وَتَكُونُ ٱلرِّيَاسَةُ عَلَى كَتِفِهِ، وَيُدْعَى ٱسْمُهُ عَجِيبًا، مُشِيرًا، إِلَهًا قَدِيرًا، أَبًا أَبَدِيًّا، رَئِيسَ ٱلسَّلَامِ.",
    "LUK.2.10-11": "فَقَالَ لَهُمُ ٱلْمَلَاكُ: «لَا تَخَافُوا! فَهَا أَنَا أُبَشِّرُكُمْ بِفَرَحٍ عَظِيمٍ يَكُونُ لِجَمِيعِ ٱلشَّعْبِ: أَنَّهُ وُلِدَ لَكُمُ ٱلْيَوْمَ فِي مَدِينَةِ دَاوُدَ مُخَلِّصٌ هُوَ ٱلْمَسِيحُ ٱلرَّبُّ.",
    "1TI.6.6-8": "وَأَمَّا ٱلتَّقْوَى مَعَ ٱلْقَنَاعَةِ فَهِيَ تِجَارَةٌ عَظِيمَةٌ. لِأَنَّنَا لَمْ نَدْخُلِ ٱلْعَالَمَ بِشَيْءٍ، وَوَاضِحٌ أَنَّنَا لَا نَقْدِرُ أَنْ نَخْرُجَ مِنْهُ بِشَيْءٍ. فَإِنْ كَانَ لَنَا قُوتٌ وَكِسْوَةٌ، فَلْنَكْتَفِ بِهِمَا.",
    "NAM.1.7": "صَالِحٌ هُوَ ٱلرَّبُّ. حِصْنٌ فِي يَوْمِ ٱلضَّيقِ، وَهُوَ يَعْرِفُ ٱلْمُتَوَكِّلِينَ عَلَيْهِ.",
    "PSA.27.1": "اَلرَّبُّ نُورِي وَخَلَاصِي، مِمَّنْ أَخَافُ؟ ٱلرَّبُّ حِصْنُ حَيَاتِي، مِمَّنْ أَرْتَعِبُ؟",
    "COL.1.15-17": "ٱلَّذِي هُوَ صُورَةُ ٱللهِ غَيْرِ ٱلْمَنْظُورِ، بِكْرُ كُلِّ خَلِيقَةٍ. فَإِنَّهُ فِيهِ خُلِقَ ٱلْكُلُّ: مَا في ٱلسَّمَاوَاتِ وَمَا عَلَى ٱلْأَرْضِ، مَا يُرَى وَمَا لَا يُرَى، سَوَاءٌ كَانَ عُرُوشًا أَمْ سِيَادَاتٍ أَمْ رِيَاسَاتٍ أَمْ سَلَاطِينَ. ٱلْكُلُّ بِهِ وَلَهُ قَدْ خُلِقَ. ٱلَّذِي هُوَ قَبْلَ كُلِّ شَيْءٍ، وَفِيهِ يَقُومُ ٱلْكُلُّ،",
    "ZEP.3.17": "ٱلرَّبُّ إِلَهُكِ فِي وَسَطِكِ جَبَّارٌ. يُخَلِّصُ. يَبْتَهِجُ بِكِ فَرَحًا. يَسْكُتُ فِي مَحَبَّتِهِ. يَبْتَهِجُ بِكِ بِتَرَنُّمٍ».",
    "PSA.90.12": "إِحْصَاءَ أَيَّامِنَا هَكَذَا عَلِّمْنَا فَنُؤْتَى قَلْبَ حِكْمَةٍ.",
    "ROM.8.24-25": "لِأَنَّنَا بِٱلرَّجَاءِ خَلَصْنَا. وَلَكِنَّ ٱلرَّجَاءَ ٱلْمَنْظُورَ لَيْسَ رَجَاءً، لِأَنَّ مَا يَنْظُرُهُ أَحَدٌ كَيْفَ يَرْجُوهُ أَيْضًا؟ وَلَكِنْ إِنْ كُنَّا نَرْجُو مَا لَسْنَا نَنْظُرُهُ فَإِنَّنَا نَتَوَقَّعُهُ بِٱلصَّبْرِ.",
    "PSA.39.7": "«وَٱلْآنَ، مَاذَا ٱنْتَظَرْتُ يَارَبُّ؟ رَجَائِي فِيكَ هُوَ.",
    "LAM.3.21-23": "أُرَدِّدُ هَذَا فِي قَلْبِي، مِنْ أَجْلِ ذَلِكَ أَرْجُو: إِنَّهُ مِنْ إِحْسَانَاتِ ٱلرَّبِّ أَنَّنَا لَمْ نَفْنَ، لِأَنَّ مَرَاحِمَهُ لَا تَزُولُ. هِيَ جَدِيدَةٌ فِي كُلِّ صَبَاحٍ. كَثِيرَةٌ أَمَانَتُكَ.",
    "PSA.71.5": "لِأَنَّكَ أَنْتَ رَجَائِي يَا سَيِّدِي ٱلرَّبَّ، مُتَّكَلِي مُنْذُ صِبَايَ.",
    "HEB.6.19": "ٱلَّذِي هُوَ لَنَا كَمِرْسَاةٍ لِلنَّفْسِ مُؤْتَمَنَةٍ وَثَابِتَةٍ، تَدْخُلُ إِلَى مَا دَاخِلَ ٱلْحِجَابِ،",
    "PSA.130.5": "ٱنْتَظَرْتُكَ يَارَبُّ. ٱنْتَظَرَتْ نَفْسِي، وَبِكَلَامِهِ رَجَوْتُ.",
    "PRO.23.18": "لِأَنَّهُ لَا بُدَّ مِنْ ثَوَابٍ، وَرَجَاؤُكَ لَا يَخِيبُ.",
    "PSA.42.11": "لِمَاذَا أَنْتِ مُنْحَنِيَةٌ يَا نَفْسِي؟ وَلِمَاذَا تَئِنِّينَ فِيَّ؟ تَرَجَّيِ ٱللهَ، لِأَنِّي بَعْدُ أَحْمَدُهُ، خَلَاصَ وَجْهِي وَإِلَهِي.",
    "TIT.2.13": "مُنْتَظِرِينَ ٱلرَّجَاءَ ٱلْمُبَارَكَ وَظُهُورَ مَجْدِ ٱللهِ ٱلْعَظِيمِ وَمُخَلِّصِنَا يَسُوعَ ٱلْمَسِيحِ،",
    "HEB.10.23": "لِنَتَمَسَّكْ بِإِقْرَارِ ٱلرَّجَاءِ رَاسِخًا، لِأَنَّ ٱلَّذِي وَعَدَ هُوَ أَمِينٌ.",
    "PSA.33.22": "لِتَكُنْ يَارَبُّ رَحْمَتُكَ عَلَيْنَا حَسْبَمَا ٱنْتَظَرْنَاكَ.",
    "1PE.1.13": "لِذَلِكَ مَنْطِقُوا أَحْقَاءَ ذِهْنِكُمْ صَاحِينَ، فَأَلْقُوا رَجَاءَكُمْ بِٱلتَّمَامِ عَلَى ٱلنِّعْمَةِ ٱلَّتِي يُؤْتَى بِهَا إِلَيْكُمْ عِنْدَ ٱسْتِعْلَانِ يَسُوعَ ٱلْمَسِيحِ.",
    "PSA.31.24": "لِتَتَشَدَّدْ وَلْتَتَشَجَّعْ قُلُوبُكُمْ، يَا جَمِيعَ ٱلْمُنْتَظِرِينَ ٱلرَّبَّ.",
    "COL.1.27": "ٱلَّذِينَ أَرَادَ ٱللهُ أَنْ يُعَرِّفَهُمْ مَا هُوَ غِنَى مَجْدِ هَذَا ٱلسِّرِّ فِي ٱلْأُمَمِ، ٱلَّذِي هُوَ ٱلْمَسِيحُ فِيكُمْ رَجَاءُ ٱلْمَجْدِ.",
    "PSA.62.5": "إِنَّمَا لِلهِ ٱنْتَظِرِي يَا نَفْسِي، لِأَنَّ مِنْ قِبَلِهِ رَجَائِي.",
    "PSA.147.11": "يَرْضَى ٱلرَّبُّ بِأَتْقِيَائِهِ، بِٱلرَّاجِينَ رَحْمَتَهُ.",
    "1TH.4.13-14": "ثُمَّ لَا أُرِيدُ أَنْ تَجْهَلُوا أَيُّهَا ٱلْإِخْوَةُ مِنْ جِهَةِ ٱلرَّاقِدِينَ، لِكَيْ لَا تَحْزَنُوا كَٱلْبَاقِينَ ٱلَّذِينَ لَا رَجَاءَ لَهُمْ. لِأَنَّهُ إِنْ كُنَّا نُؤْمِنُ أَنَّ يَسُوعَ مَاتَ وَقَامَ، فَكَذَلِكَ ٱلرَّاقِدُونَ بِيَسُوعَ، سَيُحْضِرُهُمُ ٱللهُ أَيْضًا مَعَهُ.",
    "PRO.13.12": "ٱلرَّجَاءُ ٱلْمُمَاطَلُ يُمْرِضُ ٱلْقَلْبَ، وَٱلشَّهْوَةُ ٱلْمُتَمَّمَةُ شَجَرَةُ حَيَاةٍ.",
    "PSA.119.114": "سِتْرِي وَمِجَنِّي أَنْتَ. كَلَامَكَ ٱنْتَظَرْتُ.",
    "2CO.4.17-18": "لِأَنَّ خِفَّةَ ضِيقَتِنَا ٱلْوَقْتِيَّةَ تُنْشِئُ لَنَا أَكْثَرَ فَأَكْثَرَ ثِقَلَ مَجْدٍ أَبَدِيًّا. وَنَحْنُ غَيْرُ نَاظِرِينَ إِلَى ٱلْأَشْيَاءِ ٱلَّتِي تُرَى، بَلْ إِلَى ٱلَّتِي لَا تُرَى. لِأَنَّ ٱلَّتِي تُرَى وَقْتِيَّةٌ، وَأَمَّا ٱلَّتِي لَا تُرَى فَأَبَدِيَّةٌ.",
    "ISA.26.3-4": "ذُو ٱلرَّأْيِ ٱلْمُمَكَّنِ تَحْفَظُهُ سَالِمًا سَالِمًا، لِأَنَّهُ عَلَيْكَ مُتَوَكِّلٌ. تَوَكَّلُوا عَلَى ٱلرَّبِّ إِلَى ٱلْأَبَدِ، لِأَنَّ فِي يَاهَ ٱلرَّبِّ صَخْرَ ٱلدُّهُورِ.",
    "PSA.37.5": "سَلِّمْ لِلرَّبِّ طَرِيقَكَ وَٱتَّكِلْ عَلَيْهِ وَهُوَ يُجْرِي،",
    "PSA.9.10": "وَيَتَّكِلُ عَلَيْكَ ٱلْعَارِفُونَ ٱسْمَكَ، لِأَنَّكَ لَمْ تَتْرُكْ طَالِبِيكَ يَارَبُّ.",
    "PSA.20.7": "هَؤُلَاءِ بِٱلْمَرْكَبَاتِ وَهَؤُلَاءِ بِٱلْخَيْلِ، أَمَّا نَحْنُ فَٱسْمَ ٱلرَّبِّ إِلَهِنَا نَذْكُرُ.",
    "PSA.62.8": "تَوَكَّلُوا عَلَيْهِ فِي كُلِّ حِينٍ يَا قَوْمُ. ٱسْكُبُوا قُدَّامَهُ قُلُوبَكُمْ. ٱللهُ مَلْجَأٌ لَنَا. سِلَاهْ.",
    "PSA.112.7": "لَا يَخْشَى مِنْ خَبَرِ سُوءٍ. قَلْبُهُ ثَابِتٌ مُتَّكِلًا عَلَى ٱلرَّبِّ.",
    "PSA.118.8": "ٱلِٱحْتِمَاءُ بِٱلرَّبِّ خَيْرٌ مِنَ ٱلتَّوَكُّلِ عَلَى إِنْسَانٍ.",
    "ISA.12.2": "هُوَذَا ٱللهُ خَلَاصِي فَأَطْمَئِنُّ وَلَا أَرْتَعِبُ، لِأَنَّ يَاهَ يَهْوَهَ قُوَّتِي وَتَرْنِيمَتِي وَقَدْ صَارَ لِي خَلَاصًا».",
    "PSA.125.1": "اَلْمُتَوَكِّلُونَ عَلَى ٱلرَّبِّ مِثْلُ جَبَلِ صِهْيَوْنَ، ٱلَّذِي لَا يَتَزَعْزَعُ، بَلْ يَسْكُنُ إِلَى ٱلدَّهْرِ.",
    "PSA.143.8": "أَسْمِعْنِي رَحْمَتَكَ فِي ٱلْغَدَاةِ، لِأَنِّي عَلَيْكَ تَوَكَّلْتُ. عَرِّفْنِي ٱلطَّرِيقَ ٱلَّتِي أَسْلُكُ فِيهَا، لِأَنِّي إِلَيْكَ رَفَعْتُ نَفْسِي.",
    "PRO.29.25": "خَشْيَةُ ٱلْإِنْسَانِ تَضَعُ شَرَكًا، وَٱلْمُتَّكِلُ عَلَى ٱلرَّبِّ يُرْفَعُ.",
    "PSA.91.2": "أَقُولُ لِلرَّبِّ: «مَلْجَإِي وَحِصْنِي. إِلَهِي فَأَتَّكِلُ عَلَيْهِ».",
    "2CO.5.7": "لِأَنَّنَا بِٱلْإِيمَانِ نَسْلُكُ لَا بِٱلْعِيَانِ.",
    "PSA.40.4": "طُوبَى لِلرَّجُلِ ٱلَّذِي جَعَلَ ٱلرَّبَّ مُتَّكَلَهُ، وَلَمْ يَلْتَفِتْ إِلَى ٱلْغَطَارِيسِ وَٱلْمُنْحَرِفِينَ إِلَى ٱلْكَذِبِ.",
    "PSA.13.5-6": "أَمَّا أَنَا فَعَلَى رَحْمَتِكَ تَوَكَّلْتُ. يَبْتَهِجُ قَلْبِي بِخَلَاصِكَ. أُغَنِّي لِلرَّبِّ لِأَنَّهُ أَحْسَنَ إِلَيَّ.",
    "PSA.84.12": "يَارَبَّ ٱلْجُنُودِ، طُوبَى لِلْإِنْسَانِ ٱلْمُتَّكِلِ عَلَيْكَ.",
    "PRO.16.20": "ٱلْفَطِنُ مِنْ جِهَةِ أَمْرٍ يَجِدُ خَيْرًا، وَمَنْ يَتَّكِلُ عَلَى ٱلرَّبِّ فَطُوبَى لَهُ.",
    "PSA.32.10": "كَثِيرَةٌ هِيَ نَكَبَاتُ ٱلشِّرِّيرِ، أَمَّا ٱلْمُتَوَكِّلُ عَلَى ٱلرَّبِّ فَٱلرَّحْمَةُ تُحِيطُ بِهِ.",
    "ISA.50.10": "مَنْ مِنْكُمْ خَائِفُ ٱلرَّبِّ، سَامِعٌ لِصَوْتِ عَبْدِهِ؟ مَنِ ٱلَّذِي يَسْلُكُ فِي ٱلظُّلُمَاتِ وَلَا نُورَ لَهُ؟ فَلْيَتَّكِلْ عَلَى ٱسْمِ ٱلرَّبِّ وَيَسْتَنِدْ إِلَى إِلَهِهِ.",
    "PSA.37.3": "ٱتَّكِلْ عَلَى ٱلرَّبِّ وَٱفْعَلِ ٱلْخَيْرَ. ٱسْكُنِ ٱلْأَرْضَ وَٱرْعَ ٱلْأَمَانَةَ.",
    "PSA.115.11": "يَا مُتَّقِي ٱلرَّبِّ، ٱتَّكِلُوا عَلَى ٱلرَّبِّ. هُوَ مُعِينُهُمْ وَمِجَنُّهُمْ.",
    "ROM.4.20-21": "وَلَا بِعَدَمِ إِيمَانٍ ٱرْتَابَ فِي وَعْدِ ٱللهِ، بَلْ تَقَوَّى بِٱلْإِيمَانِ مُعْطِيًا مَجْدًا لِلهِ. وَتَيَقَّنَ أَنَّ مَا وَعَدَ بِهِ هُوَ قَادِرٌ أَنْ يَفْعَلَهُ أَيْضًا.",
    "1JN.4.18-19": "لَا خَوْفَ فِي ٱلْمَحَبَّةِ، بَلِ ٱلْمَحَبَّةُ ٱلْكَامِلَةُ تَطْرَحُ ٱلْخَوْفَ إِلَى خَارِجٍ لِأَنَّ ٱلْخَوْفَ لَهُ عَذَابٌ. وَأَمَّا مَنْ خَافَ فَلَمْ يَتَكَمَّلْ فِي ٱلْمَحَبَّةِ. نَحْنُ نُحِبُّهُ لِأَنَّهُ هُوَ أَحَبَّنَا أَوَّلًا.",
    "1JN.3.18": "يَا أَوْلَادِي، لَا نُحِبَّ بِٱلْكَلَامِ وَلَا بِٱللِّسَانِ، بَلْ بِٱلْعَمَلِ وَٱلْحَقِّ!",
    "COL.3.14": "وَعَلَى جَمِيعِ هَذِهِ ٱلْبَسُوا ٱلْمَحَبَّةَ ٱلَّتِي هِيَ رِبَاطُ ٱلْكَمَالِ.",
    "ROM.13.10": "اَلْمَحَبَّةُ لَا تَصْنَعُ شَرًّا لِلْقَرِيبِ، فَٱلْمَحَبَّةُ هِيَ تَكْمِيلُ ٱلنَّامُوسِ.",
    "DEU.6.5": "فَتُحِبُّ ٱلرَّبَّ إِلَهَكَ مِنْ كُلِّ قَلْبِكَ وَمِنْ كُلِّ نَفْسِكَ وَمِنْ كُلِّ قُوَّتِكَ.",
    "1CO.16.14": "لِتَصِرْ كُلُّ أُمُورِكُمْ فِي مَحَبَّةٍ.",
    "EPH.5.2": "وَٱسْلُكُوا فِي ٱلْمَحَبَّةِ كَمَا أَحَبَّنَا ٱلْمَسِيحُ أَيْضًا وَأَسْلَمَ نَفْسَهُ لِأَجْلِنَا، قُرْبَانًا وَذَبِيحَةً لِلهِ رَائِحَةً طَيِّبَةً.",
    "GAL.5.13": "فَإِنَّكُمْ إِنَّمَا دُعِيتُمْ لِلْحُرِّيَّةِ أَيُّهَا ٱلْإِخْوَةُ. غَيْرَ أَنَّهُ لَا تُصَيِّرُوا ٱلْحُرِّيَّةَ فُرْصَةً لِلْجَسَدِ، بَلْ بِٱلْمَحَبَّةِ ٱخْدِمُوا بَعْضُكُمْ بَعْضًا.",
    "PSA.136.26": "ٱحْمَدُوا إِلَهَ ٱلسَّمَاوَاتِ، لِأَنَّ إِلَى ٱلْأَبَدِ رَحْمَتَهُ.",
    "LUK.6.35": "بَلْ أَحِبُّوا أَعْدَاءَكُمْ، وَأَحْسِنُوا وَأَقْرِضُوا وَأَنْتُمْ لَا تَرْجُونَ شَيْئًا، فَيَكُونَ أَجْرُكُمْ عَظِيمًا وَتَكُونُوا بَنِي ٱلْعَلِيِّ، فَإِنَّهُ مُنْعِمٌ عَلَى غَيْرِ ٱلشَّاكِرِينَ وَٱلْأَشْرَارِ.",
    "ROM.12.9-10": "اَلْمَحَبَّةُ فَلْتَكُنْ بِلَا رِيَاءٍ. كُونُوا كَارِهِينَ ٱلشَّرَّ، مُلْتَصِقِينَ بِٱلْخَيْرِ. وَادِّينَ بَعْضُكُمْ بَعْضًا بِٱلْمَحَبَّةِ ٱلْأَخَوِيَّةِ، مُقَدِّمِينَ بَعْضُكُمْ بَعْضًا فِي ٱلْكَرَامَةِ.",
    "1JN.4.10-11": "فِي هَذَا هِيَ ٱلْمَحَبَّةُ: لَيْسَ أَنَّنَا نَحْنُ أَحْبَبْنَا ٱللهَ، بَلْ أَنَّهُ هُوَ أَحَبَّنَا، وَأَرْسَلَ ٱبْنَهُ كَفَّارَةً لِخَطَايَانَا. أَيُّهَا ٱلْأَحِبَّاءُ، إِنْ كَانَ ٱللهُ قَدْ أَحَبَّنَا هَكَذَا، يَنْبَغِي لَنَا أَيْضًا أَنْ يُحِبَّ بَعْضُنَا بَعْضًا.",
    "EPH.4.2": "بِكُلِّ تَوَاضُعٍ وَوَدَاعَةٍ وَبِطُولِ أَنَاةٍ، مُحْتَمِلِينَ بَعْضُكُمْ بَعْضًا فِي ٱلْمَحَبَّةِ.",
    "PSA.86.15": "أَمَّا أَنْتَ يَارَبُّ فَإِلَهٌ رَحِيمٌ وَرَؤُوفٌ، طَوِيلُ ٱلرُّوحِ وَكَثِيرُ ٱلرَّحْمَةِ وَٱلْحَقِّ.",
    "EXO.20.12": "أَكْرِمْ أَبَاكَ وَأُمَّكَ لِكَيْ تَطُولَ أَيَّامُكَ عَلَى ٱلْأَرْضِ ٱلَّتِي يُعْطِيكَ ٱلرَّبُّ إِلَهُكَ.",
    "PSA.127.3-5": "هُوَذَا ٱلْبَنُونَ مِيرَاثٌ مِنْ عِنْدِ ٱلرَّبِّ، ثَمَرَةُ ٱلْبَطْنِ أُجْرَةٌ. كَسِهَامٍ بِيَدِ جَبَّارٍ، هَكَذَا أَبْنَاءُ ٱلشَّبِيبَةِ. طُوبَى لِلَّذِي مَلَأَ جَعْبَتَهُ مِنْهُمْ. لَا يَخْزَوْنَ بَلْ يُكَلِّمُونَ ٱلْأَعْدَاءَ فِي ٱلْبَابِ.",
    "EPH.6.1-3": "أَيُّهَا ٱلْأَوْلَادُ، أَطِيعُوا وَالِدِيكُمْ فِي ٱلرَّبِّ لِأَنَّ هَذَا حَقٌّ. «أَكْرِمْ أَبَاكَ وَأُمَّكَ»، ٱلَّتِي هِيَ أَوَّلُ وَصِيَّةٍ بِوَعْدٍ، «لِكَيْ يَكُونَ لَكُمْ خَيْرٌ، وَتَكُونُوا طِوَالَ ٱلْأَعْمَارِ عَلَى ٱلْأَرْضِ».",
    "COL.3.20-21": "أَيُّهَا ٱلْأَوْلَادُ، أَطِيعُوا وَالِدِيكُمْ فِي كُلِّ شَيْءٍ لِأَنَّ هَذَا مَرْضِيٌّ فِي ٱلرَّبِّ. أَيُّهَا ٱلْآبَاءُ، لَا تُغِيظُوا أَوْلَادَكُمْ لِئَلَّا يَفْشَلُوا.",
    "PRO.17.6": "تَاجُ ٱلشُّيُوخِ بَنُو ٱلْبَنِينَ، وَفَخْرُ ٱلْبَنِينَ آبَاؤُهُمْ.",
    "PSA.103.17": "أَمَّا رَحْمَةُ ٱلرَّبِّ فَإِلَى ٱلدَّهْرِ وَٱلْأَبَدِ عَلَى خَائِفِيهِ، وَعَدْلُهُ عَلَى بَنِي ٱلْبَنِينَ،",
    "DEU.6.6-7": "وَلْتَكُنْ هَذِهِ ٱلْكَلِمَاتُ ٱلَّتِي أَنَا أُوصِيكَ بِهَا ٱلْيَوْمَ عَلَى قَلْبِكَ، وَقُصَّهَا عَلَى أَوْلَادِكَ، وَتَكَلَّمْ بِهَا حِينَ تَجْلِسُ فِي بَيْتِكَ، وَحِينَ تَمْشِي فِي ٱلطَّرِيقِ، وَحِينَ تَنَامُ وَحِينَ تَقُومُ،",
    "GEN.2.24": "لِذَلِكَ يَتْرُكُ ٱلرَّجُلُ أَبَاهُ وَأُمَّهُ وَيَلْتَصِقُ بِٱمْرَأَتِهِ وَيَكُونَانِ جَسَدًا وَاحِدًا.",
    "PRO.31.28-29": "يَقُومُ أَوْلَادُهَا وَيُطَوِّبُونَهَا. زَوْجُهَا أَيْضًا فَيَمْدَحُهَا: «بَنَاتٌ كَثِيرَاتٌ عَمِلْنَ فَضْلًا، أَمَّا أَنْتِ فَفُقْتِ عَلَيْهِنَّ جَمِيعًا».",
    "EPH.5.25": "أَيُّهَا ٱلرِّجَالُ، أَحِبُّوا نِسَاءَكُمْ كَمَا أَحَبَّ ٱلْمَسِيحُ أَيْضًا ٱلْكَنِيسَةَ وَأَسْلَمَ نَفْسَهُ لِأَجْلِهَا،",
    "1TI.5.8": "وَإِنْ كَانَ أَحَدٌ لَا يَعْتَنِي بِخَاصَّتِهِ، وَلَا سِيَّمَا أَهْلُ بَيْتِهِ، فَقَدْ أَنْكَرَ ٱلْإِيمَانَ، وَهُوَ شَرٌّ مِنْ غَيْرِ ٱلْمُؤْمِنِ.",
    "PSA.128.3": "ٱمْرَأَتُكَ مِثْلُ كَرْمَةٍ مُثْمِرَةٍ فِي جَوَانِبِ بَيْتِكَ. بَنُوكَ مِثْلُ غُرُوسِ ٱلزَّيْتُونِ حَوْلَ مَائِدَتِكَ.",
    "PRO.1.8-9": "اِسْمَعْ يَا ٱبْنِي تَأْدِيبَ أَبِيكَ، وَلَا تَرْفُضْ شَرِيعَةَ أُمِّكَ، لِأَنَّهُمَا إِكْلِيلُ نِعْمَةٍ لِرَأْسِكَ، وَقَلَائِدُ لِعُنُقِكَ.",
    "PSA.133.1": "هُوَذَا مَا أَحْسَنَ وَمَا أَجْمَلَ أَنْ يَسْكُنَ ٱلْإِخْوَةُ مَعًا!",
    "PRO.20.7": "اَلصِّدِّيقُ يَسْلُكُ بِكَمَالِهِ. طُوبَى لِبَنِيهِ بَعْدَهُ.",
    "ISA.54.13": "وَكُلَّ بَنِيكِ تَلَامِيذَ ٱلرَّبِّ، وَسَلَامَ بَنِيكِ كَثِيرًا.",
    "MAL.4.6": "فَيَرُدُّ قَلْبَ ٱلْآبَاءِ عَلَى ٱلْأَبْنَاءِ، وَقَلْبَ ٱلْأَبْنَاءِ عَلَى آبَائِهِمْ. لِئَلَّا آتِيَ وَأَضْرِبَ ٱلْأَرْضَ بِلَعْنٍ».",
    "PRO.15.20": "اَلِٱبْنُ ٱلْحَكِيمُ يَسُرُّ أَبَاهُ، وَٱلرَّجُلُ ٱلْجَاهِلُ يَحْتَقِرُ أُمَّهُ.",
    "EPH.5.33": "وَأَمَّا أَنْتُمُ ٱلْأَفْرَادُ، فَلْيُحِبَّ كُلُّ وَاحِدٍ ٱمْرَأَتَهُ هَكَذَا كَنَفْسِهِ، وَأَمَّا ٱلْمَرْأَةُ فَلْتَهَبْ رَجُلَهَا.",
    "PRO.23.24-25": "أَبُو ٱلصِّدِّيقِ يَبْتَهِجُ ٱبْتِهَاجًا، وَمَنْ وَلَدَ حَكِيمًا يُسَرُّ بِهِ. يَفْرَحُ أَبُوكَ وَأُمُّكَ، وَتَبْتَهِجُ ٱلَّتِي وَلَدَتْكَ.",
    "GEN.18.19": "لِأَنِّي عَرَفْتُهُ لِكَيْ يُوصِيَ بَنِيهِ وَبَيْتَهُ مِنْ بَعْدِهِ أَنْ يَحْفَظُوا طَرِيقَ ٱلرَّبِّ، لِيَعْمَلُوا بِرًّا وَعَدْلًا، لِكَيْ يَأْتِيَ ٱلرَّبُّ لِإِبْرَاهِيمَ بِمَا تَكَلَّمَ بِهِ».",
    "PSA.68.6": "ٱللهُ مُسْكِنُ ٱلْمُتَوَحِّدِينَ فِي بَيْتٍ. مُخْرِجُ ٱلْأَسْرَى إِلَى فَلَاحٍ. إِنَّمَا ٱلْمُتَمَرِّدُونَ يَسْكُنُونَ ٱلرَّمْضَاءَ.",
    "PRO.18.22": "مَنْ يَجِدُ زَوْجَةً يَجِدُ خَيْرًا وَيَنَالُ رِضًى مِنَ ٱلرَّبِّ.",
    "COL.3.18-19": "أَيَّتُهَا ٱلنِّسَاءُ، ٱخْضَعْنَ لِرِجَالِكُنَّ كَمَا يَلِيقُ فِي ٱلرَّبِّ. أَيُّهَا ٱلرِّجَالُ، أَحِبُّوا نِسَاءَكُمْ، وَلَا تَكُونُوا قُسَاةً عَلَيْهِنَّ.",
    "PRO.6.20": "يَا ٱبْنِي، ٱحْفَظْ وَصَايَا أَبِيكَ وَلَا تَتْرُكْ شَرِيعَةَ أُمِّكَ.",
    "PRO.31.10": "اِمْرَأَةٌ فَاضِلَةٌ مَنْ يَجِدُهَا؟ لِأَنَّ ثَمَنَهَا يَفُوقُ ٱللَّآلِئَ.",
    "ROM.5.1": "فَإِذْ قَدْ تَبَرَّرْنَا بِٱلْإِيمَانِ لَنَا سَلَامٌ مَعَ ٱللهِ بِرَبِّنَا يَسُوعَ ٱلْمَسِيحِ،",
    "COL.3.15": "وَلْيَمْلِكْ فِي قُلُوبِكُمْ سَلَامُ ٱللهِ ٱلَّذِي إِلَيْهِ دُعِيتُمْ فِي جَسَدٍ وَاحِدٍ، وَكُونُوا شَاكِرِينَ.",
    "PSA.29.11": "ٱلرَّبُّ يُعْطِي عِزًّا لِشَعْبِهِ. ٱلرَّبُّ يُبَارِكُ شَعْبَهُ بِٱلسَّلَامِ.",
    "MAT.5.9": "طُوبَى لِصَانِعِي ٱلسَّلَامِ، لِأَنَّهُمْ أَبْنَاءَ ٱللهِ يُدْعَوْنَ.",
    "ROM.12.18": "إِنْ كَانَ مُمْكِنًا فَحَسَبَ طَاقَتِكُمْ سَالِمُوا جَمِيعَ ٱلنَّاسِ.",
    "PSA.34.14": "حِدْ عَنِ ٱلشَّرِّ، وَٱصْنَعِ ٱلْخَيْرَ. ٱطْلُبِ ٱلسَّلَامَةَ، وَٱسْعَ وَرَاءَهَا.",
    "PRO.16.7": "إِذَا أَرْضَتِ ٱلرَّبَّ طُرُقُ إِنْسَانٍ، جَعَلَ أَعْدَاءَهُ أَيْضًا يُسَالِمُونَهُ.",
    "ISA.32.17": "وَيَكُونُ صُنْعُ ٱلْعَدْلِ سَلَامًا، وَعَمَلُ ٱلْعَدْلِ سُكُونًا وَطُمَأْنِينَةً إِلَى ٱلْأَبَدِ.",
    "PSA.119.165": "سَلَامَةٌ جَزِيلَةٌ لِمُحِبِّي شَرِيعَتِكَ، وَلَيْسَ لَهُمْ مَعْثَرَةٌ.",
    "ROM.14.17": "لِأَنْ لَيْسَ مَلَكُوتُ ٱللهِ أَكْلًا وَشُرْبًا، بَلْ هُوَ بِرٌّ وَسَلَامٌ وَفَرَحٌ فِي ٱلرُّوحِ ٱلْقُدُسِ.",
    "EPH.2.14": "لِأَنَّهُ هُوَ سَلَامُنَا، ٱلَّذِي جَعَلَ ٱلِٱثْنَيْنِ وَاحِدًا، وَنَقَضَ حَائِطَ ٱلسِّيَاجِ ٱلْمُتَوَسِّطَ،",
    "PSA.85.8": "إِنِّي أَسْمَعُ مَا يَتَكَلَّمُ بِهِ ٱللهُ ٱلرَّبُّ، لِأَنَّهُ يَتَكَلَّمُ بِٱلسَّلَامِ لِشَعْبِهِ وَلِأَتْقِيَائِهِ، فَلَا يَرْجِعُنَّ إِلَى ٱلْحَمَاقَةِ.",
    "JAS.3.18": "وَثَمَرُ ٱلْبِرِّ يُزْرَعُ فِي ٱلسَّلَامِ مِنَ ٱلَّذِينَ يَفْعَلُونَ ٱلسَّلَامَ.",
    "HEB.12.14": "اِتْبَعُوا ٱلسَّلَامَ مَعَ ٱلْجَمِيعِ، وَٱلْقَدَاسَةَ ٱلَّتِي بِدُونِهَا لَنْ يَرَى أَحَدٌ ٱلرَّبَّ،",
    "ISA.55.12": "لِأَنَّكُمْ بِفَرَحٍ تَخْرُجُونَ وَبِسَلَامٍ تُحْضَرُونَ. ٱلْجِبَالُ وَٱلْآكَامُ تُشِيدُ أَمَامَكُمْ تَرَنُّمًا، وَكُلُّ شَجَرِ ٱلْحَقْلِ تُصَفِّقُ بِٱلْأَيَادِي.",
    "PSA.37.11": "أَمَّا ٱلْوُدَعَاءُ فَيَرِثُونَ ٱلْأَرْضَ، وَيَتَلَذَّذُونَ فِي كَثْرَةِ ٱلسَّلَامَةِ.",
    "1PE.3.11": "لِيُعْرِضْ عَنِ ٱلشَّرِّ، وَيَصْنَعِ ٱلْخَيْرَ، لِيَطْلُبِ ٱلسَّلَامَ، وَيَجِدَّ فِي أَثَرِهِ.",
    "ROM.8.6": "لِأَنَّ ٱهْتِمَامَ ٱلْجَسَدِ هُوَ مَوْتٌ، وَلَكِنَّ ٱهْتِمَامَ ٱلرُّوحِ هُوَ حَيَاةٌ وَسَلَامٌ.",
    "PSA.122.6-7": "ٱسْأَلُوا سَلَامَةَ أُورُشَلِيمَ: «لِيَسْتَرِحْ مُحِبُّوكِ. لِيَكُنْ سَلَامٌ فِي أَبْرَاجِكِ، رَاحَةٌ فِي قُصُورِكِ».",
    "ISA.48.18": "لَيْتَكَ أَصْغَيْتَ لِوَصَايَايَ، فَكَانَ كَنَهْرٍ سَلَامُكَ وَبِرُّكَ كَلُجَجِ ٱلْبَحْرِ.",
    "ISA.40.29": "يُعْطِي ٱلْمُعْيِيَ قُدْرَةً، وَلِعَدِيمِ ٱلْقُوَّةِ يُكَثِّرُ شِدَّةً.",
    "PSA.46.1-2": "ٱللهُ لَنَا مَلْجَأٌ وَقُوَّةٌ. عَوْنًا فِي ٱلضِّيْقَاتِ وُجِدَ شَدِيدًا. لِذَلِكَ لَا نَخْشَى وَلَوْ تَزَحْزَحَتِ ٱلْأَرْضُ، وَلَوِ ٱنْقَلَبَتِ ٱلْجِبَالُ إِلَى قَلْبِ ٱلْبِحَارِ.",
    "EPH.6.10": "أَخِيرًا يَا إِخْوَتِي، تَقَوَّوْا فِي ٱلرَّبِّ وَفِي شِدَّةِ قُوَّتِهِ.",
    "2CO.12.9-10": "فَقَالَ لِي: «تَكْفِيكَ نِعْمَتِي، لِأَنَّ قُوَّتِي فِي ٱلضَّعْفِ تُكْمَلُ». فَبِكُلِّ سُرُورٍ أَفْتَخِرُ بِٱلْحَرِيِّ فِي ضَعَفَاتِي، لِكَيْ تَحِلَّ عَلَيَّ قُوَّةُ ٱلْمَسِيحِ. لِذَلِكَ أُسَرُّ بِٱلضَّعَفَاتِ وَٱلشَّتَائِمِ وَٱلضَّرُورَاتِ وَٱلِٱضْطِهَادَاتِ وَٱلضِّيقَاتِ لِأَجْلِ ٱلْمَسِيحِ. لِأَنِّي حِينَمَا أَنَا ضَعِيفٌ فَحِينَئِذٍ أَنَا قَوِيٌّ.",
    "1CO.16.13": "اِسْهَرُوا. ٱثْبُتُوا فِي ٱلْإِيمَانِ. كُونُوا رِجَالًا. تَقَوَّوْا.",
    "PSA.118.14": "قُوَّتِي وَتَرَنُّمِي ٱلرَّبُّ، وَقَدْ صَارَ لِي خَلَاصًا.",
    "PSA.138.3": "فِي يَوْمَ دَعَوْتُكَ أَجَبْتَنِي. شَجَّعْتَنِي قُوَّةً فِي نَفْسِي.",
    "PSA.105.4": "اُطْلُبُوا ٱلرَّبَّ وَقُدْرَتَهُ. ٱلْتَمِسُوا وَجْهَهُ دَائِمًا.",
    "PSA.119.28": "قَطَرَتْ نَفْسِي مِنَ ٱلْحُزْنِ. أَقِمْنِي حَسَبَ كَلَامِكَ.",
    "2SA.22.33": "ٱلْإِلَهُ ٱلَّذِي يُعَزِّزُنِي بِٱلْقُوَّةِ، وَيُصَيِّرُ طَرِيقِي كَامِلًا.",
    "PSA.59.17": "يَا قُوَّتِي لَكَ أُرَنِّمُ، لِأَنَّ ٱللهَ مَلْجَإِي، إِلَهُ رَحْمَتِي.",
    "EPH.3.16": "لِكَيْ يُعْطِيَكُمْ بِحَسَبِ غِنَى مَجْدِهِ، أَنْ تَتَأَيَّدُوا بِٱلْقُوَّةِ بِرُوحِهِ فِي ٱلْإِنْسَانِ ٱلْبَاطِنِ،",
    "ISA.66.13": "كَإِنْسَانٍ تُعَزِّيهِ أُمُّهُ هَكَذَا أُعَزِّيكُمْ أَنَا، وَفِي أُورُشَلِيمَ تُعَزَّوْنَ.",
    "MAT.5.4": "طُوبَى لِلْحَزَانَى، لِأَنَّهُمْ يَتَعَزَّوْنَ.",
    "PSA.119.50": "هَذِهِ هِيَ تَعْزِيَتِي فِي مَذَلَّتِي، لِأَنَّ قَوْلَكَ أَحْيَانِي.",
    "ISA.40.1": "عَزُّوا، عَزُّوا شَعْبِي، يَقُولُ إِلَهُكُمْ.",
    "1PE.5.7": "مُلْقِينَ كُلَّ هَمِّكُمْ عَلَيْهِ، لِأَنَّهُ هُوَ يَعْتَنِي بِكُمْ.",
    "ISA.49.13": "تَرَنَّمِي أَيَّتُهَا ٱلسَّمَاوَاتُ، وَٱبْتَهِجِي أَيَّتُهَا ٱلْأَرْضُ. لِتُشِدِ ٱلْجِبَالُ بِٱلتَّرَنُّمِ، لِأَنَّ ٱلرَّبَّ قَدْ عَزَّى شَعْبَهُ، وَعَلَى بَائِسِيهِ يَتَرَحَّمُ.",
    "PSA.119.76": "فَلْتَصِرْ رَحْمَتُكَ لِتَعْزِيَتِي، حَسَبَ قَوْلِكَ لِعَبْدِكَ.",
    "ISA.51.12": "«أَنَا أَنَا هُوَ مُعَزِّيكُمْ. مَنْ أَنْتِ حَتَّى تَخَافِي مِنْ إِنْسَانٍ يَمُوتُ، وَمِنِ ٱبْنِ ٱلْإِنْسَانِ ٱلَّذِي يُجْعَلُ كَٱلْعُشْبِ؟",
    "PSA.9.9": "وَيَكُونُ ٱلرَّبُّ مَلْجَأً لِلْمُنْسَحِقِ. مَلْجَأً فِي أَزْمِنَةِ ٱلضِّيقِ.",
    "JHN.14.18": "لَا أَتْرُكُكُمْ يَتَامَى. إِنِّي آتِي إِلَيْكُمْ.",
    "PSA.71.21": "تَزِيدُ عَظَمَتِي وَتَرْجِعُ فَتُعَزِّينِي.",
    "2TH.2.16-17": "وَرَبُّنَا نَفْسُهُ يَسُوعُ ٱلْمَسِيحُ، وَٱللهُ أَبُونَا ٱلَّذِي أَحَبَّنَا وَأَعْطَانَا عَزَاءً أَبَدِيًّا وَرَجَاءً صَالِحًا بِٱلنِّعْمَةِ، يُعَزِّي قُلُوبَكُمْ وَيُثَبِّتُكُمْ فِي كُلِّ كَلَامٍ وَعَمَلٍ صَالِحٍ.",
    "PSA.138.7": "إِنْ سَلَكْتُ فِي وَسَطِ ٱلضِّيْقِ تُحْيِنِي. عَلَى غَضَبِ أَعْدَائِي تَمُدُّ يَدَكَ، وَتُخَلِّصُنِي يَمِينُكَ.",
    "ISA.61.1-3": "رُوحُ ٱلسَّيِّدِ ٱلرَّبِّ عَلَيَّ، لِأَنَّ ٱلرَّبَّ مَسَحَنِي لِأُبَشِّرَ ٱلْمَسَاكِينَ، أَرْسَلَنِي لِأَعْصِبَ مُنْكَسِرِي ٱلْقَلْبِ، لِأُنَادِيَ لِلْمَسْبِيِّينَ بِٱلْعِتْقِ، وَلِلْمَأْسُورِينَ بِٱلْإِطْلَاقِ. لِأُنَادِيَ بِسَنَةٍ مَقْبُولَةٍ لِلرَّبِّ، وَبِيَوْمِ ٱنْتِقَامٍ لِإِلَهِنَا. لِأُعَزِّيَ كُلَّ ٱلنَّائِحِينَ. لِأَجْعَلَ لِنَائِحِي صِهْيَوْنَ، لِأُعْطِيَهُمْ جَمَالًا عِوَضًا عَنِ ٱلرَّمَادِ، وَدُهْنَ فَرَحٍ عِوَضًا عَنِ ٱلنَّوْحِ، وَرِدَاءَ تَسْبِيحٍ عِوَضًا عَنِ ٱلرُّوحِ ٱلْيَائِسَةِ، فَيُدْعَوْنَ أَشْجَارَ ٱلْبِرِّ، غَرْسَ ٱلرَّبِّ لِلتَّمْجِيدِ.",
    "PRO.3.13-14": "طُوبَى لِلْإِنْسَانِ ٱلَّذِي يَجِدُ ٱلْحِكْمَةَ، وَلِلرَّجُلِ ٱلَّذِي يَنَالُ ٱلْفَهْمَ، لِأَنَّ تِجَارَتَهَا خَيْرٌ مِنْ تِجَارَةِ ٱلْفِضَّةِ، وَرِبْحَهَا خَيْرٌ مِنَ ٱلذَّهَبِ ٱلْخَالِصِ.",
    "PRO.9.10": "بَدْءُ ٱلْحِكْمَةِ مَخَافَةُ ٱلرَّبِّ، وَمَعْرِفَةُ ٱلْقُدُّوسِ فَهْمٌ.",
    "PSA.111.10": "رَأْسُ ٱلْحِكْمَةِ مَخَافَةُ ٱلرَّبِّ. فِطْنَةٌ جَيِّدَةٌ لِكُلِّ عَامِلِيهَا. تَسْبِيحُهُ قَائِمٌ إِلَى ٱلْأَبَدِ.",
    "PRO.4.7": "ٱلْحِكْمَةُ هِيَ ٱلرَّأْسُ. فَٱقْتَنِ ٱلْحِكْمَةَ، وَبِكُلِّ مُقْتَنَاكَ ٱقْتَنِ ٱلْفَهْمَ.",
    "ECC.7.12": "لِأَنَّ ٱلَّذِي فِي ظِلِّ ٱلْحِكْمَةِ هُوَ فِي ظِلِّ ٱلْفِضَّةِ، وَفَضْلُ ٱلْمَعْرِفَةِ هُوَ إِنَّ ٱلْحِكْمَةَ تُحْيِي أَصْحَابَهَا.",
    "PRO.16.16": "قِنْيَةُ ٱلْحِكْمَةِ كَمْ هِيَ خَيْرٌ مِنَ ٱلذَّهَبِ، وَقِنْيَةُ ٱلْفَهْمِ تُخْتَارُ عَلَى ٱلْفِضَّةِ!",
    "JAS.3.17": "وَأَمَّا ٱلْحِكْمَةُ ٱلَّتِي مِنْ فَوْقُ فَهِيَ أَوَّلًا طَاهِرَةٌ، ثُمَّ مُسَالِمَةٌ، مُتَرَفِّقَةٌ، مُذْعِنَةٌ، مَمْلُوَّةٌ رَحْمَةً وَأَثْمَارًا صَالِحَةً، عَدِيمَةُ ٱلرَّيْبِ وَٱلرِّيَاءِ.",
    "PRO.11.2": "تَأْتِي ٱلْكِبْرِيَاءُ فَيَأْتِي ٱلْهَوَانُ، وَمَعَ ٱلْمُتَوَاضِعِينَ حِكْمَةٌ.",
    "PRO.12.15": "طَرِيقُ ٱلْجَاهِلِ مُسْتَقِيمٌ فِي عَيْنَيْهِ، أَمَّا سَامِعُ ٱلْمَشُورَةِ فَهُوَ حَكِيمٌ.",
    "PRO.19.20": "اِسْمَعِ ٱلْمَشُورَةَ وَٱقْبَلِ ٱلتَّأْدِيبَ، لِكَيْ تَكُونَ حَكِيمًا فِي آخِرَتِكَ.",
    "EPH.5.15-16": "فَٱنْظُرُوا كَيْفَ تَسْلُكُونَ بِٱلتَّدْقِيقِ، لَا كَجُهَلَاءَ بَلْ كَحُكَمَاءَ، مُفْتَدِينَ ٱلْوَقْتَ لِأَنَّ ٱلْأَيَّامَ شِرِّيرَةٌ.",
    "PRO.15.22": "مَقَاصِدُ بِغَيْرِ مَشُورَةٍ تَبْطُلُ، وَبِكَثْرَةِ ٱلْمُشِيرِينَ تَقُومُ.",
    "PRO.13.20": "اَلْمُسَايِرُ ٱلْحُكَمَاءَ يَصِيرُ حَكِيمًا، وَرَفِيقُ ٱلْجُهَّالِ يُضَرُّ.",
    "1CO.1.25": "لِأَنَّ جَهَالَةَ ٱللهِ أَحْكَمُ مِنَ ٱلنَّاسِ! وَضَعْفَ ٱللهِ أَقْوَى مِنَ ٱلنَّاسِ!",
    "PRO.18.15": "قَلْبُ ٱلْفَهِيمِ يَقْتَنِي مَعْرِفَةً، وَأُذُنُ ٱلْحُكَمَاءِ تَطْلُبُ عِلْمًا.",
    "PRO.24.3-4": "بِٱلْحِكْمَةِ يُبْنَى ٱلْبَيْتُ وَبِالْفَهْمِ يُثَبَّتُ، وَبِالْمَعْرِفَةِ تَمْتَلِئُ ٱلْمَخَادِعُ مِنْ كُلِّ ثَرْوَةٍ كَرِيمَةٍ وَنَفِيسَةٍ.",
    "COL.2.2-3": "لِكَيْ تَتَعَزَّى قُلُوبُهُمْ مُقْتَرِنَةً فِي ٱلْمَحَبَّةِ لِكُلِّ غِنَى يَقِينِ ٱلْفَهْمِ، لِمَعْرِفَةِ سِرِّ ٱللهِ ٱلْآبِ وَٱلْمَسِيحِ، ٱلْمُذَّخَرِ فِيهِ جَمِيعُ كُنُوزِ ٱلْحِكْمَةِ وَٱلْعِلْمِ.",
    "PRO.3.7": "لَا تَكُنْ حَكِيمًا فِي عَيْنَيْ نَفْسِكَ. ٱتَّقِ ٱلرَّبَّ وَٱبْعُدْ عَنِ ٱلشَّرِّ،",
    "PSA.119.98-100": "وَصِيَّتُكَ جَعَلَتْنِي أَحْكَمَ مِنْ أَعْدَائِي، لِأَنَّهَا إِلَى ٱلدَّهْرِ هِيَ لِي. أَكْثَرَ مِنْ كُلِّ مُعَلِّمِيَّ تَعَقَّلْتُ، لِأَنَّ شَهَادَاتِكَ هِيَ لَهَجِي. أَكْثَرَ مِنَ ٱلشُّيُوخِ فَطِنْتُ، لِأَنِّي حَفِظْتُ وَصَايَاكَ.",
    "PRO.17.27-28": "ذُو ٱلْمَعْرِفَةِ يُبْقِي كَلَامَهُ، وَذُو ٱلْفَهْمِ وَقُورُ ٱلرُّوحِ. بَلِ ٱلْأَحْمَقُ إِذَا سَكَتَ يُحْسَبُ حَكِيمًا، وَمَنْ ضَمَّ شَفَتَيْهِ فَهِيمًا.",
    "DAN.2.20-21": "أَجَابَ دَانِيآلُ وَقَالَ: «لِيَكُنِ ٱسْمُ ٱللهِ مُبَارَكًا مِنَ ٱلْأَزَلِ وَإِلَى ٱلْأَبَدِ، لِأَنَّ لَهُ ٱلْحِكْمَةَ وَٱلْجَبَرُوتَ. وَهُوَ يُغَيِّرُ ٱلْأَوْقَاتَ وَٱلْأَزْمِنَةَ. يَعْزِلُ مُلُوكًا وَيُنَصِّبُ مُلُوكًا. يُعْطِي ٱلْحُكَمَاءَ حِكْمَةً، وَيُعَلِّمُ ٱلْعَارِفِينَ فَهْمًا.",
    "PRO.14.29": "بَطِيءُ ٱلْغَضَبِ كَثِيرُ ٱلْفَهْمِ، وَقَصِيرُ ٱلرُّوحِ مُعَلِّي ٱلْحَمَقِ.",
    "JOB.28.28": "وَقَالَ لِلْإِنْسَانِ: هُوَذَا مَخَافَةُ ٱلرَّبِّ هِيَ ٱلْحِكْمَةُ، وَٱلْحَيَدَانُ عَنِ ٱلشَّرِّ هُوَ ٱلْفَهْمُ».",
    "EPH.5.20": "شَاكِرِينَ كُلَّ حِينٍ عَلَى كُلِّ شَيْءٍ فِي ٱسْمِ رَبِّنَا يَسُوعَ ٱلْمَسِيحِ، لِلهِ وَٱلْآبِ.",
    "PHP.4.6": "لَا تَهْتَمُّوا بِشَيْءٍ، بَلْ فِي كُلِّ شَيْءٍ بِٱلصَّلَاةِ وَٱلدُّعَاءِ مَعَ ٱلشُّكْرِ، لِتُعْلَمْ طِلْبَاتُكُمْ لَدَى ٱللهِ.",
    "PSA.95.1-2": "هَلُمَّ نُرَنِّمُ لِلرَّبِّ، نَهْتِفُ لِصَخْرَةِ خَلَاصِنَا. نَتَقَدَّمُ أَمَامَهُ بِحَمْدٍ، وَبِتَرْنِيمَاتٍ نَهْتِفُ لَهُ.",
    "PSA.9.1": "أَحْمَدُ ٱلرَّبَّ بِكُلِّ قَلْبِي. أُحَدِّثُ بِجَمِيعِ عَجَائِبِكَ.",
    "HEB.13.15": "فَلْنُقَدِّمْ بِهِ فِي كُلِّ حِينٍ لِلهِ ذَبِيحَةَ ٱلتَّسْبِيحِ، أَيْ ثَمَرَ شِفَاهٍ مُعْتَرِفَةٍ بِٱسْمِهِ.",
    "PSA.69.30": "أُسَبِّحُ ٱسْمَ ٱللهِ بِتَسْبِيحٍ، وَأُعَظِّمُهُ بِحَمْدٍ.",
    "2CO.9.15": "فَشُكْرًا لِلهِ عَلَى عَطِيَّتِهِ ٱلَّتِي لَا يُعَبَّرُ عَنْهَا.",
    "PSA.106.1": "هَلِّلُويَا. اِحْمَدُوا ٱلرَّبَّ لِأَنَّهُ صَالِحٌ، لِأَنَّ إِلَى ٱلْأَبَدِ رَحْمَتَهُ.",
    "PSA.92.1-2": "حَسَنٌ هُوَ ٱلْحَمْدُ لِلرَّبِّ وَٱلتَّرَنُّمُ لِٱسْمِكَ أَيُّهَا ٱلْعَلِيُّ. أَنْ يُخْبَرَ بِرَحْمَتِكَ فِي ٱلْغَدَاةِ، وَأَمَانَتِكَ كُلَّ لَيْلَةٍ،",
    "1TI.4.4-5": "لِأَنَّ كُلَّ خَلِيقَةِ ٱللهِ جَيِّدَةٌ، وَلَا يُرْفَضُ شَيْءٌ إِذَا أُخِذَ مَعَ ٱلشُّكْرِ، لِأَنَّهُ يُقَدَّسُ بِكَلِمَةِ ٱللهِ وَٱلصَّلَاةِ.",
    "PSA.34.1": "أُبَارِكُ ٱلرَّبَّ فِي كُلِّ حِينٍ. دَائِمًا تَسْبِيحُهُ فِي فَمِي.",
    "DAN.2.23": "إِيَّاكَ يَا إِلَهَ آبَائِي أَحْمَدُ، وَأُسَبِّحُ ٱلَّذِي أَعْطَانِي ٱلْحِكْمَةَ وَٱلْقُوَّةَ وَأَعْلَمَنِي ٱلْآنَ مَا طَلَبْنَاهُ مِنْكَ، لِأَنَّكَ أَعْلَمْتَنَا أَمْرَ ٱلْمَلِكِ».",
    "COL.4.2": "وَاظِبُوا عَلَى ٱلصَّلَاةِ سَاهِرِينَ فِيهَا بِٱلشُّكْرِ،",
    "PSA.118.28-29": "إِلَهِي أَنْتَ فَأَحْمَدُكَ، إِلَهِي فَأَرْفَعُكَ. ٱحْمَدُوا ٱلرَّبَّ لِأَنَّهُ صَالِحٌ، لِأَنَّ إِلَى ٱلْأَبَدِ رَحْمَتَهُ.",
    "ISA.12.4-5": "وَتَقُولُونَ فِي ذَلِكَ ٱلْيَوْمِ: «ٱحْمَدُوا ٱلرَّبَّ. ٱدْعُوا بِٱسْمِهِ. عَرِّفُوا بَيْنَ ٱلشُّعُوبِ بِأَفْعَالِهِ. ذَكِّرُوا بِأَنَّ ٱسْمَهُ قَدْ تَعَالَى. رَنِّمُوا لِلرَّبِّ لِأَنَّهُ قَدْ صَنَعَ مُفْتَخَرًا. لِيَكُنْ هَذَا مَعْرُوفًا فِي كُلِّ ٱلْأَرْضِ.",
    "PSA.145.1-3": "أَرْفَعُكَ يَا إِلَهِي ٱلْمَلِكَ، وَأُبَارِكُ ٱسْمَكَ إِلَى ٱلدَّهْرِ وَٱلْأَبَدِ. فِي كُلِّ يَوْمٍ أُبَارِكُكَ، وَأُسَبِّحُ ٱسْمَكَ إِلَى ٱلدَّهْرِ وَٱلْأَبَدِ. عَظِيمٌ هُوَ ٱلرَّبُّ وَحَمِيدٌ جِدًّا، وَلَيْسَ لِعَظَمَتِهِ ٱسْتِقْصَاءٌ.",
    "1CO.15.57": "وَلَكِنْ شُكْرًا لِلهِ ٱلَّذِي يُعْطِينَا ٱلْغَلَبَةَ بِرَبِّنَا يَسُوعَ ٱلْمَسِيحِ.",
    "PSA.30.11-12": "حَوَّلْتَ نَوْحِي إِلَى رَقْصٍ لِي. حَلَلْتَ مِسْحِي وَمَنْطَقْتَنِي فَرَحًا، لِكَيْ تَتَرَنَّمَ لَكَ رُوحِي وَلَا تَسْكُتَ. يَارَبُّ إِلَهِي، إِلَى ٱلْأَبَدِ أَحْمَدُكَ.",
    "REV.7.12": "قَائِلِينَ: «آمِينَ! ٱلْبَرَكَةُ وَٱلْمَجْدُ وَٱلْحِكْمَةُ وَٱلشُّكْرُ وَٱلْكَرَامَةُ وَٱلْقُدْرَةُ وَٱلْقُوَّةُ لِإِلَهِنَا إِلَى أَبَدِ ٱلْآبِدِينَ. آمِينَ!».",
    "PSA.103.12": "كَبُعْدِ ٱلْمَشْرِقِ مِنَ ٱلْمَغْرِبِ أَبْعَدَ عَنَّا مَعَاصِيَنَا.",
    "COL.3.13": "مُحْتَمِلِينَ بَعْضُكُمْ بَعْضًا، وَمُسَامِحِينَ بَعْضُكُمْ بَعْضًا. إِنْ كَانَ لِأَحَدٍ عَلَى أَحَدٍ شَكْوَى، كَمَا غَفَرَ لَكُمُ ٱلْمَسِيحُ هَكَذَا أَنْتُمْ أَيْضًا.",
    "MAT.6.14-15": "فَإِنَّهُ إِنْ غَفَرْتُمْ لِلنَّاسِ زَلَّاتِهِمْ، يَغْفِرْ لَكُمْ أَيْضًا أَبُوكُمُ ٱلسَّمَاوِيُّ. وَإِنْ لَمْ تَغْفِرُوا لِلنَّاسِ زَلَّاتِهِمْ، لَا يَغْفِرْ لَكُمْ أَبُوكُمْ أَيْضًا زَلَّاتِكُمْ.",
    "PSA.32.1-2": "طُوبَى لِلَّذِي غُفِرَ إِثْمُهُ وَسُتِرَتْ خَطِيَّتُهُ. طُوبَى لِرَجُلٍ لَا يَحْسِبُ لَهُ ٱلرَّبُّ خَطِيَّةً، وَلَا فِي رُوحِهِ غِشٌّ.",
    "LUK.6.37": "«وَلَا تَدِينُوا فَلَا تُدَانُوا. لَا تَقْضُوا عَلَى أَحَدٍ فَلَا يُقْضَى عَلَيْكُمْ. اِغْفِرُوا يُغْفَرْ لَكُمْ.",
    "ACT.3.19": "فَتُوبُوا وَٱرْجِعُوا لِتُمْحَى خَطَايَاكُمْ، لِكَيْ تَأْتِيَ أَوْقَاتُ ٱلْفَرَجِ مِنْ وَجْهِ ٱلرَّبِّ.",
    "HEB.8.12": "لِأَنِّي أَكُونُ صَفُوحًا عَنْ آثَامِهِمْ، وَلَا أَذْكُرُ خَطَايَاهُمْ وَتَعَدِّيَاتِهِمْ فِي مَا بَعْدُ».",
    "EPH.1.7": "ٱلَّذِي فِيهِ لَنَا ٱلْفِدَاءُ بِدَمِهِ، غُفْرَانُ ٱلْخَطَايَا، حَسَبَ غِنَى نِعْمَتِهِ،",
    "ISA.43.25": "أَنَا أَنَا هُوَ ٱلْمَاحِي ذُنُوبَكَ لِأَجْلِ نَفْسِي، وَخَطَايَاكَ لَا أَذْكُرُهَا».",
    "MRK.11.25": "وَمَتَى وَقَفْتُمْ تُصَلُّونَ، فَٱغْفِرُوا إِنْ كَانَ لَكُمْ عَلَى أَحَدٍ شَيْءٌ، لِكَيْ يَغْفِرَ لَكُمْ أَيْضًا أَبُوكُمُ ٱلَّذِي فِي ٱلسَّمَاوَاتِ زَلَّاتِكُمْ.",
    "PSA.51.1-2": "اِرْحَمْنِي يَا ٱللهُ حَسَبَ رَحْمَتِكَ. حَسَبَ كَثْرَةِ رَأْفَتِكَ ٱمْحُ مَعَاصِيَّ. ٱغْسِلْنِي كَثِيرًا مِنْ إِثْمِي، وَمِنْ خَطِيَّتِي طَهِّرْنِي.",
    "LUK.23.34": "فَقَالَ يَسُوعُ: «يَا أَبَتَاهُ، ٱغْفِرْ لَهُمْ، لِأَنَّهُمْ لَا يَعْلَمُونَ مَاذَا يَفْعَلُونَ». وَإِذِ ٱقْتَسَمُوا ثِيَابَهُ ٱقْتَرَعُوا عَلَيْهَا.",
    "PSA.130.3-4": "إِنْ كُنْتَ تُرَاقِبُ ٱلْآثَامَ يَارَبُّ، يَا سَيِّدُ، فَمَنْ يَقِفُ؟ لِأَنَّ عِنْدَكَ ٱلْمَغْفِرَةَ. لِكَيْ يُخَافَ مِنْكَ.",
    "ROM.5.20": "وَأَمَّا ٱلنَّامُوسُ فَدَخَلَ لِكَيْ تَكْثُرَ ٱلْخَطِيَّةُ. وَلَكِنْ حَيْثُ كَثُرَتِ ٱلْخَطِيَّةُ ٱزْدَادَتِ ٱلنِّعْمَةُ جِدًّا.",
    "MAT.18.21-22": "حِينَئِذٍ تَقَدَّمَ إِلَيْهِ بُطْرُسُ وَقَالَ: «يَارَبُّ، كَمْ مَرَّةً يُخْطِئُ إِلَيَّ أَخِي وَأَنَا أَغْفِرُ لَهُ؟ هَلْ إِلَى سَبْعِ مَرَّاتٍ؟». قَالَ لَهُ يَسُوعُ: «لَا أَقُولُ لَكَ إِلَى سَبْعِ مَرَّاتٍ، بَلْ إِلَى سَبْعِينَ مَرَّةً سَبْعَ مَرَّاتٍ.",
    "HEB.4.16": "فَلْنَتَقَدَّمْ بِثِقَةٍ إِلَى عَرْشِ ٱلنِّعْمَةِ لِكَيْ نَنَالَ رَحْمَةً وَنَجِدَ نِعْمَةً عَوْنًا فِي حِينِهِ.",
    "PRO.28.13": "مَنْ يَكْتُمُ خَطَايَاهُ لَا يَنْجَحُ، وَمَنْ يُقِرُّ بِهَا وَيَتْرُكُهَا يُرْحَمُ.",
    "ISA.55.7": "لِيَتْرُكِ ٱلشِّرِّيرُ طَرِيقَهُ، وَرَجُلُ ٱلْإِثْمِ أَفْكَارَهُ، وَلْيَتُبْ إِلَى ٱلرَّبِّ فَيَرْحَمَهُ، وَإِلَى إِلَهِنَا لِأَنَّهُ يُكْثِرُ ٱلْغُفْرَانَ.",
    "DAN.9.9": "لِلرَّبِّ إِلَهِنَا ٱلْمَرَاحِمُ وَٱلْمَغْفِرَةُ، لِأَنَّنَا تَمَرَّدْنَا عَلَيْهِ.",
    "1TH.5.17": "صَلُّوا بِلَا ٱنْقِطَاعٍ.",
    "MAT.6.6": "وَأَمَّا أَنْتَ فَمَتَى صَلَّيْتَ فَٱدْخُلْ إِلَى مِخْدَعِكَ وَأَغْلِقْ بَابَكَ، وَصَلِّ إِلَى أَبِيكَ ٱلَّذِي فِي ٱلْخَفَاءِ. فَأَبُوكَ ٱلَّذِي يَرَى فِي ٱلْخَفَاءِ يُجَازِيكَ عَلَانِيَةً.",
    "ROM.8.26": "وَكَذَلِكَ ٱلرُّوحُ أَيْضًا يُعِينُ ضَعَفَاتِنَا، لِأَنَّنَا لَسْنَا نَعْلَمُ مَا نُصَلِّي لِأَجْلِهِ كَمَا يَنْبَغِي. وَلَكِنَّ ٱلرُّوحَ نَفْسَهُ يَشْفَعُ فِينَا بِأَنَّاتٍ لَا يُنْطَقُ بِهَا.",
    "MAT.6.9-10": "«فَصَلُّوا أَنْتُمْ هَكَذَا: أَبَانَا ٱلَّذِي فِي ٱلسَّمَاوَاتِ، لِيَتَقَدَّسِ ٱسْمُكَ. لِيَأْتِ مَلَكُوتُكَ. لِتَكُنْ مَشِيئَتُكَ كَمَا فِي ٱلسَّمَاءِ كَذَلِكَ عَلَى ٱلْأَرْضِ.",
    "PSA.17.6": "أَنَا دَعَوْتُكَ لِأَنَّكَ تَسْتَجِيبُ لِي يَا ٱللهُ. أَمِلْ أُذُنَيْكَ إِلَيَّ. ٱسْمَعْ كَلَامِي.",
    "LUK.11.9-10": "وَأَنَا أَقُولُ لَكُمُ: ٱسْأَلُوا تُعْطَوْا، اُطْلُبُوا تَجِدُوا، اِقْرَعُوا يُفْتَحْ لَكُمْ. لِأَنَّ كُلَّ مَنْ يَسْأَلُ يَأْخُذُ، وَمَنْ يَطْلُبُ يَجِدُ، وَمَنْ يَقْرَعُ يُفْتَحُ لَهُ.",
    "PSA.34.17": "أُولَئِكَ صَرَخُوا، وَٱلرَّبُّ سَمِعَ، وَمِنْ كُلِّ شَدَائِدِهِمْ أَنْقَذَهُمْ.",
    "EPH.6.18": "مُصَلِّينَ بِكُلِّ صَلَاةٍ وَطِلْبَةٍ كُلَّ وَقْتٍ فِي ٱلرُّوحِ، وَسَاهِرِينَ لِهَذَا بِعَيْنِهِ بِكُلِّ مُواظَبَةٍ وَطِلْبَةٍ، لِأَجْلِ جَمِيعِ ٱلْقِدِّيسِينَ،",
    "MAT.18.19-20": "وَأَقُولُ لَكُمْ أَيْضًا: إِنِ ٱتَّفَقَ ٱثْنَانِ مِنْكُمْ عَلَى ٱلْأَرْضِ فِي أَيِّ شَيْءٍ يَطْلُبَانِهِ فَإِنَّهُ يَكُونُ لَهُمَا مِنْ قِبَلِ أَبِي ٱلَّذِي فِي ٱلسَّمَاوَاتِ، لِأَنَّهُ حَيْثُمَا ٱجْتَمَعَ ٱثْنَانِ أَوْ ثَلَاثَةٌ بِٱسْمِي فَهُنَاكَ أَكُونُ فِي وَسْطِهِمْ».",
    "PSA.55.17": "مَسَاءً وَصَبَاحًا وَظُهْرًا أَشْكُو وَأَنُوحُ، فَيَسْمَعُ صَوْتِي.",
    "PSA.66.19-20": "لَكِنْ قَدْ سَمِعَ ٱللهُ. أَصْغَى إِلَى صَوْتِ صَلَاتِي. مُبَارَكٌ ٱللهُ، ٱلَّذِي لَمْ يُبْعِدْ صَلَاتِي وَلَا رَحْمَتَهُ عَنِّي.",
    "MAT.26.41": "اِسْهَرُوا وَصَلُّوا لِئَلَّا تَدْخُلُوا فِي تَجْرِبَةٍ. أَمَّا ٱلرُّوحُ فَنَشِيطٌ وَأَمَّا ٱلْجَسَدُ فَضَعِيفٌ».",
    "PSA.5.3": "يَارَبُّ، بِٱلْغَدَاةِ تَسْمَعُ صَوْتِي. بِٱلْغَدَاةِ أُوَجِّهُ صَلَاتِي نَحْوَكَ وَأَنْتَظِرُ.",
    "JHN.14.13-14": "وَمَهْمَا سَأَلْتُمْ بِٱسْمِي فَذَلِكَ أَفْعَلُهُ لِيَتَمَجَّدَ ٱلْآبُ بِٱلِٱبْنِ. إِنْ سَأَلْتُمْ شَيْئًا بِٱسْمِي فَإِنِّي أَفْعَلُهُ.",
    "JHN.15.7": "إِنْ ثَبَتُّمْ فِيَّ وَثَبَتَ كَلَامِي فِيكُمْ تَطْلُبُونَ مَا تُرِيدُونَ فَيَكُونُ لَكُمْ.",
    "PSA.141.2": "لِتَسْتَقِمْ صَلَاتِي كَٱلْبَخُورِ قُدَّامَكَ. لِيَكُنْ رَفْعُ يَدَيَّ كَذَبِيحَةٍ مَسَائِيَّةٍ.",
    "1TI.2.1-2": "فَأَطْلُبُ أَوَّلَ كُلِّ شَيْءٍ، أَنْ تُقَامَ طَلِبَاتٌ وَصَلَوَاتٌ وَٱبْتِهَالَاتٌ وَتَشَكُّرَاتٌ لِأَجْلِ جَمِيعِ ٱلنَّاسِ، لِأَجْلِ ٱلْمُلُوكِ وَجَمِيعِ ٱلَّذِينَ هُمْ فِي مَنْصِبٍ، لِكَيْ نَقْضِيَ حَيَاةً مُطْمَئِنَّةً هَادِئَةً فِي كُلِّ تَقْوَى وَوَقَارٍ،",
    "LUK.18.1": "وَقَالَ لَهُمْ أَيْضًا مَثَلًا فِي أَنَّهُ يَنْبَغِي أَنْ يُصَلَّى كُلَّ حِينٍ وَلَا يُمَلَّ،",
    "PSA.102.17": "ٱلْتَفَتَ إِلَى صَلَاةِ ٱلْمُضْطَرِّ، وَلَمْ يَرْذُلْ دُعَاءَهُمْ.",
    "JHN.15.11": "كَلَّمْتُكُمْ بِهَذَا لِكَيْ يَثْبُتَ فَرَحِي فِيكُمْ وَيُكْمَلَ فَرَحُكُمْ.",
    "JAS.1.2-3": "اِحْسِبُوهُ كُلَّ فَرَحٍ يَا إِخْوَتِي حِينَمَا تَقَعُونَ فِي تَجَارِبَ مُتَنَوِّعَةٍ، عَالِمِينَ أَنَّ ٱمْتِحَانَ إِيمَانِكُمْ يُنْشِئُ صَبْرًا.",
    "PSA.126.5-6": "ٱلَّذِينَ يَزْرَعُونَ بِٱلدُّمُوعِ يَحْصُدُونَ بِٱلِٱبْتِهَاجِ. ٱلذَّاهِبُ ذَهَابًا بِٱلْبُكَاءِ حَامِلًا مِبْذَرَ ٱلزَّرْعِ، مَجِيئًا يَجِيءُ بِٱلتَّرَنُّمِ حَامِلًا حُزَمَهُ.",
    "1PE.1.8-9": "ٱلَّذِي وَإِنْ لَمْ تَرَوْهُ تُحِبُّونَهُ. ذَلِكَ وَإِنْ كُنْتُمْ لَا تَرَوْنَهُ ٱلْآنَ لَكِنْ تُؤْمِنُونَ بِهِ، فَتَبْتَهِجُونَ بِفَرَحٍ لَا يُنْطَقُ بِهِ وَمَجِيدٍ، نَائِلِينَ غَايَةَ إِيمَانِكُمْ خَلَاصَ ٱلنُّفُوسِ.",
    "PSA.5.11": "وَيَفْرَحُ جَمِيعُ ٱلْمُتَّكِلِينَ عَلَيْكَ. إِلَى ٱلْأَبَدِ يَهْتِفُونَ، وَتُظَلِّلُهُمْ. وَيَبْتَهِجُ بِكَ مُحِبُّو ٱسْمِكَ.",
    "JHN.16.22": "فَأَنْتُمْ كَذَلِكَ، عِنْدَكُمُ ٱلْآنَ حُزْنٌ. وَلَكِنِّي سَأَرَاكُمْ أَيْضًا فَتَفْرَحُ قُلُوبُكُمْ، وَلَا يَنْزِعُ أَحَدٌ فَرَحَكُمْ مِنْكُمْ",
    "ISA.61.10": "فَرَحًا أَفْرَحُ بِٱلرَّبِّ. تَبْتَهِجُ نَفْسِي بِإِلَهِي، لِأَنَّهُ قَدْ أَلْبَسَنِي ثِيَابَ ٱلْخَلَاصِ. كَسَانِي رِدَاءَ ٱلْبِرِّ، مِثْلَ عَرِيسٍ يَتَزَيَّنُ بِعِمَامَةٍ، وَمِثْلَ عَرُوسٍ تَتَزَيَّنُ بِحُلِيِّهَا.",
    "PSA.100.1-2": "اِهْتِفِي لِلرَّبِّ يَا كُلَّ ٱلْأَرْضِ. ٱعْبُدُوا ٱلرَّبَّ بِفَرَحٍ. ٱدْخُلُوا إِلَى حَضْرَتِهِ بِتَرَنُّمٍ.",
    "PSA.32.11": "ٱفْرَحُوا بِٱلرَّبِّ وَٱبْتَهِجُوا يَا أَيُّهَا ٱلصِّدِّيقُونَ، وَٱهْتِفُوا يَا جَمِيعَ ٱلْمُسْتَقِيمِي ٱلْقُلُوبِ.",
    "1TH.5.16": "ٱفْرَحُوا كُلَّ حِينٍ.",
    "PSA.51.12": "رُدَّ لِي بَهْجَةَ خَلَاصِكَ، وَبِرُوحٍ مُنْتَدِبَةٍ ٱعْضُدْنِي.",
    "ISA.12.3": "فَتَسْتَقُونَ مِيَاهًا بِفَرَحٍ مِنْ يَنَابِيعِ ٱلْخَلَاصِ.",
    "PSA.47.1": "يَا جَمِيعَ ٱلْأُمَمِ صَفِّقُوا بِٱلْأَيَادِي. ٱهْتِفُوا لِلهِ بِصَوْتِ ٱلِٱبْتِهَاجِ.",
    "LUK.15.10": "هَكَذَا، أَقُولُ لَكُمْ: يَكُونُ فَرَحٌ قُدَّامَ مَلَائِكَةِ ٱللهِ بِخَاطِئٍ وَاحِدٍ يَتُوبُ.",
    "PSA.97.11-12": "نُورٌ قَدْ زُرِعَ لِلصِّدِّيقِ، وَفَرَحٌ لِلْمُسْتَقِيمِي ٱلْقَلْبِ. ٱفْرَحُوا أَيُّهَا ٱلصِّدِّيقُونَ بِٱلرَّبِّ، وَٱحْمَدُوا ذِكْرَ قُدْسِهِ.",
    "JHN.16.24": "إِلَى ٱلْآنَ لَمْ تَطْلُبُوا شَيْئًا بِٱسْمِي. اُطْلُبُوا تَأْخُذُوا، لِيَكُونَ فَرَحُكُمْ كَامِلًا."
};
